window.ANSWER_TERMS = {"ATP":{"match":"adenosinetrifosfaat|adenosine trifosfaat|adenosine-trifosfaat|ATP","title":"ATP (adenosinetrifosfaat)","short":"ATP is de energiemunt van de cel: bij afsplitsing van de derde fosfaatgroep komt energie vrij die transport, contractie en biosynthese aandrijft.","definition":"<p><strong>ATP</strong> (adenosinetrifosfaat) bestaat uit adenine, ribose en drie fosfaatgroepen. Hydrolyse van de eindstandige fosfaatbinding (ATP → ADP + P<sub>i</sub>) levert ongeveer 30 kJ/mol — genoeg om ongunstige reacties te koppelen aan een gunstige: spiercontractie, de Na⁺/K⁺-ATPase, en de opbouw van eiwitten, vetten en DNA.</p><p>Het meeste ATP komt uit de <em>oxidatieve fosforylering</em> in het mitochondrion: de elektronentransportketen pompt protonen naar de intermembraanruimte, en ATP-synthase laat die protonengradiënt terugstromen en maakt daarmee ATP (chemiosmose). Glycolyse en de citroenzuurcyclus leveren daarnaast rechtstreeks een kleine hoeveelheid.</p><p>De cel slaat ATP nauwelijks op — de voorraad gaat in seconden — dus productie en verbruik zijn strak gekoppeld: veel ADP versnelt de verbranding, overmaat ATP remt die af.</p>","image_url":"","wiki_titles":["Adenosine triphosphate","ATP synthase"]},"mitochondrion":{"title":"Mitochondrion","short":"De 'energiecentrale' van de cel; produceert ATP via de citroenzuurcyclus en oxidatieve fosforylering.","definition":"<p>Het <b>mitochondrion</b> heeft een dubbele membraan; de binnenste is sterk geplooid (cristae). Hier vinden de citroenzuurcyclus en de elektronentransportketen plaats.</p><p>Zo levert het mitochondrion het grootste deel van de ATP van de cel. Het bevat eigen DNA en kan zich delen.</p>","image_url":"","wiki_title":"Mitochondrion","match":"mitochondrion|mitochondriën|mitochondrien|mitochondria|mitochondrium"},"microtubuli":{"title":"Microtubuli","short":"Holle buisjes van tubuline; het stevigste onderdeel van het cytoskelet, sporen voor transport en de mitosespoel.","definition":"<p><b>Microtubuli</b> zijn holle buisjes opgebouwd uit tubuline-dimeren. Ze zijn dynamisch: ze groeien en krimpen aan hun uiteinden.</p><p>Ze geven de cel structuur, vormen de rails voor de motoreiwitten kinesine en dyneïne, en bouwen tijdens de celdeling de mitosespoel.</p>","image_url":"","wiki_title":"Microtubule","match":"microtubuli|microtubulus"},"endocriene signalering":{"title":"Endocriene signalering","short":"Klieren geven hormonen af aan het bloed, dat ze naar verre doelorganen vervoert.","definition":"<p>Bij <b>endocriene signalering</b> scheiden endocriene klieren hormonen rechtstreeks in de bloedbaan uit.</p><p>Via het bloed bereiken de hormonen doelcellen elders in het lichaam die de bijbehorende receptor dragen. Het effect is trager maar wijdverbreid.</p>","image_url":"","wiki_title":"Endocrine system","match":"endocriene signalering|endocrien|endocriene secretie|endocriene celsignalering"},"glycoproteine":{"title":"Glycoproteïne","short":"Eiwit met aangehechte suikerketens; veel membraan- en secretie-eiwitten zijn geglycosyleerd.","definition":"<p>Een <b>glycoproteïne</b> is een eiwit waaraan tijdens de rijping in ER en Golgi suikerketens zijn gekoppeld (glycosylering).</p><p>Ze zitten veel in de celmembraan en in secreten en spelen een rol bij herkenning, adhesie en bescherming.</p>","image_url":"","wiki_title":"Glycoprotein","match":"glycoproteïne|glycoproteine|glycoproteïnen|glycoproteinen|glycoproteinen"},"cholesterol":{"title":"Cholesterol","short":"Vetachtige stof die de celmembraan stevigheid en de juiste vloeibaarheid geeft en grondstof is voor steroïden.","definition":"<p><b>Cholesterol</b> is een steroïd dat tussen de fosfolipiden van de celmembraan zit en de membraanvloeibaarheid stabiliseert.</p><p>Het is bovendien de grondstof voor steroïdhormonen, vitamine D en galzouten.</p>","image_url":"","wiki_title":"Cholesterol","match":"cholesterol"},"necrose":{"title":"Necrose","short":"Ongecontroleerde celdood door schade, waarbij de cel opzwelt, openbarst en een ontstekingsreactie uitlokt.","definition":"<p><b>Necrose</b> is celdood door acute schade (zuurstoftekort, toxinen, trauma). De cel zwelt op en de membraan scheurt.</p><p>De vrijkomende celinhoud lokt een ontstekingsreactie uit — anders dan bij de 'nette' apoptose.</p>","image_url":"","wiki_title":"Necrosis","match":"necrose"},"pyruvaat":{"title":"Pyruvaat","short":"Eindproduct van de glycolyse; gaat bij zuurstof over in acetyl-CoA, zonder zuurstof in lactaat.","definition":"<p><b>Pyruvaat</b> (pyrodruivenzuur) is het eindproduct van de glycolyse.</p><p>Met zuurstof wordt het in het mitochondrion omgezet tot acetyl-CoA voor de citroenzuurcyclus; zonder zuurstof wordt het via gisting lactaat.</p>","image_url":"","wiki_title":"Pyruvic acid","match":"pyruvaat|pyrodruivenzuur"},"neutrofiele granulocyt":{"title":"Neutrofiele granulocyt","short":"Meest voorkomende witte bloedcel en eerste verdedigingslinie tegen bacteriën via fagocytose.","definition":"<p>De <b>neutrofiele granulocyt</b> is de talrijkste leukocyt, met een gelobde kern, en als eerste ter plaatse bij een bacteriële infectie.</p><p>Hij ruimt bacteriën op door fagocytose en enzymen; dode neutrofielen vormen samen met bacterieresten de pus.</p>","image_url":"","wiki_title":"Neutrophil","match":"neutrofiele granulocyt|neutrofiele granulocyten"},"macrofaag":{"title":"Macrofaag","short":"Grote fagocyt in de weefsels die pathogenen en celresten opruimt en antigenen presenteert.","definition":"<p>De <b>macrofaag</b> ontstaat uit een monocyt die het weefsel is binnengegaan. Hij fagocyteert bacteriën, dode cellen en afval.</p><p>Als antigeenpresenterende cel activeert hij ook T-cellen en scheidt hij ontstekingsmediatoren uit. In de huid heten verwante cellen histiocyten.</p>","image_url":"","wiki_title":"Macrophage","match":"macrofaag|macrofagen"},"lymfocyt":{"title":"Lymfocyt","short":"Witte bloedcel van de specifieke afweer; omvat de B-cellen (antistoffen) en T-cellen.","definition":"<p>De <b>lymfocyt</b> is de sleutelcel van het adaptieve (specifieke) immuunsysteem. B-lymfocyten maken antistoffen; T-lymfocyten doden geïnfecteerde cellen of sturen de afweer aan.</p><p>Lymfocyten circuleren tussen bloed, lymfe en lymfoïde organen.</p>","image_url":"","wiki_title":"Lymphocyte","match":"lymfocyt|lymfocyten"},"milt":{"title":"Milt","short":"Lymfoïd orgaan dat oude bloedcellen afbreekt en bloedgedragen ziekteverwekkers filtert.","definition":"<p>De <b>milt</b> filtert het bloed: de rode pulpa ruimt versleten erytrocyten op, de witte pulpa herbergt lymfocyten voor de afweer tegen bloedgedragen pathogenen.</p><p>Ook dient de milt als bloedreservoir.</p>","image_url":"","wiki_title":"Spleen","match":"milt"},"beenmerg":{"title":"Beenmerg","short":"Weefsel in de holten van botten waar alle bloedcellen worden gevormd (hematopoëse).","definition":"<p>Het <b>beenmerg</b> vult de holten van botten. In het rode beenmerg vindt de hematopoëse plaats: de vorming van rode en witte bloedcellen en bloedplaatjes uit stamcellen.</p><p>Het is tevens de plaats waar B-lymfocyten uitrijpen.</p>","image_url":"","wiki_title":"Bone marrow","match":"beenmerg|het beenmerg"},"lymfeklier":{"title":"Lymfeklier","short":"Filterstation in de lymfebaan waar antigenen worden gepresenteerd en de afweerreactie op gang komt.","definition":"<p>De <b>lymfeklier</b> filtert de lymfe en is een ontmoetingsplaats voor antigeenpresenterende cellen en lymfocyten.</p><p>Hier worden T- en B-cellen geactiveerd; bij infectie zwellen lymfeklieren op doordat de lymfocyten zich vermenigvuldigen.</p>","image_url":"","wiki_title":"Lymph node","match":"lymfeklier|lymfeklieren|lymfklier|lymfklieren"},"plaque":{"title":"Plaque","short":"Verheven, plateauvormige huidafwijking groter dan ~1 cm, vaak door samenvloeien van papels.","definition":"<p>Een <b>plaque</b> is een verheven, afgeplatte laesie groter dan ongeveer 1 cm — breder dan hoog.</p><p>Ze ontstaat vaak door het samenvloeien van papels en is typisch voor psoriasis.</p>","image_url":"","wiki_title":"Skin condition","match":"plaque|plaques"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"urtica":{"title":"Urtica","short":"Vluchtige, jeukende, verheven zwelling van de huid — een 'galbult' of kwaddel.","definition":"<p>Een <b>urtica</b> (kwaddel, galbult) is een verheven, bleekroze zwelling door vochtophoping in de dermis, meestal sterk jeukend.</p><p>Ze ontstaat door histamine-afgifte (netelroos/urticaria) en verdwijnt doorgaans binnen 24 uur weer.</p>","image_url":"","wiki_title":"Hives","match":"urtica|urticae"},"erosie":{"title":"Erosie","short":"Oppervlakkig huiddefect beperkt tot de epidermis, dat zonder litteken geneest.","definition":"<p>Een <b>erosie</b> is een oppervlakkig verlies van epidermis, bijvoorbeeld nadat een blaasje is opengegaan.</p><p>Omdat de dermis intact blijft, geneest een erosie zonder litteken.</p>","image_url":"","wiki_title":"Erosion (dermatology)","match":"erosie|erosies"},"ulcus":{"title":"Ulcus","short":"Diep huiddefect tot in de dermis of dieper, dat met een litteken geneest (een 'zweer').","definition":"<p>Een <b>ulcus</b> (zweer) is een dieper weefselverlies dat tot in de dermis of subcutis reikt.</p><p>Doordat de dermis is aangetast, geneest het met littekenvorming. Een ulcus cruris (open been) is een bekend voorbeeld.</p>","image_url":"","wiki_title":"Ulcer (dermatology)","match":"ulcus|ulcera"},"fissuur":{"title":"Fissuur","short":"Pijnlijke, spleetvormige scheur in de huid, vaak op handen of hielen (kloof/rhagade).","definition":"<p>Een <b>fissuur</b> (rhagade, kloof) is een smalle, spleetvormige scheur in de huid die tot in de dermis kan reiken.</p><p>Ze ontstaat vooral in droge, verdikte huid op belaste plaatsen zoals vingers, handen en hielen, en kan pijnlijk zijn.</p>","image_url":"","wiki_title":"Fissure","match":"fissuur|rhagade|rhagaden|kloof"},"atrofie":{"title":"Atrofie","short":"Verdunning of afname van weefsel; bij de huid een dunnere, kwetsbaardere epidermis en/of dermis.","definition":"<p><b>Atrofie</b> is het slinken van een weefsel of orgaan doordat de cellen krimpen of in aantal afnemen.</p><p>Huidatrofie (bijv. na langdurig sterk corticosteroïdgebruik of door veroudering) geeft een dunne, doorschijnende, kwetsbare huid.</p>","image_url":"","wiki_title":"Atrophy","match":"atrofie"},"plaveiselcelcarcinoom":{"title":"Plaveiselcelcarcinoom","short":"Op één na meest voorkomende huidkanker, uit keratinocyten; kan uitzaaien.","definition":"<p>Het <b>plaveiselcelcarcinoom</b> gaat uit van de keratinocyten van de epidermis en is de op één na meest voorkomende huidkanker.</p><p>Anders dan het basaalcelcarcinoom kan het metastaseren. Het ontstaat vooral op zonbeschadigde huid, vaak vanuit een actinische keratose.</p>","image_url":"","wiki_title":"Squamous-cell carcinoma","match":"plaveiselcelcarcinoom|plaveiselcel carcinoom"},"hemangioom":{"title":"Hemangioom","short":"Goedaardige tumor van bloedvaten; als 'aardbeivlek' een veelvoorkomende rode zwelling bij baby's.","definition":"<p>Een <b>hemangioom</b> is een goedaardige woekering van bloedvaten.</p><p>Het infantiele hemangioom ('aardbeivlek') groeit in de eerste levensmaanden en verdwijnt daarna meestal vanzelf weer.</p>","image_url":"","wiki_title":"Hemangioma","match":"hemangioom|hemangiomen"},"radiotherapie":{"title":"Radiotherapie","short":"Behandeling met ioniserende straling die het DNA van tumorcellen beschadigt.","definition":"<p><b>Radiotherapie</b> (bestraling) gebruikt ioniserende straling om het DNA van kankercellen zodanig te beschadigen dat ze afsterven.</p><p>In de dermatologie is het een alternatief voor chirurgie bij bijvoorbeeld basaal- en plaveiselcelcarcinomen, vooral bij oudere patiënten of moeilijke locaties.</p>","image_url":"","wiki_title":"Radiation therapy","match":"radiotherapie"},"autosomaal dominant":{"title":"Autosomaal dominant","short":"Overervingspatroon waarbij één afwijkend gen (op een niet-geslachtschromosoom) al ziekte geeft.","definition":"<p>Bij <b>autosomaal dominante</b> overerving volstaat één gemuteerd allel op een autosoom om de aandoening tot uiting te laten komen.</p><p>Aangedane ouders geven het gemiddeld aan de helft van hun kinderen door; de aandoening komt in elke generatie voor, ongeacht geslacht.</p>","image_url":"","wiki_title":"Dominance (genetics)","match":"autosomaal dominant"},"pneumonie":{"title":"Pneumonie","short":"Een pneumonie is een infectie van het longweefsel (alveoli), meestal door bacteriën of virussen, met koorts, hoesten en kortademigheid.","definition":"<p>Bij een <strong>pneumonie</strong> (longontsteking) raken de alveoli ontstoken en vullen ze zich met ontstekingsvocht en cellen. Daardoor is minder longoppervlak beschikbaar voor gaswisseling.</p><p>Typische klachten zijn koorts, hoesten (vaak met sputum), kortademigheid en soms pijn bij het ademen. Bij lichamelijk onderzoek kunnen crepitaties of een gedempte percussie optreden; een X-thorax toont een infiltraat. De meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie is <em>Streptococcus pneumoniae</em>.</p>","image_url":"","wiki_title":"Pneumonia","match":"pneumonie|longontsteking","option_only":true},"norovirus":{"title":"Norovirus","short":"Norovirus is een zeer besmettelijk RNA-virus dat acute gastro-enteritis veroorzaakt met plotseling braken en diarree, vaak in uitbraken.","definition":"<p>Het <strong>norovirus</strong> is een niet-omhuld RNA-virus (calicivirus). Er zijn maar weinig deeltjes nodig voor infectie en het overleeft lang in de omgeving.</p><p>Het veroorzaakt acute gastro-enteritis met plotseling braken, waterige diarree en buikkrampen, die 1 à 3 dagen duurt. Uitbraken komen vooral voor in verpleeghuizen, ziekenhuizen en op cruiseschepen; handhygiëne is de belangrijkste maatregel.</p>","image_url":"","wiki_title":"Norovirus","match":"norovirus|noro","option_only":true},"hepatitis a":{"title":"Hepatitis A","short":"Hepatitis A is een fecaal-oraal overgedragen virale leverontsteking die acuut verloopt en nooit chronisch wordt.","definition":"<p><strong>Hepatitis A</strong> wordt veroorzaakt door het hepatitis A-virus, een niet-omhuld RNA-virus dat fecaal-oraal wordt overgedragen (besmet water en voedsel, reizen).</p><p>Het geeft een acute hepatitis met moeheid, misselijkheid, geelzucht en verhoogde transaminasen; bij jonge kinderen vaak zonder klachten. Hepatitis A wordt <em>niet chronisch</em> en geeft levenslange immuniteit. Er is een vaccin.</p>","image_url":"","wiki_title":"Hepatitis A","match":"hepatitis a|hav|hepatitis a-virus","option_only":true},"hepatitis b":{"title":"Hepatitis B","short":"Hepatitis B is een via bloed en seks overgedragen DNA-virus dat acute en chronische leverontsteking geeft, met risico op cirrose en levercelcarcinoom.","definition":"<p><strong>Hepatitis B</strong> wordt veroorzaakt door het hepatitis B-virus, een omhuld (gedeeltelijk dubbelstrengs) DNA-virus. Overdracht via bloed, seksueel contact en van moeder op kind rond de geboorte.</p><p>Bij volwassenen geneest de meeste acute infectie; bij pasgeborenen wordt de infectie meestal <em>chronisch</em>. Chronische hepatitis B kan leiden tot levercirrose en hepatocellulair carcinoom. Diagnostiek via serologie (HBsAg, anti-HBc, anti-HBs). Er is een effectief vaccin.</p>","image_url":"","wiki_title":"Hepatitis B","match":"hepatitis b|hbv|hepatitis b-virus","option_only":true},"hepatitis e":{"title":"Hepatitis E","short":"Hepatitis E is een virale leverontsteking die fecaal-oraal of via varkensvlees wordt overgedragen; meestal acuut en zelflimiterend.","definition":"<p><strong>Hepatitis E</strong> wordt veroorzaakt door het hepatitis E-virus, een niet-omhuld RNA-virus. Wereldwijd verspreidt het via besmet water; in Nederland vooral via (onvoldoende verhit) varkensvlees.</p><p>Het geeft meestal een milde, zelflimiterende acute hepatitis. Bij zwangeren kan het ernstig verlopen en bij immuungecompromitteerden (bijv. na transplantatie) kan het chronisch worden.</p>","image_url":"","wiki_title":"Hepatitis E","match":"hepatitis e|hev|hepatitis e-virus","option_only":true},"tuberculose":{"title":"Tuberculose","short":"Tuberculose is een infectie met Mycobacterium tuberculosis, meestal in de longen, met langdurig hoesten, nachtzweten, gewichtsverlies en granulomen.","definition":"<p><strong>Tuberculose</strong> wordt veroorzaakt door <em>Mycobacterium tuberculosis</em> en verspreidt zich via aerosolen. Na infectie wordt de bacterie meestal ingekapseld in granulomen (latente tbc); bij verminderde afweer kan actieve ziekte ontstaan.</p><p>Longtuberculose geeft langdurig hoesten (soms met bloed), koorts, nachtzweten en gewichtsverlies; typisch zijn holtevorming in de longtoppen en granulomen met centrale <em>verkazing</em>. Behandeling met een combinatie van tuberculostatica gedurende minstens 6 maanden.</p>","image_url":"","wiki_title":"Tuberculosis","match":"tuberculose|tbc|tb","option_only":true},"pyelonefritis":{"title":"Pyelonefritis","short":"Pyelonefritis is een bacteriële infectie van het nierbekken en de nier, met koorts, flankpijn en vaak klachten van een blaasontsteking.","definition":"<p><strong>Pyelonefritis</strong> is een opstijgende urineweginfectie die de nier en het nierbekken bereikt, meestal door <em>E. coli</em>.</p><p>Kenmerkend zijn koorts, koude rillingen, flankpijn en slagpijn in de nierloge, eventueel met mictieklachten. Het is een gecompliceerde urineweginfectie die behandeld wordt met antibiotica met goede weefselpenetratie (niet nitrofurantoïne).</p>","image_url":"","wiki_title":"Pyelonephritis","match":"pyelonefritis|nierbekkenontsteking","option_only":true},"cystitis":{"title":"Cystitis","short":"Cystitis is een ontsteking van de blaas, meestal door een bacteriële infectie, met pijnlijke en frequente mictie zonder koorts.","definition":"<p><strong>Cystitis</strong> (blaasontsteking) is een infectie van de lage urinewegen, meestal door <em>E. coli</em> vanuit de darmflora. Vrouwen zijn vaker aangedaan door hun korte urethra.</p><p>Klachten: pijn bij het plassen (dysurie), vaak kleine beetjes plassen (frequentie), aandrang en soms hematurie, zonder koorts of flankpijn. Ongecompliceerde cystitis wordt behandeld met bijv. nitrofurantoïne of fosfomycine.</p>","image_url":"","wiki_title":"Cystitis","match":"cystitis|blaasontsteking","option_only":true},"prednison":{"title":"Prednison / prednisolon","short":"Prednison(olon) is een synthetisch glucocorticoïd met sterke ontstekingsremmende en immunosuppressieve werking.","definition":"<p><strong>Prednison</strong> is een prodrug die in de lever wordt omgezet in het actieve <strong>prednisolon</strong>. Beide zijn synthetische <em>glucocorticoïden</em>: ze binden aan de intracellulaire glucocorticoïdreceptor en veranderen de gentranscriptie.</p><p>Daardoor remmen ze de vorming van allerlei ontstekingsmediatoren en de activatie van ontstekingscellen. Gebruikt bij astma/COPD-exacerbaties, auto-immuunziekten en allergieën. Bijwerkingen bij langdurig gebruik: osteoporose, hyperglykemie, gewichtstoename, huidatrofie, infectierisico en bijnierschorsremming.</p>","image_url":"","wiki_title":"Prednisolone","match":"prednison|prednisolon|prednisone|prednisolone","option_only":true},"chemotherapie":{"title":"Chemotherapie","short":"Chemotherapie is behandeling met cytostatica: medicijnen die snel delende (kanker)cellen doden of hun deling remmen.","definition":"<p><strong>Chemotherapie</strong> is behandeling met <em>cytostatica</em>. Deze grijpen in op de celdeling, bijvoorbeeld door DNA te beschadigen (alkylerende middelen, platinaverbindingen), de DNA-synthese te remmen (antimetabolieten) of de mitosespoel te verstoren (taxanen, vinca-alkaloïden).</p><p>Omdat ook gezonde, snel delende cellen geraakt worden, zijn bijwerkingen beenmergsuppressie, haaruitval, mucositis en misselijkheid. Chemotherapie kan curatief, (neo)adjuvant of palliatief worden ingezet.</p>","image_url":"","wiki_title":"Chemotherapy","match":"chemotherapie|chemo|cytostatica","option_only":true},"somatostatine analoog":{"title":"Somatostatine-analoog","short":"Somatostatine-analogen (zoals octreotide) bootsen somatostatine na en remmen de afgifte van groeihormoon en veel maag-darmhormonen.","definition":"<p><strong>Somatostatine-analogen</strong> zoals <em>octreotide</em> en <em>lanreotide</em> zijn langwerkende varianten van het hormoon somatostatine. Ze binden aan somatostatinereceptoren en remmen de afgifte van o.a. groeihormoon, TSH, insuline, glucagon en gastro-intestinale hormonen.</p><p>Ze worden gebruikt bij acromegalie, hormoonproducerende neuro-endocriene tumoren (bijv. carcinoïdsyndroom) en bij varicesbloedingen (vermindering van de splanchnische doorbloeding).</p>","image_url":"","wiki_title":"Octreotide","match":"somatostatine analoog|somatostatine-analoog|somatostatineanaloog|octreotide|lanreotide","option_only":true},"foliumzuur":{"title":"Foliumzuur","short":"Foliumzuur (vitamine B11/B9) is nodig voor DNA-synthese; tekort geeft megaloblastaire anemie en verhoogt het risico op een neuralebuisdefect.","definition":"<p><strong>Foliumzuur</strong> (folaat) is als tetrahydrofolaat een drager van één-koolstofgroepen, nodig voor de synthese van purines en thymidine en dus voor <em>DNA-synthese</em> en celdeling.</p><p>Tekort geeft een <em>megaloblastaire (macrocytaire) anemie</em>. Een tekort rond de conceptie verhoogt het risico op neuralebuisdefecten (spina bifida); daarom wordt vrouwen met kinderwens aangeraden vanaf 4 weken voor de conceptie tot 10 weken zwangerschap foliumzuur te slikken.</p>","image_url":"","wiki_title":"Folate","match":"foliumzuur|folaat|vitamine b11|vitamine b9","option_only":true},"vitamine b6":{"title":"Vitamine B6 (pyridoxine)","short":"Vitamine B6 is als pyridoxaalfosfaat cofactor bij het aminozuurmetabolisme en de synthese van neurotransmitters en heem.","definition":"<p><strong>Vitamine B6</strong> (pyridoxine) wordt omgezet in <em>pyridoxaalfosfaat</em>, de cofactor van transaminasen en decarboxylasen. Het is nodig voor het aminozuurmetabolisme, de synthese van neurotransmitters (GABA, serotonine, dopamine) en van heem.</p><p>Tekort is zeldzaam en kan optreden bij gebruik van isoniazide; het geeft perifere neuropathie, glossitis en een sideroblastaire anemie. Overdosering geeft eveneens neuropathie.</p>","image_url":"","wiki_title":"Vitamin B6","match":"vitamine b6|pyridoxine|pyridoxaalfosfaat","option_only":true},"alcohol":{"title":"Alcohol (ethanol)","short":"Ethanol wordt in de lever afgebroken via acetaldehyde tot azijnzuur; overmatig gebruik schaadt lever, brein, hart en pancreas.","definition":"<p><strong>Ethanol</strong> wordt vooral in de lever geoxideerd door <em>alcoholdehydrogenase</em> tot acetaldehyde en daarna door aldehydedehydrogenase tot acetaat. Hierbij ontstaat veel NADH, wat de gluconeogenese remt (hypoglykemie) en vetstapeling in de lever bevordert.</p><p>Chronisch overmatig gebruik geeft leververvetting, alcoholische hepatitis en cirrose, pancreatitis, cardiomyopathie, hypertensie, neuropathie, thiaminetekort (Wernicke-Korsakov) en een verhoogd risico op verschillende kankers.</p>","image_url":"","wiki_title":"Alcohol (drug)","match":"alcohol|ethanol|alcoholgebruik|overmatig alcoholgebruik|alcoholmisbruik","option_only":true},"ductus thoracicus":{"title":"Ductus thoracicus","short":"De ductus thoracicus is het grootste lymfevat; hij voert de lymfe van het grootste deel van het lichaam af naar de linker veneuze hoek.","definition":"<p>De <strong>ductus thoracicus</strong> begint in de buik bij de cisterna chyli, loopt door de hiatus aorticus van het diafragma omhoog door het achterste mediastinum en mondt uit in de <em>linker veneuze hoek</em> (samenkomst v. jugularis interna en v. subclavia sinistra).</p><p>Hij draineert de lymfe van de benen, de buik (inclusief chylus met vetten uit de darm), de linker thoraxhelft, de linker arm en de linker kant van hoofd en hals. De rechter bovenkwadrant draineert via de ductus lymphaticus dexter.</p>","image_url":"","wiki_title":"Thoracic duct","match":"ductus thoracicus|borstbuis","option_only":true},"x-thorax":{"title":"X-thorax","short":"Een X-thorax is een röntgenfoto van de borstkas; het eerste beeldvormend onderzoek bij verdenking op longafwijkingen, hartfalen of pneumothorax.","definition":"<p>Een <strong>X-thorax</strong> is een röntgenopname van de borstkas, meestal posterieur-anterieur en lateraal. Lucht is zwart, weke delen grijs en bot wit.</p><p>Het is snel, goedkoop en met een lage stralingsdosis, en wordt gebruikt om o.a. pneumonie (infiltraat), pleuravocht, pneumothorax, longtumoren, hartvergroting en tekenen van hartfalen op te sporen. Kleine of subtiele afwijkingen zijn er minder goed op te zien dan op een CT.</p>","image_url":"","wiki_title":"Chest radiograph","match":"x-thorax|thoraxfoto|röntgenfoto van de thorax|x thorax|x-thorax (röntgenfoto)","option_only":true},"echo abdomen":{"title":"Echo abdomen","short":"Een echo abdomen is een echografisch onderzoek van de buikorganen; zonder straling en goed voor galblaas, galwegen, lever, nieren en vrij vocht.","definition":"<p>Bij een <strong>echo abdomen</strong> wordt met geluidsgolven een beeld gemaakt van de buikorganen. Het onderzoek gebruikt geen ioniserende straling, is goedkoop en direct beschikbaar.</p><p>Het is bijzonder geschikt voor het aantonen van galstenen en cholecystitis, verwijde galwegen, leverafwijkingen, nierstuwing (hydronefrose), een abdominaal aorta-aneurysma en vrij vocht. Darmgas en een dikke buikwand beperken het zicht; de kwaliteit hangt af van de onderzoeker.</p>","image_url":"","wiki_title":"Abdominal ultrasonography","match":"echo abdomen|echografie abdomen|echo van de buik|abdominale echografie|echo-abdomen","option_only":true},"ct abdomen":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct abdomen|ct-abdomen|ct van de buik|ct-scan abdomen","option_only":true},"gladde spiercellen":{"title":"Gladde spiercellen","short":"Gladde spiercellen zijn spoelvormige, onwillekeurig aangestuurde spiercellen zonder dwarsstreping, in de wand van vaten en holle organen.","definition":"<p><strong>Gladde spiercellen</strong> zijn spoelvormige cellen met één centraal gelegen kern. Actine en myosine liggen niet in sarcomeren, daarom ontbreekt de dwarsstreping. Contractie wordt via calcium-calmoduline en myosine-lichteketenkinase gereguleerd.</p><p>Ze komen voor in de wand van bloedvaten, luchtwegen, maag-darmkanaal, blaas en uterus en worden aangestuurd door het autonome zenuwstelsel, hormonen en lokale factoren. Ze kunnen langdurig samentrekken met weinig energieverbruik.</p>","image_url":"","wiki_title":"Smooth muscle","match":"gladde spiercellen|glad spierweefsel|gladde spier|gladde spiercel","option_only":true},"submucosa":{"title":"Submucosa","short":"De submucosa is de bindweefsellaag onder het slijmvlies van het maag-darmkanaal, met grotere bloedvaten, lymfevaten en de plexus van Meissner.","definition":"<p>De wand van het maag-darmkanaal bestaat van binnen naar buiten uit mucosa, <strong>submucosa</strong>, muscularis externa en serosa/adventitia.</p><p>De submucosa is een laag van los tot straf bindweefsel met grotere bloed- en lymfevaten en de <em>plexus submucosus</em> (van Meissner), die secretie en lokale doorbloeding regelt. In het duodenum bevat zij de klieren van Brunner en in de oesofagus mukeuze klieren.</p>","image_url":"","wiki_title":"Submucosa","match":"submucosa|tela submucosa","option_only":true},"mucosa":{"title":"Mucosa (slijmvlies)","short":"De mucosa is het slijmvlies: de binnenste laag van holle organen, bestaande uit epitheel, lamina propria en (in de darm) een laagje spier.","definition":"<p>De <strong>mucosa</strong> bekleedt de binnenkant van holle organen die met de buitenwereld in contact staan, zoals het maag-darmkanaal, de luchtwegen en de urinewegen.</p><p>Ze bestaat uit een <em>epitheel</em> (aangepast aan de functie: bijv. meerlagig plaveisel in de slokdarm, enkellaags cilindrisch in de darm), een <em>lamina propria</em> van losmazig bindweefsel met vaten en afweercellen en, in het maag-darmkanaal, een dun spierlaagje (muscularis mucosae).</p>","image_url":"","wiki_title":"Mucous membrane","match":"mucosa|slijmvlies|tunica mucosa","option_only":true},"obesitas":{"title":"Obesitas","short":"Obesitas is ernstig overgewicht (BMI ≥30 kg/m²) met verhoogd risico op diabetes type 2, hart- en vaatziekten, artrose en bepaalde kankers.","definition":"<p>Bij <strong>obesitas</strong> is er een overmaat aan lichaamsvet, gedefinieerd als een <em>BMI ≥30 kg/m²</em>. Vooral vet in de buik (grote middelomtrek, visceraal vet) is metabool ongunstig.</p><p>Obesitas verhoogt het risico op insulineresistentie en diabetes type 2, hypertensie, dyslipidemie, hart- en vaatziekten, slaapapneu, leververvetting, artrose en verschillende vormen van kanker. Oorzaken zijn een combinatie van leefstijl, omgeving, genetische aanleg en soms medicatie of hormonale ziekten.</p>","image_url":"","wiki_title":"Obesity","match":"obesitas|ernstig overgewicht|adipositas","option_only":true},"maligniteit":{"title":"Maligniteit","short":"Een maligniteit is een kwaadaardige tumor: ongecontroleerd groeiende cellen die omliggend weefsel binnendringen en kunnen uitzaaien.","definition":"<p>Een <strong>maligniteit</strong> (kanker) is een tumor waarvan de cellen ongeremd delen, het omliggende weefsel <em>infiltreren</em> en via bloed- of lymfevaten kunnen <em>metastaseren</em>. Dat onderscheidt ze van goedaardige (benigne) tumoren, die expansief groeien zonder invasie.</p><p>Maligniteiten ontstaan door een opeenstapeling van genetische veranderingen (activatie van oncogenen, uitschakeling van tumorsuppressorgenen). Systemische verschijnselen kunnen zijn: gewichtsverlies, moeheid, nachtzweten, anemie, trombose en paraneoplastische syndromen.</p>","image_url":"","wiki_title":"","match":"maligniteit|maligne tumor|kanker|kwaadaardige tumor","option_only":true},"maagcarcinoom":{"title":"Maagcarcinoom","short":"Een maagcarcinoom is een kwaadaardige tumor (meestal adenocarcinoom) van de maag; risicofactoren zijn o.a. H. pylori, roken en zoutrijke voeding.","definition":"<p>Het <strong>maagcarcinoom</strong> is meestal een adenocarcinoom, uitgaand van het klierepitheel. Het intestinale type ontstaat via een reeks van chronische (H. pylori-)gastritis, atrofie, intestinale metaplasie en dysplasie; het diffuse type (zegelringcellen) infiltreert de wand zonder duidelijke massa (linitis plastica).</p><p>Klachten komen vaak laat: verminderde eetlust, vroege verzadiging, gewichtsverlies, epigastrische pijn, anemie of slikklachten. Metastasen kunnen zich manifesteren als een klier van Virchow (links supraclaviculair) of ovariummetastasen (Krukenberg).</p>","image_url":"","wiki_title":"Stomach cancer","match":"maagcarcinoom|maagkanker|adenocarcinoom van de maag","option_only":true},"ulcus pepticum":{"title":"Ulcus pepticum","short":"Een ulcus pepticum is een zweer in maag of duodenum door aantasting door maagzuur, meestal bij H. pylori-infectie of NSAID-gebruik.","definition":"<p>Een <strong>ulcus pepticum</strong> is een defect in de wand van maag (ulcus ventriculi) of duodenum (ulcus duodeni) dat dieper gaat dan de muscularis mucosae. Het ontstaat door een verstoorde balans tussen aanvallende factoren (zuur, pepsine) en beschermende factoren (slijm, bicarbonaat, doorbloeding).</p><p>De belangrijkste oorzaken zijn <em>Helicobacter pylori</em> en <em>NSAID's</em> (inclusief aspirine). Klachten: epigastrische pijn, soms gerelateerd aan maaltijden. Complicaties: bloeding, perforatie en obstructie. Behandeling: protonpompremmer en H. pylori-eradicatie.</p>","image_url":"","wiki_title":"Peptic ulcer disease","match":"ulcus pepticum|maagzweer|ulcus duodeni|ulcus ventriculi|peptisch ulcus","option_only":true},"acute cholecystitis":{"title":"Acute cholecystitis","short":"Acute cholecystitis is een ontsteking van de galblaas, meestal doordat een galsteen de ductus cysticus afsluit; pijn rechtsboven, koorts en een positief teken van Murphy.","definition":"<p>Bij een <strong>acute cholecystitis</strong> blokkeert meestal een galsteen de <em>ductus cysticus</em>. De galblaas zwelt, de wand raakt geïrriteerd en ontstoken, en secundair kan een bacteriële infectie ontstaan.</p><p>Klachten: aanhoudende pijn rechts in de bovenbuik (langer dan een galsteenkoliek), koorts en een positief <em>teken van Murphy</em> (pijn en stokkende inademing bij palpatie onder de ribboog). De echo toont galstenen, een verdikte galblaaswand en vocht rond de galblaas. Behandeling: antibiotica en (vroege) cholecystectomie.</p>","image_url":"","wiki_title":"Cholecystitis","match":"acute cholecystitis|cholecystitis|galblaasontsteking","option_only":true},"bacteriële overgroei":{"title":"Bacteriële overgroei van de dunne darm","short":"Bij bacteriële overgroei zijn er te veel bacteriën in de dunne darm, met een opgeblazen gevoel, diarree, malabsorptie en B12-tekort.","definition":"<p>Normaal bevat de dunne darm weinig bacteriën. Bij <strong>bacteriële overgroei</strong> (SIBO) nemen die sterk toe, bijvoorbeeld door verminderde motiliteit (diabetes, sclerodermie), anatomische afwijkingen (blinde lis, divertikels, na operaties) of verminderd maagzuur.</p><p>De bacteriën deconjugeren galzouten (vetmalabsorptie, steatorroe), fermenteren koolhydraten (opgeblazen gevoel, winderigheid, diarree) en verbruiken vitamine B12 (tekort). Foliumzuur kan juist hoog zijn. Diagnose o.a. via een waterstofademtest; behandeling met antibiotica.</p>","image_url":"","wiki_title":"","match":"bacteriële overgroei|bacteriële overgroei van de dunne darm|sibo|dunnedarmbacteriële overgroei","option_only":true},"elementaire voeding":{"title":"Elementaire voeding","short":"Elementaire voeding is sondevoeding of drinkvoeding waarin eiwitten als losse aminozuren aanwezig zijn, zodat er nauwelijks vertering nodig is.","definition":"<p>In <strong>elementaire voeding</strong> zitten de voedingsstoffen in hun eenvoudigste vorm: eiwitten als vrije aminozuren, koolhydraten als kleine sachariden en weinig vet. Daardoor is nauwelijks enzymatische vertering nodig en wordt ze gemakkelijk opgenomen.</p><p>Ze wordt gebruikt bij ernstige malabsorptie of verteringsstoornissen, bij sommige vormen van voedselallergie (bijv. koemelkallergie, eosinofiele oesofagitis) en soms bij de ziekte van Crohn. Elementaire voeding smaakt slecht en wordt daarom vaak per sonde gegeven.</p>","image_url":"","wiki_title":"","match":"elementaire voeding|elementair dieet","option_only":true},"drinkvoeding (nutridrink)":{"title":"Drinkvoeding","short":"Drinkvoeding is een energie- en eiwitrijke drink (zoals Nutridrink) als aanvulling op de gewone voeding bij (dreigende) ondervoeding.","definition":"<p><strong>Drinkvoeding</strong> is een kant-en-klare, energie- en eiwitrijke vloeibare voeding, verrijkt met vitamines en mineralen. Een bekend merk is Nutridrink.</p><p>Ze wordt gegeven als bijvoeding wanneer iemand met gewone maaltijden onvoldoende binnenkrijgt, bijvoorbeeld bij ziekte, ouderdom of na een operatie.</p>","image_url":"","wiki_title":"","match":"drinkvoeding (nutridrink)|drinkvoeding|nutridrink","option_only":true},"lever":{"title":"Lever","short":"De lever is de grootste klier van het lichaam: hij regelt stofwisseling van suikers, vetten en eiwitten, maakt gal en eiwitten (o.a. albumine, stollingsfactoren) en ontgift stoffen.","definition":"<p>De <strong>lever</strong> ligt rechtsboven in de buik en krijgt bloed uit de a. hepatica en (voor ±75%) uit de <em>v. portae</em>, met voedingsstoffen uit de darm.</p><p>Functies: opslag en afgifte van glucose (glycogeen, gluconeogenese), vet- en cholesterolmetabolisme, aanmaak van plasma-eiwitten (albumine, stollingsfactoren), ureumvorming, galproductie, afbraak van bilirubine en ontgifting van geneesmiddelen en alcohol. Functionele eenheden zijn de leverlobjes met hepatocyten rond sinusoïden.</p>","image_url":"","wiki_title":"Liver","match":"lever|hepar","option_only":true},"maag":{"title":"Maag","short":"De maag slaat voedsel tijdelijk op, mengt het met maagzuur en pepsine en geeft het geleidelijk af aan het duodenum.","definition":"<p>De <strong>maag</strong> bestaat uit cardia, fundus, corpus, antrum en pylorus. Het slijmvlies bevat klieren met <em>pariëtale cellen</em> (zoutzuur en intrinsieke factor), <em>hoofdcellen</em> (pepsinogeen), slijmcellen en endocriene cellen (o.a. G-cellen met gastrine in het antrum).</p><p>De maag doodt micro-organismen, start de eiwitvertering en mengt voedsel tot chymus. Intrinsieke factor is nodig voor opname van vitamine B12 in het terminale ileum.</p>","image_url":"","wiki_title":"Stomach","match":"maag|gaster|ventriculus","option_only":true},"pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"pancreas|alvleesklier","option_only":true},"galblaas":{"title":"Galblaas","short":"De galblaas slaat gal uit de lever op en dikt die in; na een vetrijke maaltijd trekt hij samen onder invloed van cholecystokinine.","definition":"<p>De <strong>galblaas</strong> ligt aan de onderzijde van de lever en is via de ductus cysticus verbonden met de galwegen. Ze slaat de gal die de lever continu maakt op en concentreert die door water en zout terug te resorberen.</p><p>Na een (vetrijke) maaltijd geeft het duodenum <em>cholecystokinine</em> af: de galblaas trekt samen en de sfincter van Oddi ontspant, zodat gal in het duodenum komt voor de vetvertering. Galstenen kunnen koliek, cholecystitis of een choledocholithiasis geven.</p>","image_url":"","wiki_title":"Gallbladder","match":"galblaas|vesica biliaris|vesica fellea","option_only":true},"de milt":{"title":"Milt","short":"De milt filtert het bloed: hij ruimt oude en beschadigde rode bloedcellen op en vormt een afweerorgaan tegen bacteriën in het bloed.","definition":"<p>De <strong>milt</strong> ligt linksboven in de buik onder het diafragma. Ze bestaat uit <em>rode pulpa</em> (sinusoïden waar verouderde of afwijkende erytrocyten worden afgebroken) en <em>witte pulpa</em> (lymfatisch weefsel met B- en T-cellen rond arteriolen).</p><p>De milt is belangrijk voor de afweer tegen <em>gekapselde bacteriën</em> (pneumokok, meningokok, H. influenzae). Na splenectomie is het risico op een ernstige sepsis daardoor verhoogd; deze patiënten worden gevaccineerd.</p>","image_url":"","wiki_title":"Spleen","match":"de milt|milt|lien|splenomegalie","option_only":true},"parafraseren":{"title":"Parafraseren (gesprekstechniek)","short":"Parafraseren is het in eigen woorden teruggeven van de inhoud van één uitspraak van de patiënt, om te laten merken dat je luistert en te checken of je het goed begrijpt.","definition":"<p>Bij <strong>parafraseren</strong> herhaalt de arts de <em>inhoud</em> van wat de patiënt net zei in eigen, vaak kortere woorden (bijvoorbeeld: “U heeft dus vooral ’s nachts last”). Het is een vorm van actief luisteren.</p><p>Parafraseren nodigt de patiënt uit om verder te vertellen of te corrigeren. Het verschilt van het reflecteren van gevoelens, dat zich richt op de emotie achter de woorden.</p>","image_url":"","wiki_title":"","match":"parafraseren|parafrase","option_only":true},"agenderen":{"title":"Agenderen (gesprekstechniek)","short":"Agenderen is aan het begin van een consult samen met de patiënt vaststellen welke onderwerpen besproken worden.","definition":"<p>Bij <strong>agenderen</strong> inventariseert de arts aan het begin van het gesprek welke vragen en klachten de patiënt wil bespreken, en vult die aan met eigen punten (bijv. uitslagen of controles). Samen wordt besloten wat er in dit consult aan bod komt en in welke volgorde.</p><p>Het voorkomt dat belangrijke punten aan het eind van het gesprek nog opduiken (‘deurknopvragen’) en geeft het consult structuur.</p>","image_url":"","wiki_title":"","match":"agenderen|agenda bespreken|agenda opstellen","option_only":true},"gesprekskader bespreken":{"title":"Gesprekskader bespreken","short":"Het gesprekskader bespreken betekent aan het begin van een gesprek uitleggen wat het doel, de duur en de opbouw van het gesprek zijn.","definition":"<p>Bij het <strong>bespreken van het gesprekskader</strong> vertelt de arts aan het begin wat de aanleiding en het doel van het gesprek zijn, hoeveel tijd er is, en hoe het gesprek ongeveer verloopt (bijvoorbeeld eerst vragen stellen, dan onderzoek, dan bespreken).</p><p>Het geeft de patiënt duidelijkheid en houvast, en vormt samen met agenderen het startpunt van een gestructureerd consult.</p>","image_url":"","wiki_title":"","match":"gesprekskader bespreken|gesprekskader|kader schetsen|het gesprekskader aangeven","option_only":true},"hardop denken":{"title":"Hardop denken","short":"Hardop denken is het voor de patiënt uitspreken van je overwegingen tijdens onderzoek of besluitvorming, zodat de patiënt kan meekijken en meedenken.","definition":"<p>Bij <strong>hardop denken</strong> verwoordt de arts wat hij of zij doet en overweegt, bijvoorbeeld tijdens het lichamelijk onderzoek (“ik voel nu aan uw buik of de lever vergroot is”) of bij het afwegen van mogelijke oorzaken.</p><p>Het maakt het klinisch redeneren transparant, vermindert onzekerheid bij de patiënt en ondersteunt gedeelde besluitvorming.</p>","image_url":"","wiki_title":"","match":"hardop denken|hardop-denken","option_only":true},"depressieve stoornis":{"title":"Depressieve stoornis","short":"Een depressieve stoornis kenmerkt zich door minstens twee weken een sombere stemming en/of verlies van interesse en plezier, met o.a. slaap-, eetlust- en concentratieproblemen.","definition":"<p>Voor een <strong>depressieve stoornis</strong> (DSM-5) moeten gedurende minstens twee weken vijf of meer symptomen aanwezig zijn, waaronder ten minste één kernsymptoom: <em>depressieve stemming</em> of <em>verlies van interesse of plezier</em> (anhedonie).</p><p>Andere symptomen: veranderde eetlust of gewicht, slapeloosheid of juist veel slapen, psychomotorische remming of agitatie, vermoeidheid, schuldgevoelens of waardeloosheid, concentratieproblemen en gedachten aan de dood. Behandeling met psychotherapie en/of antidepressiva.</p>","image_url":"","wiki_title":"Major depressive disorder","match":"depressieve stoornis|depressie|depressieve episode|majeure depressie","option_only":true},"crp":{"title":"CRP (C-reactief proteïne)","short":"CRP is een acutefase-eiwit uit de lever dat binnen een dag sterk stijgt bij ontsteking of infectie, vooral bacterieel.","definition":"<p><strong>C-reactief proteïne</strong> wordt door de lever gemaakt onder invloed van vooral <em>IL-6</em>. Het bindt aan fosfocholine op micro-organismen en beschadigde cellen en activeert zo complement (opsonisatie).</p><p>Het CRP stijgt binnen 6–12 uur na het begin van een ontsteking en daalt snel bij herstel, waardoor het een nuttige maat is voor ontstekingsactiviteit. Bacteriële infecties geven vaak een hoger CRP dan virale, maar de waarde is niet specifiek.</p>","image_url":"","wiki_title":"C-reactive protein","match":"crp|c-reactief proteïne|c-reactief proteine","option_only":true},"astma":{"title":"Astma","short":"Astma is een chronische ontsteking van de luchtwegen met wisselende, reversibele luchtwegobstructie en hyperreactiviteit; klachten zijn piepen, benauwdheid en hoesten.","definition":"<p>Bij <strong>astma</strong> zijn de luchtwegen chronisch ontstoken (vaak eosinofiel/Th2-gemedieerd) en <em>hyperreactief</em>: op prikkels zoals allergenen, inspanning, koude lucht of rook ontstaan bronchoconstrictie, slijmvliesoedeem en slijmproductie.</p><p>De obstructie is variabel en grotendeels <em>reversibel</em> (verbetering van de FEV1 na een luchtwegverwijder). Klachten: aanvallen van piepen, kortademigheid, een beklemd gevoel op de borst en hoesten, vaak ’s nachts. Behandeling met inhalatiecorticosteroïden en luchtwegverwijders.</p>","image_url":"","wiki_title":"Asthma","match":"astma|asthma|astma bronchiale","option_only":true},"duodenum":{"title":"Duodenum (twaalfvingerige darm)","short":"Het duodenum is het eerste, C-vormige deel van de dunne darm; hier komen gal en pancreassap bij de voedselbrij.","definition":"<p>Het <strong>duodenum</strong> loopt van de pylorus in een C-bocht om de pancreaskop heen en gaat bij de flexura duodenojejunalis over in het jejunum. Het ligt grotendeels retroperitoneaal. In de pars descendens mondt via de papil van Vater de ductus choledochus samen met de ductus pancreaticus uit. Klieren van Brunner in de submucosa maken bicarbonaatrijk slijm dat het zure chymus neutraliseert; endocriene cellen maken o.a. secretine en cholecystokinine.</p>","image_url":"","wiki_title":"Duodenum","match":"duodenum|twaalfvingerige darm","option_only":true},"jejunum":{"title":"Jejunum","short":"Het jejunum is het middelste deel van de dunne darm, met hoge kringplooien en veel opname van voedingsstoffen.","definition":"<p>Het <strong>jejunum</strong> volgt op het duodenum en ligt vooral linksboven in de buik, opgehangen aan het mesenterium. Vergeleken met het ileum heeft het een dikkere wand, hogere kringplooien (plicae circulares), minder vet in het mesenterium en weinig lange vaatarcades. Het grootste deel van de opname van suikers, aminozuren en vetten vindt hier plaats.</p>","image_url":"","wiki_title":"Jejunum","match":"jejunum","option_only":true},"ileum":{"title":"Ileum","short":"Het ileum is het laatste deel van de dunne darm; het terminale ileum neemt vitamine B12 en galzouten op.","definition":"<p>Het <strong>ileum</strong> ligt vooral rechtsonder in de buik en eindigt bij de ileocaecaalklep. Het heeft lagere kringplooien dan het jejunum en veel lymfatisch weefsel in de vorm van Peyerse platen. Het <em>terminale ileum</em> resorbeert vitamine B12 (gebonden aan intrinsieke factor) en galzouten, die via de enterohepatische kringloop terug naar de lever gaan.</p>","image_url":"","wiki_title":"Ileum","match":"ileum","option_only":true},"terminale ileum":{"title":"Terminale ileum","short":"Het terminale ileum is het laatste stuk van de dunne darm, waar vitamine B12 en galzouten worden opgenomen.","definition":"<p>Het <strong>terminale ileum</strong> is het eindstuk van het ileum vlak voor de ileocaecaalklep. Hier worden vitamine B12 (als complex met intrinsieke factor) en geconjugeerde galzouten actief opgenomen. Ziekte of resectie van dit deel, bijvoorbeeld bij de ziekte van Crohn, kan B12-tekort en galzuurdiarree geven.</p>","image_url":"","wiki_title":"Ileum","match":"terminale ileum|terminaal ileum","option_only":true},"vitamine b12":{"title":"Vitamine B12 (cobalamine)","short":"Vitamine B12 is nodig voor DNA-synthese en de myelinevorming; opname vereist intrinsieke factor uit de maag en een gezond terminaal ileum.","definition":"<p><strong>Vitamine B12</strong> komt alleen uit dierlijke producten. In de maag bindt het aan intrinsieke factor (van pariëtale cellen); het complex wordt in het terminale ileum opgenomen. B12 is cofactor van methioninesynthase (koppeling met foliumzuur) en methylmalonyl-CoA-mutase. Tekort ontstaat door bijv. auto-immuungastritis (pernicieuze anemie), maag- of ileumresectie, metformine of veganisme, en geeft macrocytaire anemie en neurologische schade.</p>","image_url":"","wiki_title":"Vitamin B12","match":"vitamine b12|cobalamine|b12","option_only":true},"vitamine a":{"title":"Vitamine A (retinol)","short":"Vitamine A is een in vet oplosbare vitamine die nodig is voor het zien in het donker, de opbouw van epitheel en de afweer.","definition":"<p><strong>Vitamine A</strong> komt als retinol uit dierlijke producten en als bètacaroteen uit groenten. In de retina vormt retinal samen met opsine het lichtgevoelige rodopsine. Retinoïnezuur reguleert de groei en differentiatie van epitheel. Tekort geeft nachtblindheid, droge ogen (xeroftalmie) en meer infecties; overmaat is teratogeen en levertoxisch.</p>","image_url":"","wiki_title":"Vitamin A","match":"vitamine a|retinol|retinoïnezuur","option_only":true},"vitamine c":{"title":"Vitamine C (ascorbinezuur)","short":"Vitamine C is een in water oplosbare vitamine die nodig is voor de collageensynthese en werkt als antioxidant.","definition":"<p><strong>Vitamine C</strong> is cofactor van prolyl- en lysylhydroxylase, die collageen stabiliseren. Het bevordert ook de opname van non-heemijzer en werkt als antioxidant. Tekort geeft <em>scheurbuik</em>: tandvleesbloedingen, perifolliculaire bloedinkjes, slechte wondgenezing en loszittende tanden.</p>","image_url":"","wiki_title":"Vitamin C","match":"vitamine c|ascorbinezuur","option_only":true},"vitamine d":{"title":"Vitamine D","short":"Vitamine D bevordert de opname van calcium en fosfaat uit de darm en is nodig voor sterke botten.","definition":"<p><strong>Vitamine D</strong> wordt in de huid onder invloed van UVB-licht gemaakt of via de voeding opgenomen. De lever zet het om in 25-OH-vitamine D en de nier (onder invloed van PTH) in het actieve 1,25-(OH)₂-vitamine D (calcitriol). Calcitriol verhoogt de opname van calcium en fosfaat in de darm. Tekort geeft rachitis bij kinderen en osteomalacie bij volwassenen.</p>","image_url":"","wiki_title":"Vitamin D","match":"vitamine d|calcitriol|colecalciferol|vitamine d3","option_only":true},"vitamine e":{"title":"Vitamine E (tocoferol)","short":"Vitamine E is een in vet oplosbare antioxidant die celmembranen beschermt tegen oxidatieve schade.","definition":"<p><strong>Vitamine E</strong> (tocoferol) beschermt meervoudig onverzadigde vetzuren in membranen tegen lipideperoxidatie. Tekort is zeldzaam en komt vooral voor bij vetmalabsorptie (bijv. cystische fibrose, cholestase); het geeft neurologische klachten zoals ataxie en neuropathie, en hemolytische anemie bij prematuren.</p>","image_url":"","wiki_title":"Vitamin E","match":"vitamine e|tocoferol","option_only":true},"vitamine k":{"title":"Vitamine K","short":"Vitamine K is nodig voor de activatie van stollingsfactoren II, VII, IX en X en eiwit C en S in de lever.","definition":"<p><strong>Vitamine K</strong> is cofactor van het enzym γ-glutamylcarboxylase, dat glutamaatresten van stollingsfactoren carboxyleert zodat ze calcium kunnen binden. Cumarines (zoals acenocoumarol en fenprocoumon) remmen de recycling van vitamine K. Pasgeborenen krijgen vitamine K om bloedingen te voorkomen, omdat ze weinig voorraad en nog geen darmflora hebben.</p>","image_url":"","wiki_title":"Vitamin K","match":"vitamine k|fytomenadion|vitamine k1","option_only":true},"calcium":{"title":"Calcium","short":"Calcium is nodig voor botten, spiercontractie, zenuwgeleiding en stolling; de bloedspiegel wordt geregeld door PTH, vitamine D en calcitonine.","definition":"<p>Het meeste <strong>calcium</strong> zit in botten als hydroxyapatiet. In het bloed is ongeveer de helft eiwitgebonden (vooral aan albumine) en de rest vrij geïoniseerd, de biologisch actieve vorm. Calcium is tweede boodschapper in cellen en essentieel voor spiercontractie, neurotransmitterafgifte en stolling. Afwijkingen geven bijv. tetanie (hypocalciëmie) of dorst, obstipatie en verwardheid (hypercalciëmie).</p>","image_url":"","wiki_title":"Calcium in biology","match":"calcium|ca2+|calciumion","option_only":true},"ijzer":{"title":"IJzer","short":"IJzer is nodig voor hemoglobine, myoglobine en enzymen; het lichaam regelt de ijzervoorraad vooral via de opname in de darm.","definition":"<p><strong>IJzer</strong> wordt vooral in het duodenum opgenomen, als heemijzer of als Fe²⁺. In het bloed wordt het vervoerd door transferrine en opgeslagen als ferritine. Het hormoon hepcidine uit de lever remt de opname en afgifte. Het lichaam heeft geen actieve uitscheidingsroute, dus verlies gaat vooral via bloedverlies.</p>","image_url":"","wiki_title":"Iron in biology","match":"ijzer|fe|ijzersuppletie","option_only":true},"albumine":{"title":"Albumine","short":"Albumine is het meest voorkomende plasma-eiwit; het houdt vocht in de bloedbaan (colloïd-osmotische druk) en vervoert veel stoffen.","definition":"<p><strong>Albumine</strong> wordt in de lever gemaakt. Het zorgt voor het grootste deel van de colloïd-osmotische druk en bindt o.a. calcium, bilirubine, vrije vetzuren, hormonen en geneesmiddelen. Een laag albumine komt voor bij leverziekte, nefrotisch syndroom, ondervoeding en ontsteking (negatief acutefase-eiwit) en kan oedeem geven.</p>","image_url":"","wiki_title":"Human serum albumin","match":"albumine|serumalbumine","option_only":true},"triglyceriden":{"title":"Triglyceriden","short":"Triglyceriden zijn vetten opgebouwd uit glycerol met drie vetzuren; ze zijn de belangrijkste energieopslag in vetweefsel.","definition":"<p><strong>Triglyceriden</strong> worden uit de voeding via chylomicronen en uit de lever via VLDL door het bloed vervoerd. Lipoproteïnelipase in de capillairen splitst ze, zodat vetzuren in spier- en vetweefsel worden opgenomen. Een verhoogd triglyceridengehalte komt voor bij obesitas, diabetes, alcoholgebruik en erfelijke vetstofwisselingsstoornissen; zeer hoge waarden geven risico op pancreatitis.</p>","image_url":"","wiki_title":"Triglyceride","match":"triglyceriden|triglyceride|triacylglycerol","option_only":true},"pepsinogeen":{"title":"Pepsinogeen","short":"Pepsinogeen is het inactieve voorstadium van pepsine, gemaakt door de hoofdcellen van de maag.","definition":"<p><strong>Pepsinogeen</strong> wordt afgegeven door hoofdcellen in de maagklieren. In het zure milieu (pH &lt; 4) splitst het zichzelf tot actief <em>pepsine</em>, een protease dat de eiwitvertering start. Pepsine wordt geïnactiveerd in het neutrale milieu van het duodenum.</p>","image_url":"","wiki_title":"Pepsin","match":"pepsinogeen|pepsine","option_only":true},"a. mesenterica inferior":{"title":"A. mesenterica inferior","short":"De a. mesenterica inferior voorziet het distale derde van het colon transversum, het colon descendens, sigmoïd en bovenste rectum.","definition":"<p>De <strong>a. mesenterica inferior</strong> ontspringt ter hoogte van L3 uit de aorta abdominalis. Haar takken zijn de a. colica sinistra, de aa. sigmoideae en de a. rectalis superior. Via de arcade van Riolan en de marginale arterie (van Drummond) staat ze in verbinding met de a. mesenterica superior.</p>","image_url":"","wiki_title":"Inferior mesenteric artery","match":"a. mesenterica inferior|arteria mesenterica inferior","option_only":true},"arteria gastrica sinistra":{"title":"A. gastrica sinistra","short":"De a. gastrica sinistra is een tak van de truncus coeliacus die de kleine curvatuur van de maag en de distale slokdarm voorziet.","definition":"<p>De <strong>a. gastrica sinistra</strong> is de kleinste tak van de truncus coeliacus. Ze loopt naar de cardia, geeft takjes aan de distale oesophagus en loopt dan langs de kleine curvatuur, waar ze anastomoseert met de a. gastrica dextra. Een ulcus aan de kleine curvatuur kan uit deze arterie bloeden.</p>","image_url":"","wiki_title":"Left gastric artery","match":"arteria gastrica sinistra|a. gastrica sinistra","option_only":true},"vena hepatica":{"title":"Vena hepatica (levervene)","short":"De venae hepaticae voeren het bloed uit de lever af naar de vena cava inferior.","definition":"<p>De drie grote <strong>venae hepaticae</strong> (rechts, midden, links) verzamelen het bloed uit de centrale venen van de leverlobjes en monden vlak onder het diafragma uit in de vena cava inferior. Ze lopen tussen de leversegmenten in. Afsluiting ervan heet het syndroom van Budd-Chiari.</p>","image_url":"","wiki_title":"Hepatic veins","match":"vena hepatica|v. hepatica|venae hepaticae|levervene","option_only":true},"salmonella enteritidis":{"title":"Salmonella enteritidis","short":"Salmonella enteritidis is een gramnegatieve staaf die via besmette eieren en kip een voedselinfectie met diarree en koorts veroorzaakt.","definition":"<p>Niet-tyfeuze <strong>salmonellae</strong> zoals <em>S. enteritidis</em> komen via onvoldoende verhitte eieren, kip of besmet voedsel binnen. Na 6–72 uur ontstaan koorts, buikkrampen en diarree, meestal zelflimiterend. Bij zuigelingen, ouderen, afweergestoorden en mensen met vaatprothesen kan bacteriëmie optreden. Antibiotica zijn meestal niet nodig.</p>","image_url":"","wiki_title":"Salmonella enterica","match":"salmonella enteritidis|salmonella|salmonellose","option_only":true},"campylobacter jejuni":{"title":"Campylobacter jejuni","short":"Campylobacter jejuni is een gekromde gramnegatieve staaf en een belangrijke oorzaak van bacteriële gastro-enteritis, vaak via kip.","definition":"<p><strong><em>Campylobacter jejuni</em></strong> wordt opgelopen via onvoldoende verhit gevogelte, rauwe melk of besmet water. Het geeft koorts, buikkrampen en (soms bloederige) diarree. Een bekende late complicatie is het syndroom van Guillain-Barré, door kruisreactie van antistoffen met gangliosiden in zenuwen; ook reactieve artritis komt voor.</p>","image_url":"","wiki_title":"Campylobacter jejuni","match":"campylobacter jejuni|campylobacter","option_only":true},"yersinia enterocolitica":{"title":"Yersinia enterocolitica","short":"Yersinia enterocolitica is een gramnegatieve staaf die via varkensvlees een enterocolitis kan veroorzaken die appendicitis kan nabootsen.","definition":"<p><strong><em>Yersinia enterocolitica</em></strong> groeit ook bij lage temperatuur. Infectie geeft koorts, diarree en buikpijn; door ontsteking van het terminale ileum en de mesenteriale lymfeklieren kan het beeld lijken op appendicitis (pseudo-appendicitis). Na infectie kunnen reactieve artritis en erythema nodosum ontstaan, vooral bij HLA-B27-dragers. IJzerstapeling (hemochromatose) is een risicofactor voor ernstige infectie.</p>","image_url":"","wiki_title":"Yersinia enterocolitica","match":"yersinia enterocolitica|yersinia","option_only":true},"reizigersdiarree":{"title":"Reizigersdiarree","short":"Reizigersdiarree is diarree die optreedt tijdens of kort na een reis, meestal door besmet voedsel of water.","definition":"<p><strong>Reizigersdiarree</strong> wordt meestal veroorzaakt door bacteriën, met enterotoxigene <em>E. coli</em> als belangrijkste verwekker; daarnaast <em>Campylobacter</em>, <em>Shigella</em>, <em>Salmonella</em>, virussen en parasieten zoals <em>Giardia</em>. Het is meestal zelflimiterend binnen enkele dagen. De basis van de behandeling is het aanvullen van vocht en zouten (ORS).</p>","image_url":"","wiki_title":"Travelers' diarrhea","match":"reizigersdiarree","option_only":true},"hepatitis c":{"title":"Hepatitis C","short":"Hepatitis C is een via bloed overgedragen RNA-virus dat vaak chronisch wordt en tot cirrose en levercelkanker kan leiden.","definition":"<p>Het <strong>hepatitis C-virus</strong> (flavivirus) wordt vooral via bloed overgedragen (drugsgebruik met naalden, vroeger transfusies). Een acute infectie verloopt meestal zonder klachten, maar wordt in de meerderheid chronisch. Na jaren kunnen fibrose, cirrose en hepatocellulair carcinoom ontstaan. Er is geen vaccin, maar direct werkende antivirale middelen genezen de infectie in vrijwel alle gevallen.</p>","image_url":"","wiki_title":"Hepatitis C","match":"hepatitis c|hcv|hepatitis c-virus","option_only":true},"hepatitis d":{"title":"Hepatitis D","short":"Hepatitis D is een defect virus dat alleen samen met hepatitis B kan vermenigvuldigen en een ernstiger leverziekte geeft.","definition":"<p>Het <strong>hepatitis D-virus</strong> heeft het oppervlakte-antigeen van hepatitis B (HBsAg) nodig voor zijn envelop. Het kan dus alleen tegelijk met HBV (co-infectie) of bij iemand met chronische HBV (superinfectie) voorkomen. Superinfectie leidt vaak tot snel progressieve leverziekte. Vaccinatie tegen hepatitis B beschermt ook tegen hepatitis D.</p>","image_url":"","wiki_title":"Hepatitis D","match":"hepatitis d|hdv|deltahepatitis","option_only":true},"giardiasis":{"title":"Giardiasis","short":"Giardiasis is een darminfectie met de protozo Giardia lamblia, met langdurige diarree, opgeblazen gevoel en vetrijke ontlasting.","definition":"<p><strong><em>Giardia lamblia</em></strong> wordt via cysten in besmet water of voedsel opgelopen. De trofozoïeten hechten aan het dunnedarmepitheel zonder het te binnendringen. Klachten: waterige, vettige, stinkende ontlasting, buikkrampen, winderigheid en gewichtsverlies, soms wekenlang. Diagnose met PCR of microscopie van ontlasting; behandeling met metronidazol of tinidazol.</p>","image_url":"","wiki_title":"Giardiasis","match":"giardiasis|giardia lamblia|giardia","option_only":true},"strongyloidiasis":{"title":"Strongyloidiasis","short":"Strongyloidiasis is een infectie met de draadworm Strongyloides stercoralis, die zich in de mens kan blijven vermenigvuldigen.","definition":"<p>Larven van <strong><em>Strongyloides stercoralis</em></strong> dringen via de huid binnen (blootsvoets lopen in de tropen), reizen via de longen naar de darm en kunnen de mens opnieuw infecteren (auto-infectie), waardoor infecties decennia kunnen blijven bestaan. Vaak zijn er weinig klachten en eosinofilie. Bij immuunsuppressie (vooral corticosteroïden) kan een levensbedreigende hyperinfectie ontstaan. Behandeling met ivermectine.</p>","image_url":"","wiki_title":"Strongyloidiasis","match":"strongyloidiasis|strongyloides stercoralis|strongyloides","option_only":true},"antibiotica":{"title":"Antibiotica","short":"Antibiotica zijn middelen die bacteriën doden of hun groei remmen; ze werken niet tegen virussen.","definition":"<p><strong>Antibiotica</strong> grijpen aan op structuren die bacteriën wel en menselijke cellen niet (of anders) hebben: de celwand (bètalactams, vancomycine), het ribosoom (o.a. macroliden, tetracyclines, aminoglycosiden), DNA-synthese (chinolonen, metronidazol) of foliumzuursynthese (trimethoprim, sulfonamiden). Bacteriostatisch betekent groeiremmend, bactericide dodend. Onnodig gebruik bevordert resistentie.</p>","image_url":"","wiki_title":"Antibiotic","match":"antibiotica|antibioticum","option_only":true},"laryngitis":{"title":"Laryngitis","short":"Laryngitis is een ontsteking van het strottenhoofd, met heesheid en soms keelpijn en hoesten.","definition":"<p>Acute <strong>laryngitis</strong> is meestal viraal en gaat vaak samen met een verkoudheid; ook stembelasting kan een oorzaak zijn. De stembanden zwellen, wat heesheid of stemverlies geeft. Bij jonge kinderen kan een subglottische laryngitis (pseudokroep) een blafhoest en inspiratoire stridor geven. Chronische laryngitis kan ontstaan door roken of reflux.</p>","image_url":"","wiki_title":"Laryngitis","match":"laryngitis|strottenhoofdontsteking","option_only":true},"ct-thorax":{"title":"CT-thorax","short":"Een CT-thorax is een röntgenscan in dwarsdoorsneden van de borstkas, gedetailleerder dan een X-thorax.","definition":"<p>Een <strong>CT-thorax</strong> geeft een driedimensionaal beeld van longen, mediastinum, pleura en thoraxwand. Met intraveneus contrast (CT-angiografie) is het het standaardonderzoek bij verdenking op longembolie. Een hoge-resolutie-CT (HRCT) is geschikt voor interstitiële longziekten; een lage-dosis-CT wordt gebruikt voor screening en follow-up van longnodules.</p>","image_url":"","wiki_title":"CT scan","match":"ct-thorax|ct thorax|ct van de thorax","option_only":true},"ileus":{"title":"Ileus","short":"Een ileus is een stilstand van de darmpassage, door een mechanische afsluiting of door verlamming van de darm.","definition":"<p>Bij een <strong>mechanische ileus</strong> is de darm afgesloten, bijvoorbeeld door verklevingen, een beklemde hernia, een tumor of een volvulus; er zijn koliekachtige buikpijn, braken, een opgezette buik en hoogklinkende peristaltiek. Bij een <strong>paralytische ileus</strong> (na operaties, bij peritonitis, elektrolytstoornissen of medicatie) staat de darm stil en is het stil bij auscultatie. Diagnose met X-buikoverzicht of CT.</p>","image_url":"","wiki_title":"Bowel obstruction","match":"ileus|darmafsluiting","option_only":true},"gastritis":{"title":"Gastritis","short":"Gastritis is een ontsteking van het maagslijmvlies, meestal door Helicobacter pylori, NSAID's of alcohol.","definition":"<p><strong>Gastritis</strong> kan acuut of chronisch zijn. Chronische actieve gastritis wordt vooral veroorzaakt door <em>Helicobacter pylori</em> en kan leiden tot atrofie, intestinale metaplasie en een verhoogd risico op maagcarcinoom en MALT-lymfoom. Auto-immuungastritis treft vooral het corpus, met vitamine B12-tekort. Veel patiënten hebben geen klachten.</p>","image_url":"","wiki_title":"Gastritis","match":"gastritis|maagslijmvliesontsteking","option_only":true},"helicobacter pylori":{"title":"Helicobacter pylori","short":"Helicobacter pylori is een gekromde gramnegatieve bacterie die in de maag leeft en gastritis, ulcera, maagcarcinoom en MALT-lymfoom kan veroorzaken.","definition":"<p><strong><em>Helicobacter pylori</em></strong> overleeft in het zure milieu door urease, dat ureum omzet in ammoniak, en nestelt zich onder de slijmlaag. Besmetting gebeurt meestal op jonge leeftijd. Diagnose met een ademtest, antigeentest in de ontlasting of biopten. Eradicatie gebeurt met een protonpompremmer en twee antibiotica.</p>","image_url":"","wiki_title":"Helicobacter pylori","match":"helicobacter pylori|h. pylori|helicobacter","option_only":true},"appendicitis":{"title":"Appendicitis","short":"Appendicitis is een ontsteking van de appendix, met buikpijn die vaak rond de navel begint en naar rechtsonder trekt.","definition":"<p>Bij <strong>appendicitis</strong> raakt het lumen van de appendix afgesloten (bijv. door een fecoliet of lymfoïde hyperplasie), waarna ontsteking en infectie volgen. Klachten: pijn eerst rond de navel, later rechtsonder (McBurney), misselijkheid, koorts en lokale peritoneale prikkeling. Zonder behandeling kan perforatie optreden. Diagnose met echo en/of CT; behandeling meestal appendectomie.</p>","image_url":"","wiki_title":"Appendicitis","match":"appendicitis|blindedarmontsteking","option_only":true},"coloncarcinoom":{"title":"Coloncarcinoom (darmkanker)","short":"Coloncarcinoom is een kwaadaardige tumor van de dikke darm, meestal een adenocarcinoom dat ontstaat uit een poliep.","definition":"<p>Het <strong>colorectaal carcinoom</strong> ontstaat meestal via de adenoom-carcinoomsequentie, waarbij mutaties (o.a. in APC, KRAS, p53) zich opstapelen. Risicofactoren zijn leeftijd, familiaire belasting (FAP, Lynch-syndroom), IBD, rood en bewerkt vlees, alcohol en roken. Klachten: veranderd ontlastingspatroon, bloed bij de ontlasting en ijzergebreksanemie. In Nederland is er een bevolkingsonderzoek met de FIT-test.</p>","image_url":"","wiki_title":"Colorectal cancer","match":"coloncarcinoom|darmkanker|colorectaal carcinoom|dikkedarmkanker","option_only":true},"colitis ulcerosa":{"title":"Colitis ulcerosa","short":"Colitis ulcerosa is een chronische ontstekingsziekte van het slijmvlies van de dikke darm, die altijd in het rectum begint en zich doorlopend naar proximaal uitbreidt.","definition":"<p>Bij <strong>colitis ulcerosa</strong> is alleen de mucosa ontstoken, zonder ‘skip lesions’. Klachten: bloederige diarree met slijm, aandrang en buikkrampen. Extra-intestinale verschijnselen zijn o.a. artritis, uveïtis, erythema nodosum en primaire scleroserende cholangitis. Langdurige ziekte verhoogt het risico op coloncarcinoom. Roken lijkt (in tegenstelling tot bij Crohn) beschermend.</p>","image_url":"","wiki_title":"Ulcerative colitis","match":"colitis ulcerosa|ulceratieve colitis","option_only":true},"coeliakie":{"title":"Coeliakie","short":"Coeliakie is een auto-immuunziekte waarbij gluten een ontsteking van de dunne darm met vlokatrofie veroorzaken.","definition":"<p>Bij <strong>coeliakie</strong> (geassocieerd met HLA-DQ2/DQ8) wordt gliadine door weefseltransglutaminase gemodificeerd en daarna door T-cellen herkend, wat leidt tot vlokatrofie en crypthyperplasie. Klachten: diarree, buikpijn, gewichtsverlies, groeiachterstand, ijzergebrek en vermoeidheid, maar ook atypische presentaties. Diagnose met anti-tTG-antistoffen en een duodenumbiopt; behandeling is een levenslang glutenvrij dieet.</p>","image_url":"","wiki_title":"Coeliac disease","match":"coeliakie|glutenintolerantie|glutenenteropathie","option_only":true},"gastroenteritis":{"title":"Gastro-enteritis","short":"Gastro-enteritis is een ontsteking van maag en darm, meestal door een virus, met braken en diarree.","definition":"<p>Acute <strong>gastro-enteritis</strong> wordt meestal veroorzaakt door virussen (norovirus, rotavirus), soms door bacteriën (<em>Campylobacter</em>, <em>Salmonella</em>) of parasieten. Het belangrijkste risico is uitdroging, vooral bij jonge kinderen en ouderen. Behandeling bestaat vooral uit orale rehydratie; antibiotica zijn zelden nodig.</p>","image_url":"","wiki_title":"Gastroenteritis","match":"gastroenteritis|gastro-enteritis|buikgriep","option_only":true},"peritonitis":{"title":"Peritonitis","short":"Peritonitis is een ontsteking van het buikvlies, meestal door een perforatie of infectie van een buikorgaan.","definition":"<p><strong>Secundaire peritonitis</strong> ontstaat bij perforatie (bijv. ulcus, appendicitis, diverticulitis) of na buikoperaties. Klachten: hevige buikpijn, koorts, een plankharde buik met défense musculaire en loslaatpijn, en een stille buik. Spontane bacteriële peritonitis komt voor bij ascites door levercirrose. Behandeling: antibiotica en vaak chirurgie.</p>","image_url":"","wiki_title":"Peritonitis","match":"peritonitis|buikvliesontsteking","option_only":true},"peritoneum":{"title":"Peritoneum (buikvlies)","short":"Het peritoneum is het sereuze vlies dat de buikwand (pariëtaal) en de buikorganen (visceraal) bekleedt.","definition":"<p>Het <strong>peritoneum</strong> bestaat uit mesotheel op een laagje bindweefsel. Tussen het pariëtale en viscerale blad ligt de peritoneaalholte met een klein beetje vocht. Organen kunnen intraperitoneaal liggen (bijv. maag, jejunum, ileum, colon transversum) of retroperitoneaal (bijv. nieren, pancreas, duodenum grotendeels). Het pariëtale blad is pijngevoelig en goed te lokaliseren, het viscerale niet.</p>","image_url":"","wiki_title":"Peritoneum","match":"peritoneum|buikvlies","option_only":true},"maagperforatie":{"title":"Maagperforatie","short":"Bij een maagperforatie ontstaat een gat in de maagwand, meestal door een ulcus, waardoor maaginhoud in de buikholte lekt.","definition":"<p>Een <strong>perforatie</strong> van maag of duodenum geeft plotselinge, hevige bovenbuikpijn die zich snel over de hele buik uitbreidt, met een plankharde buik (chemische peritonitis). Op een staande X-thorax of CT is vrij lucht onder het diafragma te zien. Risicofactoren zijn NSAID-gebruik, <em>H. pylori</em> en roken. Behandeling is meestal chirurgisch sluiten.</p>","image_url":"","wiki_title":"Gastrointestinal perforation","match":"maagperforatie|perforatie van de maag|ulcusperforatie","option_only":true},"refluxklachten":{"title":"Gastro-oesofageale reflux","short":"Bij refluxklachten stroomt maaginhoud terug in de slokdarm, met zuurbranden en oprispingen.","definition":"<p><strong>Gastro-oesofageale refluxziekte</strong> ontstaat bij een tekortschietende onderste slokdarmsfincter, een hiatus hernia of verhoogde druk in de buik (overgewicht, zwangerschap). Klachten zijn zuurbranden achter het borstbeen en zure oprispingen, soms hoesten of heesheid. Complicaties: oesofagitis, stenose en Barrett-slokdarm. Behandeling met leefstijladviezen en protonpompremmers.</p>","image_url":"","wiki_title":"Gastroesophageal reflux disease","match":"refluxklachten|reflux|gastro-oesofageale reflux|zuurbranden|refluxziekte","option_only":true},"movicolon":{"title":"Macrogol (Movicolon)","short":"Movicolon is een osmotisch laxans op basis van macrogol dat water in de darm vasthoudt en de ontlasting zachter maakt.","definition":"<p><strong>Macrogol</strong> (polyethyleenglycol) wordt nauwelijks opgenomen en bindt water in het darmlumen, waardoor de ontlasting zachter en volumineuzer wordt. Het is een eerste keus laxans bij obstipatie, ook bij kinderen en bij opioïdgebruik. De elektrolyten in Movicolon voorkomen netto zoutverlies.</p>","image_url":"","wiki_title":"Polyethylene glycol","match":"movicolon|macrogol","option_only":true},"gastro-duodenoscopie":{"title":"Gastroduodenoscopie","short":"Bij een gastroduodenoscopie worden slokdarm, maag en duodenum met een flexibele endoscoop bekeken.","definition":"<p>Bij een <strong>gastroduodenoscopie</strong> gaat een flexibele scoop via de mond naar het duodenum. Er kunnen biopten worden genomen (bijv. voor coeliakie of H. pylori) en behandelingen worden uitgevoerd, zoals het stelpen van een bloeding of het oprekken van een stenose. Het onderzoek gebeurt met keelverdoving, eventueel met sedatie.</p>","image_url":"","wiki_title":"Esophagogastroduodenoscopy","match":"gastro-duodenoscopie|gastroduodenoscopie|gastroscopie","option_only":true},"coloscopie":{"title":"Coloscopie","short":"Bij een coloscopie wordt de hele dikke darm met een flexibele endoscoop bekeken, na darmvoorbereiding.","definition":"<p>Een <strong>coloscopie</strong> wordt gedaan bij o.a. bloed bij de ontlasting, een veranderd ontlastingspatroon, ijzergebreksanemie, een positieve FIT-test en voor surveillance bij poliepen of IBD. Poliepen kunnen direct worden verwijderd en er kunnen biopten worden genomen. Risico's zijn bloeding en (zelden) perforatie.</p>","image_url":"","wiki_title":"Colonoscopy","match":"coloscopie|colonoscopie","option_only":true},"diagnostische laparoscopie":{"title":"Diagnostische laparoscopie","short":"Bij een diagnostische laparoscopie wordt via kleine sneetjes met een camera in de buikholte gekeken.","definition":"<p>Bij een <strong>laparoscopie</strong> wordt de buik opgeblazen met CO₂ en via kleine incisies een camera en instrumenten ingebracht. Het wordt diagnostisch gebruikt bij onduidelijke buikpijn, verdenking op endometriose of buitenbaarmoederlijke zwangerschap en voor stadiëring van tumoren; vaak kan in dezelfde ingreep worden behandeld.</p>","image_url":"","wiki_title":"Laparoscopy","match":"diagnostische laparoscopie|laparoscopie|kijkoperatie","option_only":true},"mri abdomen":{"title":"MRI-abdomen","short":"Een MRI van de buik maakt met een magneetveld gedetailleerde beelden van de buikorganen, zonder röntgenstraling.","definition":"<p>Een <strong>MRI-abdomen</strong> is vooral geschikt voor het karakteriseren van lever- en pancreaslaesies, het afbeelden van de galwegen (MRCP), de dunne darm bij de ziekte van Crohn en het rectum bij stadiëring van rectumcarcinoom. Het duurt langer dan een CT en is gevoeliger voor beweging; metalen implantaten kunnen een contra-indicatie zijn.</p>","image_url":"","wiki_title":"Magnetic resonance imaging","match":"mri abdomen|mri van de buik|mri-abdomen","option_only":true},"mri":{"title":"MRI","short":"MRI maakt met een sterk magneetveld en radiogolven gedetailleerde beelden van weke delen, zonder ioniserende straling.","definition":"<p>Bij <strong>MRI</strong> worden waterstofkernen in een sterk magneetveld door radiogolven aangeslagen; het signaal bij terugkeer verschilt per weefseltype. MRI is bijzonder geschikt voor hersenen, ruggenmerg, gewrichten, weke delen en het bekken. Nadelen zijn de lange duur, kosten en beperkingen bij pacemakers en sommige metalen implantaten.</p>","image_url":"","wiki_title":"Magnetic resonance imaging","match":"mri|mri-scan|magnetic resonance imaging","option_only":true},"x-boz":{"title":"X-buikoverzicht (X-BOZ)","short":"Een X-buikoverzicht is een röntgenfoto van de buik, vooral gebruikt om darmafsluiting of vrij lucht aan te tonen.","definition":"<p>Een <strong>X-BOZ</strong> toont darmgaspatronen, verwijde darmlissen met vloeistofspiegels (ileus), vrij lucht (perforatie, beter te zien op een staande X-thorax), stenen en vreemde voorwerpen. Door de beperkte informatie is het in veel situaties vervangen door een echo of CT.</p>","image_url":"","wiki_title":"Abdominal x-ray","match":"x-boz|buikoverzichtsfoto|x-buikoverzicht","option_only":true},"ijzergebreksanemie":{"title":"IJzergebreksanemie","short":"IJzergebreksanemie is bloedarmoede door een tekort aan ijzer, met kleine, bleke rode bloedcellen.","definition":"<p><strong>IJzergebreksanemie</strong> geeft een microcytaire, hypochrome anemie met een laag ferritine. Oorzaken zijn bloedverlies (menstruatie, maag-darmkanaal), te weinig inname, verhoogde behoefte (groei, zwangerschap) of verminderde opname (coeliakie, maagresectie). Bij mannen en vrouwen na de menopauze moet een bron van bloedverlies in de tractus digestivus worden uitgesloten.</p>","image_url":"","wiki_title":"Iron-deficiency anemia","match":"ijzergebreksanemie|ijzergebrek","option_only":true},"hemolyse":{"title":"Hemolyse","short":"Hemolyse is het voortijdig afbreken van rode bloedcellen, in de bloedbaan of in milt en lever.","definition":"<p>Bij <strong>hemolyse</strong> zijn het LDH en ongeconjugeerd bilirubine verhoogd, het haptoglobine verlaagd en het aantal reticulocyten gestegen. Oorzaken kunnen in de cel liggen (membraandefecten zoals sferocytose, enzymdefecten zoals G6PD-deficiëntie, hemoglobinopathieën) of erbuiten (auto-antistoffen, transfusiereacties, mechanische beschadiging, infecties zoals malaria). Hemolyse kan ook een kunstmatige laboratoriumfout zijn bij moeizame bloedafname.</p>","image_url":"","wiki_title":"Hemolysis","match":"hemolyse|hemolytische anemie","option_only":true},"hemochromatose":{"title":"Hemochromatose","short":"Hemochromatose is een erfelijke ijzerstapelingsziekte waarbij te veel ijzer uit de darm wordt opgenomen.","definition":"<p>Bij <strong>hereditaire hemochromatose</strong> (meestal homozygotie voor de C282Y-mutatie in het HFE-gen) is er te weinig hepcidine, waardoor ijzer ongeremd wordt opgenomen. IJzer stapelt in lever, pancreas, hart, gewrichten en huid, met leverfibrose of -cirrose, diabetes, cardiomyopathie, artropathie en een bronzen huid. De transferrineverzadiging en het ferritine zijn verhoogd; behandeling met aderlatingen.</p>","image_url":"","wiki_title":"Hemochromatosis","match":"hemochromatose|hereditaire hemochromatose|ijzerstapeling","option_only":true},"bloedtransfusie":{"title":"Bloedtransfusie","short":"Bij een bloedtransfusie krijgt een patiënt bloed of bloedproducten (erytrocyten, plaatjes, plasma) van een donor.","definition":"<p>Bij een <strong>erytrocytentransfusie</strong> moeten de AB0- en rhesusbloedgroepen en eventuele irregulaire antistoffen passen. Risico's zijn o.a. een acute hemolytische reactie bij AB0-incompatibiliteit, koorts- en allergische reacties, overvulling (TACO), transfusiegerelateerde longschade (TRALI) en, zeldzaam, infecties. Een transfusie wordt gegeven op basis van klinische noodzaak en een Hb-drempel.</p>","image_url":"","wiki_title":"Blood transfusion","match":"bloedtransfusie|transfusie","option_only":true},"igg":{"title":"IgG","short":"IgG is de meest voorkomende antistofklasse in het bloed; het is belangrijk bij de secundaire immuunrespons en passeert de placenta.","definition":"<p><strong>IgG</strong> is een monomeer en heeft vier subklassen. Het werkt via neutralisatie, opsonisatie (via Fcγ-receptoren op fagocyten) en complementactivatie. Het is de belangrijkste antistof bij een herhaalde blootstelling en de enige klasse die actief via de placenta naar de foetus gaat, wat pasgeborenen maandenlang beschermt.</p>","image_url":"","wiki_title":"Immunoglobulin G","match":"igg|immunoglobuline g","option_only":true},"ifn-α":{"title":"Interferon-alfa","short":"Interferon-alfa is een type I-interferon dat door geïnfecteerde cellen wordt gemaakt en naburige cellen in een antivirale toestand brengt.","definition":"<p><strong>Type I-interferonen</strong> (IFN-α en IFN-β) worden vooral door plasmacytoïde dendritische cellen en geïnfecteerde cellen afgegeven. Ze remmen virale replicatie in omliggende cellen, verhogen de MHC-I-expressie en activeren NK-cellen. Als geneesmiddel werd interferon-alfa gebruikt bij chronische hepatitis B en C en sommige maligniteiten; bijwerkingen zijn griepachtige klachten en depressie.</p>","image_url":"","wiki_title":"Interferon type I","match":"ifn-α|ifn-alfa|interferon-alfa|interferon alfa|type i interferon","option_only":true},"osteoporose":{"title":"Osteoporose","short":"Osteoporose is een verlaagde botmassa met verzwakte botstructuur, waardoor botten sneller breken.","definition":"<p>Bij <strong>osteoporose</strong> is de afbraak van bot groter dan de opbouw. Risicofactoren: hoge leeftijd, postmenopauzaal oestrogeentekort, corticosteroïden, laag lichaamsgewicht, roken, alcohol en weinig beweging. Typische fracturen zijn wervelinzakkingen, heupfracturen en distale radiusfracturen. Diagnose met een DEXA-scan (T-score ≤ −2,5); behandeling o.a. met bisfosfonaten, calcium en vitamine D.</p>","image_url":"","wiki_title":"Osteoporosis","match":"osteoporose|botontkalking","option_only":true},"infliximab":{"title":"Infliximab","short":"Infliximab is een monoklonaal antilichaam tegen TNF-α, gebruikt bij o.a. de ziekte van Crohn, colitis ulcerosa en reumatoïde artritis.","definition":"<p><strong>TNF-α-remmers</strong> zoals infliximab, adalimumab en etanercept remmen een centraal pro-inflammatoir cytokine. Ze worden gebruikt bij IBD, reumatoïde artritis, spondyloartritis en psoriasis. Doordat ze de cellulaire afweer verzwakken, kan latente tuberculose reactiveren; daarom wordt vooraf gescreend. Ook het risico op andere infecties is verhoogd.</p>","image_url":"","wiki_title":"Infliximab","match":"infliximab|anti-tnf|tnf-alfa antagonist|tnf-remmer","option_only":true},"azathioprine":{"title":"Azathioprine","short":"Azathioprine is een immunosuppressivum dat de purinesynthese remt en zo de deling van lymfocyten onderdrukt.","definition":"<p><strong>Azathioprine</strong> wordt omgezet in 6-mercaptopurine en dan in thioguanine-nucleotiden die in het DNA worden ingebouwd. Het wordt gebruikt bij IBD, auto-immuunhepatitis, vasculitis en na transplantatie. Bijwerkingen zijn beenmergsuppressie, levertoxiciteit en pancreatitis. Bij een TPMT-deficiëntie is het risico op ernstige beenmergsuppressie groot; allopurinol versterkt de werking.</p>","image_url":"","wiki_title":"Azathioprine","match":"azathioprine","option_only":true},"methotrexaat":{"title":"Methotrexaat","short":"Methotrexaat is een foliumzuurantagonist; in lage dosis een basismiddel bij reumatoïde artritis en psoriasis, in hoge dosis een cytostaticum.","definition":"<p><strong>Methotrexaat</strong> remt dihydrofolaatreductase. In lage, wekelijkse dosering werkt het ontstekingsremmend (o.a. via adenosine) en is het een hoeksteen bij reumatoïde artritis, psoriasis en IBD; foliumzuur vermindert bijwerkingen. Bijwerkingen: beenmergsuppressie, levertoxiciteit, mucositis en pneumonitis. Het is teratogeen en wordt via de nier uitgescheiden.</p>","image_url":"","wiki_title":"Methotrexate","match":"methotrexaat|mtx|methotrexate","option_only":true},"nsaids":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"nsaids|nsaid|nsaid's|antiflogistica|ontstekingsremmers","option_only":true},"speekselvloed":{"title":"Speekselvloed (sialorroe)","short":"Speekselvloed is overmatig speeksel in de mond of kwijlen, door teveel productie of slecht slikken.","definition":"<p><strong>Sialorroe</strong> kan ontstaan door verhoogde productie (bijv. door clozapine, cholinerge middelen, misselijkheid, tandproblemen) of, vaker, door verminderd slikken of slechte mondsluiting, zoals bij de ziekte van Parkinson, ALS, een beroerte of cerebrale parese.</p>","image_url":"","wiki_title":"Drooling","match":"speekselvloed|sialorroe|hypersalivatie|kwijlen","option_only":true},"curatief":{"title":"Curatief","short":"Een curatieve behandeling heeft als doel genezing.","definition":"<p>Bij een <strong>curatieve</strong> intentie wordt geprobeerd een ziekte volledig te genezen, bijvoorbeeld een tumor volledig te verwijderen. Daartegenover staat palliatieve behandeling, gericht op het verlichten van klachten en het verlengen van leven zonder genezing.</p>","image_url":"","wiki_title":"","match":"curatief|curatieve behandeling","option_only":true},"palliatief":{"title":"Palliatief","short":"Palliatieve zorg is gericht op kwaliteit van leven bij een ongeneeslijke ziekte, door klachten te verlichten en ondersteuning te bieden.","definition":"<p><strong>Palliatieve zorg</strong> omvat lichamelijke, psychische, sociale en spirituele zorg voor patiënten met een levensbedreigende aandoening en hun naasten. Een palliatieve behandeling (bijv. radiotherapie bij botpijn) kan het leven verlengen of klachten verminderen, maar heeft genezing niet als doel.</p>","image_url":"","wiki_title":"Palliative care","match":"palliatief|palliatieve zorg|palliatieve behandeling","option_only":true},"adjuvant":{"title":"Adjuvante behandeling","short":"Een adjuvante behandeling wordt na de primaire (meestal chirurgische) behandeling gegeven om de kans op terugkeer van kanker te verkleinen.","definition":"<p>Bij <strong>adjuvante</strong> therapie (bijv. chemotherapie, radiotherapie of hormonale therapie na een operatie) is er geen zichtbare tumor meer, maar wil men eventuele micrometastasen behandelen. <em>Neoadjuvante</em> behandeling wordt juist vóór de operatie gegeven om de tumor te verkleinen.</p>","image_url":"","wiki_title":"Adjuvant therapy","match":"adjuvant|adjuvante behandeling|adjuvante therapie","option_only":true},"totale parenterale voeding":{"title":"Totale parenterale voeding (TPV)","short":"Bij totale parenterale voeding krijgt iemand alle voedingsstoffen via een infuus in een centrale ader.","definition":"<p><strong>TPV</strong> wordt gegeven als het maag-darmkanaal niet bruikbaar is of onvoldoende functioneert, zoals bij darmfalen, een langdurige ileus of een korte-darmsyndroom. Omdat de oplossing sterk geconcentreerd is, gaat het via een centrale lijn. Complicaties zijn lijninfecties, trombose, leververvetting en metabole ontregeling (zoals het refeedingsyndroom). Enterale voeding heeft de voorkeur als de darm werkt.</p>","image_url":"","wiki_title":"Parenteral nutrition","match":"totale parenterale voeding|tpv|parenterale voeding","option_only":true},"lisdiureticum":{"title":"Lisdiureticum","short":"Lisdiuretica remmen de NKCC2-cotransporter in de lis van Henle en zijn de krachtigste plasmiddelen.","definition":"<p><strong>Lisdiuretica</strong> zoals furosemide remmen de Na⁺/K⁺/2Cl⁻-cotransporter in het dikke opstijgende deel van de lis van Henle. Ze worden gebruikt bij oedeem door hartfalen, nierziekte of levercirrose en bij longoedeem. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, metabole alkalose, uitdroging en ototoxiciteit; anders dan thiaziden verhogen ze de calciumuitscheiding.</p>","image_url":"","wiki_title":"Loop diuretic","match":"lisdiureticum|lisdiuretica|furosemide|bumetanide","option_only":true},"lactaat dehydrogenase (ld)":{"title":"Lactaatdehydrogenase (LDH)","short":"LDH is een enzym in vrijwel alle cellen dat pyruvaat en lactaat in elkaar omzet; een verhoogde bloedwaarde wijst op celschade.","definition":"<p><strong>Lactaatdehydrogenase</strong> zet pyruvaat om in lactaat (en omgekeerd) en regenereert daarbij NAD⁺, wat anaerobe glycolyse mogelijk maakt. In het bloed is LDH een aspecifieke marker van weefselschade: het is verhoogd bij hemolyse, myocardinfarct, leverschade, spierschade en snelgroeiende tumoren zoals lymfomen.</p>","image_url":"","wiki_title":"Lactate dehydrogenase","match":"lactaat dehydrogenase (ld)|lactaatdehydrogenase|ldh|ld","option_only":true},"ammoniak":{"title":"Ammoniak (ammonium)","short":"Ammoniak ontstaat bij de afbraak van aminozuren; de lever zet het om in ureum. Ophoping is giftig voor het brein.","definition":"<p><strong>Ammoniak</strong> wordt vooral in de darm (bacteriën) en uit aminozuren gevormd en via de v. portae naar de lever gevoerd, waar de ureumcyclus het onschadelijk maakt. Bij leverfalen of een portosystemische shunt stijgt het, wat bijdraagt aan hepatische encefalopathie. Ook erfelijke defecten in de ureumcyclus geven hyperammoniëmie.</p>","image_url":"","wiki_title":"Ammonia","match":"ammoniak|nh3|ammonium","option_only":true},"mutatie":{"title":"Mutatie","short":"Een mutatie is een blijvende verandering in de DNA-volgorde.","definition":"<p>Een <strong>mutatie</strong> kan één nucleotide betreffen (puntmutatie: silent, missense of nonsense), een kleine insertie of deletie (soms met frameshift), of grote stukken DNA en chromosomen. Mutaties in kiemcellen kunnen worden doorgegeven aan nakomelingen; somatische mutaties niet, maar die liggen wel ten grondslag aan kanker. Tegenwoordig spreekt men liever neutraal van een ‘variant’.</p>","image_url":"","wiki_title":"Mutation","match":"mutatie|mutaties|genmutatie","option_only":true},"auto-immuun hepatitis":{"title":"Auto-immuunhepatitis","short":"Auto-immuunhepatitis is een chronische leverontsteking waarbij het afweersysteem de hepatocyten aanvalt.","definition":"<p><strong>Auto-immuunhepatitis</strong> komt vaker voor bij vrouwen. Kenmerken zijn verhoogde transaminasen, een verhoogd IgG, auto-antistoffen (ANA, anti-SMA of anti-LKM1) en in het biopt een interfacehepatitis met plasmacellen. Zonder behandeling kan het tot cirrose leiden; het reageert meestal goed op prednison en azathioprine.</p>","image_url":"","wiki_title":"Autoimmune hepatitis","match":"auto-immuun hepatitis|auto-immuunhepatitis|autoimmuunhepatitis","option_only":true},"primaire biliaire cirrose (pbc)":{"title":"Primaire biliaire cholangitis (PBC)","short":"PBC is een auto-immuunziekte waarbij de kleine galgangen in de lever langzaam worden vernietigd.","definition":"<p><strong>Primaire biliaire cholangitis</strong> treft vooral vrouwen van middelbare leeftijd. Klachten: moeheid en jeuk; later icterus en cirrose. Kenmerkend zijn een verhoogd alkalisch fosfatase en γGT en antimitochondriale antistoffen (AMA). Ursodeoxycholzuur vertraagt het beloop.</p>","image_url":"","wiki_title":"Primary biliary cholangitis","match":"primaire biliaire cirrose (pbc)|primaire biliaire cholangitis|primaire biliaire cirrose|pbc","option_only":true},"alcoholische hepatitis":{"title":"Alcoholische hepatitis","short":"Alcoholische hepatitis is een acute leverontsteking door overmatig alcoholgebruik, met icterus, koorts en een vergrote, gevoelige lever.","definition":"<p>Bij <strong>alcoholische hepatitis</strong> ontstaat na jarenlang zwaar drinken een ontsteking met levercelnecrose, Mallory-Denk-lichaampjes en infiltratie van neutrofielen. Typisch is een ASAT dat hoger is dan het ALAT. Ernstige vormen hebben een hoge sterfte; behandeling bestaat uit alcoholstop, voeding en soms prednisolon.</p>","image_url":"","wiki_title":"Alcoholic hepatitis","match":"alcoholische hepatitis","option_only":true},"alcoholische pancreatitis":{"title":"Alcoholische pancreatitis","short":"Alcoholische pancreatitis is een acute of chronische ontsteking van de pancreas door overmatig alcoholgebruik.","definition":"<p>Alcohol is na galstenen de belangrijkste oorzaak van <strong>acute pancreatitis</strong>. Bij herhaalde aanvallen kan <strong>chronische pancreatitis</strong> ontstaan, met verkalkingen, chronische pijn, exocriene insufficiëntie (steatorroe) en diabetes. Stoppen met alcohol is essentieel.</p>","image_url":"","wiki_title":"Alcoholic pancreatitis","match":"alcoholische pancreatitis","option_only":true},"icterus":{"title":"Icterus (geelzucht)","short":"Icterus is gele verkleuring van huid, sclerae en slijmvliezen door een verhoogd bilirubine.","definition":"<p><strong>Icterus</strong> wordt meestal zichtbaar bij een bilirubine boven ongeveer 40–50 µmol/L. Men onderscheidt prehepatisch (hemolyse, vooral ongeconjugeerd bilirubine), hepatisch (leverziekte) en posthepatisch (galwegobstructie, met donkere urine en ontkleurde ontlasting). Bij pasgeborenen is lichte icterus in de eerste dagen fysiologisch.</p>","image_url":"","wiki_title":"Jaundice","match":"icterus|geelzucht","option_only":true},"tunica muscularis":{"title":"Tunica muscularis","short":"De tunica muscularis is de spierlaag van de wand van het maag-darmkanaal, meestal met een binnenste circulaire en buitenste longitudinale laag.","definition":"<p>De <strong>tunica muscularis</strong> zorgt voor peristaltiek en menging. Tussen de circulaire en longitudinale laag ligt de plexus myentericus (van Auerbach), die de motiliteit regelt. De maag heeft daarnaast een schuine binnenlaag. In het colon is de longitudinale laag samengetrokken tot drie taeniae coli.</p>","image_url":"","wiki_title":"Muscular layer","match":"tunica muscularis|muscularis propria|muscularis externa","option_only":true},"salpingitis":{"title":"Salpingitis","short":"Salpingitis is een ontsteking van de eileiders, meestal door een opstijgende seksueel overdraagbare infectie.","definition":"<p><strong>Salpingitis</strong> maakt deel uit van pelvic inflammatory disease (PID) en wordt vaak veroorzaakt door <em>Chlamydia trachomatis</em> of gonokokken. Klachten: onderbuikpijn, koorts, abnormale afscheiding en slingerpijn bij vaginaal toucher. Complicaties zijn tubo-ovarieel abces, verklevingen, buitenbaarmoederlijke zwangerschap en subfertiliteit.</p>","image_url":"","wiki_title":"Salpingitis","match":"salpingitis|eileiderontsteking|pelvic inflammatory disease|pid","option_only":true},"adenocarcinoom":{"title":"Adenocarcinoom","short":"Een adenocarcinoom is een kwaadaardige tumor van klierepitheel, zoals in darm, borst, prostaat, long en pancreas.","definition":"<p>Een <strong>adenocarcinoom</strong> vormt (verwaarloosde) klierstructuren of maakt slijm. Het is de meest voorkomende vorm van kanker van colon, maag, pancreas, prostaat, borst en een groot deel van het longcarcinoom. De mate van differentiatie (graad) en het stadium bepalen de prognose.</p>","image_url":"","wiki_title":"Adenocarcinoma","match":"adenocarcinoom|adenocarcinomen","option_only":true},"adenoom":{"title":"Adenoom","short":"Een adenoom is een goedaardige tumor van klierepitheel, bijvoorbeeld een darmpoliep of een hypofyseadenoom.","definition":"<p>Een <strong>adenoom</strong> groeit expansief en zaait niet uit, maar kan (zoals in de darm) via opeenstapeling van mutaties overgaan in een adenocarcinoom. Adenomen van endocriene klieren (bijv. hypofyse, bijnier, bijschildklier) kunnen hormonen produceren en daardoor klachten geven.</p>","image_url":"","wiki_title":"Adenoma","match":"adenoom|adenomen","option_only":true},"neuro-endocrien carcinoom":{"title":"Neuro-endocriene tumor","short":"Neuro-endocriene tumoren gaan uit van hormoonproducerende cellen, vooral in het maag-darmkanaal, de pancreas en de long.","definition":"<p><strong>Neuro-endocriene neoplasmata</strong> variëren van goed gedifferentieerde, langzaam groeiende tumoren (vroeger carcinoïden) tot agressieve, slecht gedifferentieerde carcinomen (zoals het kleincellig longcarcinoom). Ze kleuren aan met chromogranine en synaptofysine. Sommige maken hormonen; bij levermetastasen van een dunnedarm-NET kan een carcinoïdsyndroom ontstaan (flushing, diarree).</p>","image_url":"","wiki_title":"Neuroendocrine tumor","match":"neuro-endocrien carcinoom|neuro-endocriene tumor|carcinoïd","option_only":true},"slokdarm spasmen":{"title":"Slokdarmspasmen","short":"Bij slokdarmspasmen trekt de slokdarm ongecoördineerd en krachtig samen, met slikklachten en retrosternale pijn.","definition":"<p>Bij <strong>distale oesofagusspasmen</strong> zijn de contracties te vroeg of tegelijk in plaats van in een voortschrijdende golf. Klachten: wisselende slikklachten voor vast én vloeibaar voedsel en kramp-achtige pijn achter het borstbeen, die op angina pectoris kan lijken. Diagnose met slokdarmmanometrie; op een slikfoto kan een ‘kurkentrekker’-beeld te zien zijn.</p>","image_url":"","wiki_title":"Diffuse esophageal spasm","match":"slokdarm spasmen|slokdarmspasmen|oesofagusspasme|distale oesofagusspasmen","option_only":true},"diverticulitis":{"title":"Diverticulitis","short":"Diverticulitis is een ontsteking van een of meer divertikels (uitstulpingen) van de dikke darm.","definition":"<p>Bij <b>diverticulitis</b> raakt een divertikel ontstoken, vermoedelijk door obstructie en microperforatie. Divertikels ontstaan vooral bij ouderen en bij vezelarme voeding. De ernst wordt ingedeeld volgens Hinchey (van lokale ontsteking tot abces en perforatie met peritonitis). Diagnose met echo of CT; ongecompliceerde gevallen worden meestal conservatief behandeld.</p>","image_url":"","wiki_title":"Diverticulitis","match":"diverticulitis","option_only":true},"microscopische hematurie":{"title":"Microscopische hematurie","short":"Bij microscopische hematurie zijn rode bloedcellen alleen met de microscoop of een teststrook in de urine aantoonbaar.","definition":"<p><strong>Hematurie</strong> kan glomerulair zijn (dysmorfe erytrocyten, erytrocytencilinders, vaak met proteïnurie; bijv. IgA-nefropathie) of niet-glomerulair (stenen, infecties, tumoren van nier, ureter of blaas). Bij ouderen en rokers moet bij hematurie een urologische maligniteit worden uitgesloten.</p>","image_url":"","wiki_title":"Hematuria","match":"microscopische hematurie|hematurie","option_only":true},"pancreascarcinoom":{"title":"Pancreascarcinoom","short":"Het pancreascarcinoom is een agressieve tumor, meestal een ductaal adenocarcinoom, met een slechte prognose.","definition":"<p>Het <strong>pancreascarcinoom</strong> zit vaak in de pancreaskop, waar het de galweg afsluit: pijnloze icterus, een palpabele galblaas (teken van Courvoisier), jeuk, ontkleurde ontlasting en donkere urine. Tumoren in corpus en staart worden later ontdekt (rugpijn, gewichtsverlies). Risicofactoren zijn roken, chronische pancreatitis en erfelijke aanleg. Slechts een minderheid is operabel (Whipple).</p>","image_url":"","wiki_title":"Pancreatic cancer","match":"pancreascarcinoom|alvleesklierkanker|pancreaskopcarcinoom","option_only":true},"iga":{"title":"IgA","short":"IgA is de belangrijkste antistof op slijmvliezen en in secreten zoals speeksel, tranen en moedermelk.","definition":"<p><strong>IgA</strong> komt in het bloed als monomeer en op slijmvliezen als dimeer (secretoir IgA), verbonden door een J-keten en beschermd door een secretoire component. Het neutraliseert micro-organismen en toxines zonder ontsteking. Een selectieve IgA-deficiëntie is de meest voorkomende primaire immuundeficiëntie en geeft vaak weinig klachten; bij coeliakie-serologie kan het fout-negatieve uitslagen geven.</p>","image_url":"","wiki_title":"Immunoglobulin A","match":"iga|immunoglobuline a","option_only":true},"alkalische fosfatase":{"title":"Alkalische fosfatase","short":"Alkalische fosfatase is een enzym uit lever (galwegen) en bot; een verhoogde waarde wijst op cholestase of verhoogde botaanmaak.","definition":"<p>Verhoogd <strong>alkalisch fosfatase</strong> uit de lever past bij cholestase (galwegobstructie, PBC, PSC, infiltratie), meestal samen met een verhoogd γGT. Uit het bot komt het bij verhoogde osteoblastactiviteit: groei bij kinderen, fractuurgenezing, ziekte van Paget, botmetastasen en osteomalacie. In de zwangerschap maakt de placenta het ook.</p>","image_url":"","wiki_title":"Alkaline phosphatase","match":"alkalische fosfatase|alkalisch fosfatase|alp","option_only":true},"pancreatitis":{"title":"Pancreatitis","short":"Pancreatitis is een ontsteking van de pancreas, acuut meestal door galstenen of alcohol.","definition":"<p><strong>Acute pancreatitis</strong> geeft hevige, gordelvormige bovenbuikpijn uitstralend naar de rug, met misselijkheid en braken; het lipase is verhoogd. Andere oorzaken zijn hypertriglyceridemie, hypercalciëmie, medicatie en ERCP. Ernstige vormen geven necrose, SIRS en orgaanfalen. Chronische pancreatitis geeft pijn, exocriene en endocriene insufficiëntie.</p>","image_url":"","wiki_title":"Pancreatitis","match":"pancreatitis|alvleesklierontsteking|acute pancreatitis","option_only":true},"melaena":{"title":"Melaena","short":"Melaena is zwarte, teerachtige, stinkende ontlasting door een bloeding hoog in het maag-darmkanaal.","definition":"<p><strong>Melaena</strong> ontstaat als bloed uit slokdarm, maag of duodenum door maagzuur en bacteriën wordt omgezet. Belangrijke oorzaken zijn een ulcus pepticum en varices. Het ureum kan verhoogd zijn door eiwitresorptie. IJzerpreparaten en bismut kleuren de ontlasting ook zwart, maar niet teerachtig.</p>","image_url":"","wiki_title":"Melena","match":"melaena|melena|teerontlasting","option_only":true},"haematemesis":{"title":"Haematemesis","short":"Haematemesis is het braken van bloed, vers rood of als ‘koffiedik’, door een bloeding in slokdarm, maag of duodenum.","definition":"<p>Oorzaken van <strong>haematemesis</strong> zijn o.a. een ulcus pepticum, oesofagusvarices (bij portale hypertensie), een Mallory-Weiss-scheur na heftig braken, oesofagitis en tumoren. Koffiedikbraaksel wijst op bloed dat al met maagzuur in contact is geweest. Beoordeling van de circulatie en een spoedgastroscopie zijn nodig.</p>","image_url":"","wiki_title":"Hematemesis","match":"haematemesis|hematemesis|bloedbraken","option_only":true},"bisacodyl":{"title":"Bisacodyl","short":"Bisacodyl is een prikkelend (contactlaxans) laxeermiddel dat de darmperistaltiek stimuleert.","definition":"<p><strong>Bisacodyl</strong> stimuleert de zenuwen in de darmwand en vermindert de wateropname in het colon. Het werkt na 6–12 uur (oraal) of na 15–60 minuten (zetpil). Het wordt gebruikt bij obstipatie, ook bij opioïdgebruik, en voor darmvoorbereiding. Bijwerkingen zijn buikkrampen en bij langdurig hoog gebruik elektrolytverlies.</p>","image_url":"","wiki_title":"Bisacodyl","match":"bisacodyl|dulcolax","option_only":true},"sigmoïdresectie":{"title":"Sigmoïdresectie","short":"Bij een sigmoïdresectie wordt het colon sigmoideum operatief verwijderd, bijv. bij een tumor of gecompliceerde diverticulitis.","definition":"<p>Na een <strong>sigmoïdresectie</strong> worden de darmuiteinden meestal weer met elkaar verbonden (anastomose). Bij een perforatie met peritonitis wordt soms een tijdelijk stoma aangelegd (Hartmann-procedure). Een gevreesde complicatie is naadlekkage, met abcessen en sepsis.</p>","image_url":"","wiki_title":"Sigmoidectomy","match":"sigmoïdresectie|sigmoidresectie","option_only":true},"echo":{"title":"Echografie","short":"Echografie maakt met hoogfrequente geluidsgolven beelden van weke delen en organen, zonder straling.","definition":"<p>Bij <strong>echografie</strong> zendt een transducer geluidsgolven uit en vangt de echo's op. Vocht is zwart, weefsel grijs; bot en lucht houden het geluid tegen. Het is goedkoop, snel en direct beschikbaar, en geschikt voor o.a. galblaas, nieren, schildklier, zwangerschap, hart (echocardiografie), vaten (duplex) en gewrichten. De kwaliteit hangt af van de onderzoeker en de patiënt.</p>","image_url":"","wiki_title":"Medical ultrasound","match":"echo|echografie|echoscopie|ultrageluid","option_only":true},"ct scan":{"title":"CT-scan","short":"Een CT-scan maakt met röntgenstraling dwarsdoorsneden van het lichaam.","definition":"<p>Bij <strong>computertomografie</strong> draait een röntgenbuis rond de patiënt en wordt een driedimensionaal beeld berekend. CT is snel en zeer geschikt voor trauma, bloedingen in het hoofd, longen, buik en bot; met contrast ook voor vaten. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct scan|ct-scan|computertomografie","option_only":true},"pet/ct":{"title":"PET-CT","short":"Een PET-CT combineert een metabole PET-scan (meestal met radioactief glucose, FDG) met een CT voor de anatomie.","definition":"<p>Bij <strong>FDG-PET</strong> nemen cellen met een hoge glucosestofwisseling, zoals veel tumoren en ontstekingshaarden, meer tracer op. Gecombineerd met CT kan de plaats precies worden bepaald. Het wordt gebruikt voor stadiëring en respons van o.a. lymfomen en longkanker, en bij onverklaarde koorts of vasculitis.</p>","image_url":"","wiki_title":"PET-CT","match":"pet/ct|pet-ct|pet-scan","option_only":true},"ascariasis":{"title":"Ascariasis (spoelworm)","short":"Ascariasis is een infectie met de grote spoelworm Ascaris lumbricoides, opgelopen via eitjes in besmet voedsel of grond.","definition":"<p>Bij <strong>ascariasis</strong> komen larven uit de darm via bloed en longen (soms met hoest en eosinofilie: syndroom van Löffler) terug in de darm, waar ze uitgroeien tot wormen van 15–35 cm. Lichte infecties geven weinig klachten; zware infecties kunnen darmobstructie, galwegobstructie en ondervoeding geven. Behandeling met mebendazol of albendazol.</p>","image_url":"","wiki_title":"Ascariasis","match":"ascariasis|ascaris lumbricoides|spoelworm","option_only":true},"schildklier hormoon":{"title":"Schildklierhormoon (T4 en T3)","short":"Schildklierhormoon (T4 en het actievere T3) regelt het basaal metabolisme, de groei en de ontwikkeling van het zenuwstelsel.","definition":"<p>De schildklier maakt vooral <strong>T4</strong>, dat in de weefsels wordt omgezet in het actievere <strong>T3</strong>. Het hormoon werkt via kernreceptoren en verhoogt o.a. de stofwisseling, warmteproductie en gevoeligheid voor catecholaminen. In de foetale en vroege kinderjaren is het essentieel voor de hersenontwikkeling; daarom wordt congenitale hypothyreoïdie met de hielprik opgespoord.</p>","image_url":"","wiki_title":"Thyroid hormones","match":"schildklier hormoon|schildklierhormoon|thyroxine|t4|t3","option_only":true},"lobaire pneumonie, veroorzaakt door pneumokokken":{"title":"Pneumonie","short":"Een pneumonie is een infectie van het longweefsel (alveoli), meestal door bacteriën of virussen, met koorts, hoesten en kortademigheid.","definition":"<p>Bij een <strong>pneumonie</strong> (longontsteking) raken de alveoli ontstoken en vullen ze zich met ontstekingsvocht en cellen. Daardoor is minder longoppervlak beschikbaar voor gaswisseling.</p><p>Typische klachten zijn koorts, hoesten (vaak met sputum), kortademigheid en soms pijn bij het ademen. Bij lichamelijk onderzoek kunnen crepitaties of een gedempte percussie optreden; een X-thorax toont een infiltraat. De meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie is <em>Streptococcus pneumoniae</em>.</p>","image_url":"","wiki_title":"Pneumonia","match":"lobaire pneumonie, veroorzaakt door pneumokokken","option_only":true},"appendicitis acuta":{"title":"Appendicitis","short":"Appendicitis is een ontsteking van de appendix, met buikpijn die vaak rond de navel begint en naar rechtsonder trekt.","definition":"<p>Bij <strong>appendicitis</strong> raakt het lumen van de appendix afgesloten (bijv. door een fecoliet of lymfoïde hyperplasie), waarna ontsteking en infectie volgen. Klachten: pijn eerst rond de navel, later rechtsonder (McBurney), misselijkheid, koorts en lokale peritoneale prikkeling. Zonder behandeling kan perforatie optreden. Diagnose met echo en/of CT; behandeling meestal appendectomie.</p>","image_url":"","wiki_title":"Appendicitis","match":"appendicitis acuta","option_only":true},"het gesprekskader aangeven":{"title":"Gesprekskader bespreken","short":"Het gesprekskader bespreken betekent aan het begin van een gesprek uitleggen wat het doel, de duur en de opbouw van het gesprek zijn.","definition":"<p>Bij het <strong>bespreken van het gesprekskader</strong> vertelt de arts aan het begin wat de aanleiding en het doel van het gesprek zijn, hoeveel tijd er is, en hoe het gesprek ongeveer verloopt (bijvoorbeeld eerst vragen stellen, dan onderzoek, dan bespreken).</p><p>Het geeft de patiënt duidelijkheid en houvast, en vormt samen met agenderen het startpunt van een gestructureerd consult.</p>","image_url":"","wiki_title":"","match":"het gesprekskader aangeven","option_only":true},"salmonella spp":{"title":"Salmonella","short":"Salmonella zijn gramnegatieve staven die voedselinfecties (gastro-enteritis) en buiktyfus kunnen veroorzaken.","definition":"<p>Niet-tyfeuze <strong>salmonellae</strong> komen via onvoldoende verhit voedsel (kip, eieren) binnen en geven koorts, buikkrampen en diarree. <em>S. typhi</em> en <em>S. paratyphi</em> veroorzaken (para)tyfus, een systemische ziekte met hoge koorts, relatieve bradycardie en roseola. Bij sikkelcelziekte kan Salmonella osteomyelitis veroorzaken.</p>","image_url":"","wiki_title":"Salmonella","match":"salmonella spp|salmonella|salmonellosis","option_only":true},"lactose-intolerantie":{"title":"Lactose-intolerantie","short":"Bij lactose-intolerantie is er te weinig lactase in de dunne darm, waardoor melksuiker in de dikke darm wordt gefermenteerd.","definition":"<p>Bij <strong>lactose-intolerantie</strong> geeft melk een opgeblazen gevoel, winderigheid, buikkrampen en osmotische diarree. De primaire vorm (afnemende lactase na de kindertijd) komt wereldwijd bij de meerderheid van de volwassenen voor; secundaire vormen ontstaan bij darmschade (bijv. coeliakie, gastro-enteritis). Diagnose met een waterstofademtest of eliminatie.</p>","image_url":"","wiki_title":"Lactose intolerance","match":"lactose-intolerantie|lactoseintolerantie|lactasedeficiëntie|lactase deficiëntie","option_only":true},"enterobius":{"title":"Enterobius vermicularis (aarsmade)","short":"Enterobius vermicularis (aarsmade) is een kleine witte worm die vooral bij kinderen ’s nachts jeuk rond de anus geeft.","definition":"<p>Bij <strong>enterobiasis</strong> leggen de vrouwtjes ’s nachts eitjes rond de anus. Door krabben komen de eitjes onder de nagels en weer in de mond (auto-infectie), en worden ook gezinsleden besmet. Diagnose met een plakbandpreparaat ’s ochtends; behandeling met mebendazol voor het hele gezin, plus hygiënemaatregelen.</p>","image_url":"","wiki_title":"Pinworm infection","match":"enterobius|enterobiasis|enterobius vermicularis|aarsmade|aarsmaden","option_only":true},"reflux oesophagitis":{"title":"Gastro-oesofageale reflux","short":"Bij refluxklachten stroomt maaginhoud terug in de slokdarm, met zuurbranden en oprispingen.","definition":"<p><strong>Gastro-oesofageale refluxziekte</strong> ontstaat bij een tekortschietende onderste slokdarmsfincter, een hiatus hernia of verhoogde druk in de buik (overgewicht, zwangerschap). Klachten zijn zuurbranden achter het borstbeen en zure oprispingen, soms hoesten of heesheid. Complicaties: oesofagitis, stenose en Barrett-slokdarm. Behandeling met leefstijladviezen en protonpompremmers.</p>","image_url":"","wiki_title":"Gastroesophageal reflux disease","match":"reflux oesophagitis","option_only":true},"lis-diureticum":{"title":"Lisdiureticum","short":"Lisdiuretica remmen de NKCC2-cotransporter in de lis van Henle en zijn de krachtigste plasmiddelen.","definition":"<p><strong>Lisdiuretica</strong> zoals furosemide remmen de Na⁺/K⁺/2Cl⁻-cotransporter in het dikke opstijgende deel van de lis van Henle. Ze worden gebruikt bij oedeem door hartfalen, nierziekte of levercirrose en bij longoedeem. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, metabole alkalose, uitdroging en ototoxiciteit; anders dan thiaziden verhogen ze de calciumuitscheiding.</p>","image_url":"","wiki_title":"Loop diuretic","match":"lis-diureticum","option_only":true},"een lisdiureticum":{"title":"Lisdiureticum","short":"Lisdiuretica remmen de NKCC2-cotransporter in de lis van Henle en zijn de krachtigste plasmiddelen.","definition":"<p><strong>Lisdiuretica</strong> zoals furosemide remmen de Na⁺/K⁺/2Cl⁻-cotransporter in het dikke opstijgende deel van de lis van Henle. Ze worden gebruikt bij oedeem door hartfalen, nierziekte of levercirrose en bij longoedeem. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, metabole alkalose, uitdroging en ototoxiciteit; anders dan thiaziden verhogen ze de calciumuitscheiding.</p>","image_url":"","wiki_title":"Loop diuretic","match":"een lisdiureticum","option_only":true},"granulomateuze ontsteking":{"title":"Granulomateuze ontsteking","short":"Bij een granulomateuze ontsteking vormen macrofagen (epitheloïde cellen en reuscellen) compacte haarden: granulomen.","definition":"<p><strong>Granulomen</strong> ontstaan bij persisterende antigenen die moeilijk op te ruimen zijn, via een Th1/IFN-γ-gedreven reactie. Voorbeelden: tuberculose (met centrale verkazing), sarcoïdose (niet-verkazend), lepra, schimmels, de ziekte van Crohn, granulomatose met polyangiitis en vreemdlichaamreacties.</p>","image_url":"","wiki_title":"Granulomatous inflammation","match":"granulomateuze ontsteking|granuloom|granulomen","option_only":true},"oesophagusmanometrie":{"title":"Slokdarmmanometrie","short":"Bij slokdarmmanometrie worden drukken in de slokdarm gemeten om motiliteitsstoornissen op te sporen.","definition":"<p>Met <strong>(hoge-resolutie)manometrie</strong> worden de peristaltiek en de ontspanning van de onderste slokdarmsfincter beoordeeld. Het is het belangrijkste onderzoek bij achalasie (geen peristaltiek, onvoldoende sfincterontspanning) en slokdarmspasmen.</p>","image_url":"","wiki_title":"Esophageal motility study","match":"oesophagusmanometrie|slokdarmmanometrie","option_only":true},"ziekte van crohn":{"title":"Ziekte van Crohn","short":"De ziekte van Crohn is een chronische ontstekingsziekte die het hele maag-darmkanaal kan treffen, met transmurale ontsteking en ‘skip lesions’.","definition":"<p>De <strong>ziekte van Crohn</strong> zit vaak in het terminale ileum. Klachten: buikpijn, (niet altijd bloederige) diarree, gewichtsverlies en perianale fistels. Complicaties zijn stenosen, fistels en abcessen. Histologisch zijn er soms niet-verkazende granulomen. Roken verergert de ziekte.</p>","image_url":"","wiki_title":"Crohn's disease","match":"ziekte van crohn|crohn|m. crohn","option_only":true},"leverabces":{"title":"Leverabces","short":"Een leverabces is een met pus gevulde holte in de lever, bacterieel (vaak vanuit galwegen of darm) of door amoeben.","definition":"<p>Een <strong>pyogeen leverabces</strong> ontstaat bij cholangitis, diverticulitis of appendicitis (via de v. portae). Klachten: koorts, pijn rechtsboven en een gevoelige lever. Behandeling met drainage en antibiotica. Bij een reisanamnese moet aan een amoebenabces worden gedacht.</p>","image_url":"","wiki_title":"Liver abscess","match":"leverabces|abces in de lever","option_only":true},"cholangiocarcinoom":{"title":"Cholangiocarcinoom","short":"Het cholangiocarcinoom is een kwaadaardige tumor van de galwegen, vaak met pijnloze icterus.","definition":"<p>Een <strong>cholangiocarcinoom</strong> kan intrahepatisch, perihilair (Klatskin-tumor) of distaal liggen. Risicofactoren zijn primaire scleroserende cholangitis, choledochuscysten en leverbotinfecties. De prognose is slecht, omdat de tumor meestal laat wordt ontdekt.</p>","image_url":"","wiki_title":"Cholangiocarcinoma","match":"cholangiocarcinoom|galwegcarcinoom","option_only":true},"slokdarmcarcinoom":{"title":"Slokdarmcarcinoom","short":"Slokdarmkanker is een plaveiselcel- of adenocarcinoom van de slokdarm, met progressieve slikklachten en gewichtsverlies.","definition":"<p>Het <strong>plaveiselcelcarcinoom</strong> hangt samen met roken en alcohol en zit vaker in het midden van de slokdarm; het <strong>adenocarcinoom</strong> ontstaat uit een Barrett-slokdarm (reflux, obesitas) en zit distaal. Klachten: eerst slikproblemen voor vast voedsel, later ook voor vloeibaar, en gewichtsverlies.</p>","image_url":"","wiki_title":"Esophageal cancer","match":"slokdarmcarcinoom|oesofaguscarcinoom|slokdarmkanker","option_only":true},"laparoscopische cholecystectomie":{"title":"Laparoscopische cholecystectomie","short":"Bij een laparoscopische cholecystectomie wordt de galblaas via een kijkoperatie verwijderd, de standaardbehandeling bij symptomatisch galsteenlijden.","definition":"<p>Een <strong>cholecystectomie</strong> wordt gedaan bij galsteenkolieken, cholecystitis en na een biliaire pancreatitis. Een belangrijke, gevreesde complicatie is letsel van de galweg; de chirurg identificeert daarom eerst de ‘critical view of safety’.</p>","image_url":"","wiki_title":"Cholecystectomy","match":"laparoscopische cholecystectomie|cholecystectomie","option_only":true},"cholelithiasis":{"title":"Cholelithiasis (galstenen)","short":"Cholelithiasis betekent galstenen in de galblaas; veel mensen hebben geen klachten, anderen krijgen koliekpijn of complicaties.","definition":"<p>De meeste <strong>galstenen</strong> zijn cholesterolstenen (risicofactoren: vrouw, overgewicht, snel afvallen, zwangerschap, leeftijd); pigmentstenen ontstaan bij hemolyse. Een galsteenkoliek geeft heftige pijn rechtsboven of in het epigastrium. Complicaties zijn cholecystitis, choledocholithiasis, cholangitis en pancreatitis.</p>","image_url":"","wiki_title":"Gallstone","match":"cholelithiasis|galstenen|galsteenlijden","option_only":true},"amylase":{"title":"Amylase","short":"Amylase is een enzym uit speekselklieren en pancreas dat zetmeel afbreekt; een verhoogde bloedwaarde past o.a. bij pancreatitis.","definition":"<p><strong>Amylase</strong> splitst α-1,4-bindingen in zetmeel. Bij acute pancreatitis stijgt het, maar het is minder specifiek dan lipase (ook verhoogd bij o.a. parotitis, darmperforatie en nierfalen) en normaliseert sneller.</p>","image_url":"","wiki_title":"Amylase","match":"amylase|alfa-amylase","option_only":true},"lipase":{"title":"Lipase","short":"Lipase is een pancreasenzym dat triglyceriden afbreekt; een sterk verhoogd serumlipase past bij acute pancreatitis.","definition":"<p><strong>Pancreaslipase</strong> splitst vetten in vrije vetzuren en monoglyceriden, met galzouten en colipase als hulp. In het bloed is een stijging van meer dan drie keer de bovengrens, bij passende pijn, een criterium voor acute pancreatitis. Lipaseremmers (orlistat) verminderen vetopname.</p>","image_url":"","wiki_title":"Lipase","match":"lipase|pancreaslipase","option_only":true},"gamma-gt":{"title":"γ-GT","short":"γ-GT is een leverenzym dat stijgt bij cholestase en door alcoholgebruik en sommige geneesmiddelen.","definition":"<p><strong>γ-glutamyltransferase</strong> is gevoelig maar niet specifiek. Samen met een verhoogd alkalisch fosfatase bevestigt het een leveroorsprong (cholestase). Een geïsoleerd verhoogd γ-GT past vaak bij alcoholgebruik of enzyminducerende middelen.</p>","image_url":"","wiki_title":"Gamma-glutamyltransferase","match":"gamma-gt|ggt|γ-gt","option_only":true},"serosa":{"title":"Serosa","short":"De serosa is de buitenste laag van intraperitoneaal gelegen organen: mesotheel met een dun laagje bindweefsel.","definition":"<p>Organen die in de buikholte liggen, zoals maag, dunne darm en colon transversum, zijn bekleed met <strong>serosa</strong> (viscerale peritoneum). Retroperitoneale delen en de slokdarm hebben in plaats daarvan een adventitia van los bindweefsel.</p>","image_url":"","wiki_title":"Serous membrane","match":"serosa|tunica serosa","option_only":true},"neo-adjuvant":{"title":"Neoadjuvante behandeling","short":"Een neoadjuvante behandeling wordt vóór de operatie gegeven om een tumor te verkleinen en micrometastasen te behandelen.","definition":"<p><strong>Neoadjuvante</strong> chemotherapie of (chemo)radiatie wordt o.a. gebruikt bij slokdarm-, rectum- en borstkanker. Het kan een operatie mogelijk of kleiner maken en laat zien hoe de tumor op behandeling reageert. Adjuvante therapie wordt juist na de operatie gegeven.</p>","image_url":"","wiki_title":"Neoadjuvant therapy","match":"neo-adjuvant|neoadjuvant|neoadjuvante therapie","option_only":true},"gastric bypass":{"title":"Gastric bypass","short":"Een gastric bypass is een bariatrische operatie waarbij een klein maagzakje direct op de dunne darm wordt aangesloten.","definition":"<p>Bij een <strong>Roux-en-Y gastric bypass</strong> wordt het grootste deel van de maag en het duodenum omzeild. Het leidt tot fors gewichtsverlies en verbetering van diabetes type 2. Gevolgen kunnen zijn: tekorten aan ijzer, vitamine B12, calcium en vitamine D, dumpingklachten en interne herniaties.</p>","image_url":"","wiki_title":"Gastric bypass surgery","match":"gastric bypass|maagbypass|roux-en-y gastric bypass","option_only":true},"sigmoidoscopie":{"title":"Sigmoïdoscopie","short":"Bij een sigmoïdoscopie worden het rectum en het sigmoïd met een flexibele scoop bekeken.","definition":"<p>Een <strong>sigmoïdoscopie</strong> vraagt een beperkte voorbereiding (klysma) en wordt gebruikt bij rectaal bloedverlies bij jongere patiënten, verdenking op proctitis of voor het beoordelen van het distale colon. Voor het hele colon is een coloscopie nodig.</p>","image_url":"","wiki_title":"Sigmoidoscopy","match":"sigmoidoscopie|sigmoïdoscopie","option_only":true},"beenvarices":{"title":"Varices (spataderen)","short":"Varices zijn verwijde, kronkelige oppervlakkige venen in de benen, door lekkende kleppen.","definition":"<p><strong>Spataderen</strong> komen veel voor, vaker bij vrouwen, met familiaire aanleg, zwangerschap, overgewicht en staand werk als risicofactoren. Klachten: zware, moeë benen, jeuk en oedeem; complicaties zijn tromboflebitis, bloedingen, huidveranderingen en een ulcus cruris. Behandeling: compressie, sclerotherapie, endoveneuze ablatie.</p>","image_url":"","wiki_title":"Varicose veins","match":"beenvarices|varices|spataderen","option_only":true},"pleuravocht":{"title":"Pleuravocht","short":"Pleuravocht is vochtophoping tussen de longvliezen, met kortademigheid en een gedempte percussie.","definition":"<p><strong>Pleuravocht</strong> wordt met de criteria van Light ingedeeld in transsudaat (bijv. hartfalen, cirrose, nefrotisch syndroom) en exsudaat (bijv. pneumonie, maligniteit, tuberculose, longembolie). Een diagnostische punctie helpt de oorzaak vinden; grote hoeveelheden worden gedraineerd.</p>","image_url":"","wiki_title":"Pleural effusion","match":"pleuravocht|pleura-effusie|hydrothorax","option_only":true},"wondinfectie":{"title":"Wondinfectie","short":"Een wondinfectie is een infectie van een (operatie)wond, met roodheid, warmte, pijn, zwelling en eventueel pus.","definition":"<p>Postoperatieve <strong>wondinfecties</strong> worden vaak veroorzaakt door <em>S. aureus</em> of, bij darmchirurgie, door darmbacteriën. Risicofactoren zijn diabetes, obesitas, roken, lange operaties en contaminatie. Behandeling: openen en draineren, eventueel antibiotica.</p>","image_url":"","wiki_title":"Surgical site infection","match":"wondinfectie|postoperatieve wondinfectie","option_only":true},"igd":{"title":"IgD","short":"IgD komt vooral als membraanreceptor voor op naïeve B-cellen, samen met IgM.","definition":"<p>De functie van <strong>IgD</strong> is nog niet helemaal duidelijk; het speelt een rol bij de activatie van B-cellen. Vrij IgD in het bloed is laag.</p>","image_url":"","wiki_title":"Immunoglobulin D","match":"igd|immunoglobuline d","option_only":true},"a. umbilicalis":{"title":"A. umbilicalis (navelarterie)","short":"De aa. umbilicales voeren zuurstofarm bloed van de foetus via de navelstreng naar de placenta.","definition":"<p>Normaal heeft de navelstreng twee <strong>navelarteriën</strong> en één navelvene. Ze ontspringen uit de aa. iliacae internae. Na de geboorte sluiten ze en worden ze (deels) de mediale umbilicale plooien; een proximaal deel blijft als a. vesicalis superior bestaan. Een navelstreng met één arterie is geassocieerd met aangeboren afwijkingen.</p>","image_url":"","wiki_title":"Umbilical artery","match":"a. umbilicalis|arteria umbilicalis|navelarterie|navelarteriën","option_only":true},"ischaemie":{"title":"Ischemie","short":"Ischemie is een tekort aan doorbloeding van een weefsel, waardoor te weinig zuurstof en voedingsstoffen aankomen.","definition":"<p><strong>Ischemie</strong> ontstaat door vernauwing of afsluiting van een vat (atherosclerose, trombose, embolie), door een te lage bloeddruk of door een verhoogde vraag. Langdurige ischemie leidt tot een infarct (necrose). Weefsels verschillen in hoe lang ze ischemie verdragen: het brein minuten, skeletspier uren.</p>","image_url":"","wiki_title":"Ischemia","match":"ischaemie|ischemie","option_only":true},"chronische hepatitis b":{"title":"Chronische hepatitis B","short":"Bij chronische hepatitis B is het HBsAg langer dan zes maanden aanwezig; er is een risico op cirrose en leverkanker.","definition":"<p>Het beloop van <strong>chronische hepatitis B</strong> verloopt in fasen (o.a. HBeAg-positief en -negatief) met wisselende virusactiviteit en leverontsteking. Behandeling met antivirale middelen (entecavir, tenofovir) bij actieve ziekte. Bij cirrose en bij bepaalde groepen wordt gescreend op hepatocellulair carcinoom.</p>","image_url":"","wiki_title":"Hepatitis B","match":"chronische hepatitis b","option_only":true},"toxische hepatitis":{"title":"Toxische (geneesmiddelgeïnduceerde) hepatitis","short":"Toxische hepatitis is leverschade door geneesmiddelen, kruiden, alcohol of andere giftige stoffen.","definition":"<p>Bekende oorzaken zijn paracetamol (dosisafhankelijk), amoxicilline-clavulaanzuur, isoniazide, methotrexaat, statines en kruidenpreparaten. Het patroon kan hepatocellulair of cholestatisch zijn. Het middel stoppen is de belangrijkste maatregel.</p>","image_url":"","wiki_title":"Drug-induced liver injury","match":"toxische hepatitis|geneesmiddelgeïnduceerde leverschade|dili","option_only":true},"acuut leverfalen":{"title":"Acuut leverfalen","short":"Bij acuut leverfalen schiet de leverfunctie binnen enkele weken ernstig tekort, met stollingsstoornis en encefalopathie, zonder eerdere leverziekte.","definition":"<p>Oorzaken van <strong>acuut leverfalen</strong> zijn o.a. paracetamolintoxicatie, virale hepatitis (A, B, E), geneesmiddelen, auto-immuunhepatitis, de ziekte van Wilson en zwangerschapsgerelateerde ziekten. Kenmerken: icterus, een verlengde INR en hepatische encefalopathie. Snelle verwijzing naar een transplantatiecentrum is nodig.</p>","image_url":"","wiki_title":"Acute liver failure","match":"acuut leverfalen|fulminant leverfalen|leverfalen","option_only":true},"leveradenoom":{"title":"Hepatocellulair adenoom","short":"Een leveradenoom is een goedaardige levertumor, vooral bij vrouwen die de pil gebruiken.","definition":"<p>Een <strong>hepatocellulair adenoom</strong> hangt samen met oestrogenen (orale anticonceptie), anabole steroïden en obesitas. Grote adenomen (&gt;5 cm) kunnen bloeden en zelden maligne ontaarden. Stoppen met de pil en afvallen kunnen het verkleinen.</p>","image_url":"","wiki_title":"Hepatocellular adenoma","match":"leveradenoom|hepatocellulair adenoom","option_only":true},"lever metastasen":{"title":"Levermetastasen","short":"Levermetastasen zijn uitzaaiingen in de lever, vaak van tumoren uit het maag-darmkanaal via de v. portae.","definition":"<p>De lever is een veelvoorkomende plaats voor <strong>metastasen</strong>, vooral van colorectaal, pancreas-, maag-, borst- en longcarcinoom en melanoom. Bij beperkte levermetastasen van een colorectaal carcinoom kan resectie of ablatie nog curatief zijn.</p>","image_url":"","wiki_title":"Liver metastasis","match":"lever metastasen|levermetastasen|hepatogene metastasen","option_only":true},"lymfoom":{"title":"Lymfoom","short":"Een lymfoom is een kwaadaardige ziekte van lymfocyten, meestal uitgaand van lymfeklieren.","definition":"<p><strong>Lymfomen</strong> worden ingedeeld in Hodgkinlymfomen en non-Hodgkinlymfomen (B-, T- of NK-cel). Klachten zijn pijnloze lymfeklierzwelling, B-symptomen (koorts, nachtzweten, gewichtsverlies), jeuk en klachten door orgaaninfiltratie. Diagnose met een klierbiopt.</p>","image_url":"","wiki_title":"Lymphoma","match":"lymfoom|lymfomen","option_only":true},"methotrexaat (een immunosuppressivum)":{"title":"Methotrexaat","short":"Methotrexaat is een foliumzuurantagonist; in lage dosis een basismiddel bij reumatoïde artritis en psoriasis, in hoge dosis een cytostaticum.","definition":"<p><strong>Methotrexaat</strong> remt dihydrofolaatreductase. In lage, wekelijkse dosering werkt het ontstekingsremmend (o.a. via adenosine) en is het een hoeksteen bij reumatoïde artritis, psoriasis en IBD; foliumzuur vermindert bijwerkingen. Bijwerkingen: beenmergsuppressie, levertoxiciteit, mucositis en pneumonitis. Het is teratogeen en wordt via de nier uitgescheiden.</p>","image_url":"","wiki_title":"Methotrexate","match":"methotrexaat (een immunosuppressivum)","option_only":true},"pet scan":{"title":"PET-CT","short":"Een PET-CT combineert een metabole PET-scan (meestal met radioactief glucose, FDG) met een CT voor de anatomie.","definition":"<p>Bij <strong>FDG-PET</strong> nemen cellen met een hoge glucosestofwisseling, zoals veel tumoren en ontstekingshaarden, meer tracer op. Gecombineerd met CT kan de plaats precies worden bepaald. Het wordt gebruikt voor stadiëring en respons van o.a. lymfomen en longkanker, en bij onverklaarde koorts of vasculitis.</p>","image_url":"","wiki_title":"PET-CT","match":"pet scan","option_only":true},"pet-ct scan":{"title":"PET-CT","short":"Een PET-CT combineert een metabole PET-scan (meestal met radioactief glucose, FDG) met een CT voor de anatomie.","definition":"<p>Bij <strong>FDG-PET</strong> nemen cellen met een hoge glucosestofwisseling, zoals veel tumoren en ontstekingshaarden, meer tracer op. Gecombineerd met CT kan de plaats precies worden bepaald. Het wordt gebruikt voor stadiëring en respons van o.a. lymfomen en longkanker, en bij onverklaarde koorts of vasculitis.</p>","image_url":"","wiki_title":"PET-CT","match":"pet-ct scan","option_only":true},"pet/ct body":{"title":"PET-CT","short":"Een PET-CT combineert een metabole PET-scan (meestal met radioactief glucose, FDG) met een CT voor de anatomie.","definition":"<p>Bij <strong>FDG-PET</strong> nemen cellen met een hoge glucosestofwisseling, zoals veel tumoren en ontstekingshaarden, meer tracer op. Gecombineerd met CT kan de plaats precies worden bepaald. Het wordt gebruikt voor stadiëring en respons van o.a. lymfomen en longkanker, en bij onverklaarde koorts of vasculitis.</p>","image_url":"","wiki_title":"PET-CT","match":"pet/ct body","option_only":true},"pet/ct abdomen":{"title":"PET-CT","short":"Een PET-CT combineert een metabole PET-scan (meestal met radioactief glucose, FDG) met een CT voor de anatomie.","definition":"<p>Bij <strong>FDG-PET</strong> nemen cellen met een hoge glucosestofwisseling, zoals veel tumoren en ontstekingshaarden, meer tracer op. Gecombineerd met CT kan de plaats precies worden bepaald. Het wordt gebruikt voor stadiëring en respons van o.a. lymfomen en longkanker, en bij onverklaarde koorts of vasculitis.</p>","image_url":"","wiki_title":"PET-CT","match":"pet/ct abdomen","option_only":true},"mri-bovenbuik":{"title":"MRI-abdomen","short":"Een MRI van de buik maakt met een magneetveld gedetailleerde beelden van de buikorganen, zonder röntgenstraling.","definition":"<p>Een <strong>MRI-abdomen</strong> is vooral geschikt voor het karakteriseren van lever- en pancreaslaesies, het afbeelden van de galwegen (MRCP), de dunne darm bij de ziekte van Crohn en het rectum bij stadiëring van rectumcarcinoom. Het duurt langer dan een CT en is gevoeliger voor beweging; metalen implantaten kunnen een contra-indicatie zijn.</p>","image_url":"","wiki_title":"Magnetic resonance imaging","match":"mri-bovenbuik","option_only":true},"mri lever":{"title":"MRI-abdomen","short":"Een MRI van de buik maakt met een magneetveld gedetailleerde beelden van de buikorganen, zonder röntgenstraling.","definition":"<p>Een <strong>MRI-abdomen</strong> is vooral geschikt voor het karakteriseren van lever- en pancreaslaesies, het afbeelden van de galwegen (MRCP), de dunne darm bij de ziekte van Crohn en het rectum bij stadiëring van rectumcarcinoom. Het duurt langer dan een CT en is gevoeliger voor beweging; metalen implantaten kunnen een contra-indicatie zijn.</p>","image_url":"","wiki_title":"Magnetic resonance imaging","match":"mri lever","option_only":true},"ct thorax-abdomen":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct thorax-abdomen","option_only":true},"ct-abdomen met oraal contrast":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct-abdomen met oraal contrast","option_only":true},"echo van de lever":{"title":"Echo abdomen","short":"Een echo abdomen is een echografisch onderzoek van de buikorganen; zonder straling en goed voor galblaas, galwegen, lever, nieren en vrij vocht.","definition":"<p>Bij een <strong>echo abdomen</strong> wordt met geluidsgolven een beeld gemaakt van de buikorganen. Het onderzoek gebruikt geen ioniserende straling, is goedkoop en direct beschikbaar.</p><p>Het is bijzonder geschikt voor het aantonen van galstenen en cholecystitis, verwijde galwegen, leverafwijkingen, nierstuwing (hydronefrose), een abdominaal aorta-aneurysma en vrij vocht. Darmgas en een dikke buikwand beperken het zicht; de kwaliteit hangt af van de onderzoeker.</p>","image_url":"","wiki_title":"Abdominal ultrasonography","match":"echo van de lever","option_only":true},"diverticultis":{"title":"Diverticulitis","short":"Diverticulitis is een ontsteking van een of meer divertikels (uitstulpingen) van de dikke darm.","definition":"<p>Bij <b>diverticulitis</b> raakt een divertikel ontstoken, vermoedelijk door obstructie en microperforatie. Divertikels ontstaan vooral bij ouderen en bij vezelarme voeding. De ernst wordt ingedeeld volgens Hinchey (van lokale ontsteking tot abces en perforatie met peritonitis). Diagnose met echo of CT; ongecompliceerde gevallen worden meestal conservatief behandeld.</p>","image_url":"","wiki_title":"Diverticulitis","match":"diverticultis","option_only":true},"slokdarmspasme":{"title":"Slokdarmspasmen","short":"Bij slokdarmspasmen trekt de slokdarm ongecoördineerd en krachtig samen, met slikklachten en retrosternale pijn.","definition":"<p>Bij <strong>distale oesofagusspasmen</strong> zijn de contracties te vroeg of tegelijk in plaats van in een voortschrijdende golf. Klachten: wisselende slikklachten voor vast én vloeibaar voedsel en kramp-achtige pijn achter het borstbeen, die op angina pectoris kan lijken. Diagnose met slokdarmmanometrie; op een slikfoto kan een ‘kurkentrekker’-beeld te zien zijn.</p>","image_url":"","wiki_title":"Diffuse esophageal spasm","match":"slokdarmspasme","option_only":true},"slokdarmmanometrie":{"title":"Slokdarmmanometrie","short":"Bij slokdarmmanometrie worden drukken in de slokdarm gemeten om motiliteitsstoornissen op te sporen.","definition":"<p>Met <strong>(hoge-resolutie)manometrie</strong> worden de peristaltiek en de ontspanning van de onderste slokdarmsfincter beoordeeld. Het is het belangrijkste onderzoek bij achalasie (geen peristaltiek, onvoldoende sfincterontspanning) en slokdarmspasmen.</p>","image_url":"","wiki_title":"Esophageal motility study","match":"slokdarmmanometrie","option_only":true},"m. crohn":{"title":"Ziekte van Crohn","short":"De ziekte van Crohn is een chronische ontstekingsziekte die het hele maag-darmkanaal kan treffen, met transmurale ontsteking en ‘skip lesions’.","definition":"<p>De <strong>ziekte van Crohn</strong> zit vaak in het terminale ileum. Klachten: buikpijn, (niet altijd bloederige) diarree, gewichtsverlies en perianale fistels. Complicaties zijn stenosen, fistels en abcessen. Histologisch zijn er soms niet-verkazende granulomen. Roken verergert de ziekte.</p>","image_url":"","wiki_title":"Crohn's disease","match":"m. crohn","option_only":true},"a. mesenterica superior":{"title":"A. mesenterica superior","short":"De a. mesenterica superior voorziet de dunne darm en het proximale colon van bloed.","definition":"<p>De <strong>a. mesenterica superior</strong> ontspringt ter hoogte van L1 uit de aorta, achter de pancreas, en loopt vóór het duodenum. Takken: aa. jejunales en ileales, a. ileocolica, a. colica dextra en media. Een acute afsluiting (embolie) geeft mesenteriale ischemie met hevige buikpijn bij weinig afwijkingen aan de buik.</p>","image_url":"","wiki_title":"Superior mesenteric artery","match":"a. mesenterica superior|arteria mesenterica superior","option_only":true},"hepatocellulair carcinoom":{"title":"Hepatocellulair carcinoom (HCC)","short":"Het hepatocellulair carcinoom is primaire leverkanker uitgaand van hepatocyten, meestal in een cirrotische lever.","definition":"<p><strong>HCC</strong> ontstaat vooral bij cirrose door alcohol, NASH of chronische hepatitis B en C (bij hepatitis B ook zonder cirrose). Patiënten met cirrose worden halfjaarlijks gescreend met echo, eventueel met AFP. Behandeling hangt af van tumorgrootte en leverfunctie: resectie, ablatie, transplantatie of systemische therapie.</p>","image_url":"","wiki_title":"Hepatocellular carcinoma","match":"hepatocellulair carcinoom|hcc|levercelcarcinoom","option_only":true},"elastase":{"title":"Elastase","short":"Elastase is een eiwitsplitsend enzym (o.a. uit neutrofielen en pancreas) dat elastine en andere matrixeiwitten afbreekt.","definition":"<p><strong>Neutrofielenelastase</strong> helpt bij het doden van bacteriën en het opruimen van weefsel, maar kan bij overmaat longweefsel beschadigen. α1-antitrypsine remt het; een tekort daaraan geeft emfyseem. Fecaal elastase wordt gemeten om de exocriene pancreasfunctie te beoordelen.</p>","image_url":"","wiki_title":"Elastase","match":"elastase|elastases|neutrofielenelastase","option_only":true},"chronische atrofische gastritis":{"title":"Chronische atrofische gastritis","short":"Bij atrofische gastritis verdwijnen de maagklieren door chronische ontsteking, auto-immuun of door H. pylori.","definition":"<p>Bij de <strong>auto-immuunvorm</strong> (corpus) ontstaan antistoffen tegen pariëtale cellen en intrinsieke factor, met achloorhydrie, vitamine B12-tekort (pernicieuze anemie) en hypergastrinemie. Bij de H. pylori-vorm (antrum, later uitbreidend) is er een verhoogd risico op intestinale metaplasie en maagcarcinoom.</p>","image_url":"","wiki_title":"Atrophic gastritis","match":"chronische atrofische gastritis|atrofische gastritis|auto-immuun gastritis","option_only":true},"barium slikfoto":{"title":"Slikfoto (bariumslik)","short":"Bij een slikfoto drinkt de patiënt contrastvloeistof terwijl röntgenopnamen worden gemaakt van slokdarm en maag.","definition":"<p>Een <strong>bariumslikfoto</strong> laat de vorm en passage van de slokdarm zien, bijvoorbeeld bij achalasie (vogelbekvorm), vernauwingen, een divertikel van Zenker of slokdarmspasmen (kurkentrekker). Bij verdenking op een perforatie wordt een wateroplosbaar contrast gebruikt.</p>","image_url":"","wiki_title":"Upper gastrointestinal series","match":"barium slikfoto|slikfoto|x-oesophagus","option_only":true},"pseudomyxoma peritonei":{"title":"Pseudomyxoma peritonei","short":"Bij pseudomyxoma peritonei hoopt slijm zich op in de buikholte, meestal door een slijmvormende tumor van de appendix.","definition":"<p><strong>Pseudomyxoma peritonei</strong> geeft een toenemende buikomvang (‘jelly belly’). Behandeling bestaat uit uitgebreide cytoreductieve chirurgie gecombineerd met verwarmde intraperitoneale chemotherapie (HIPEC).</p>","image_url":"","wiki_title":"Pseudomyxoma peritonei","match":"pseudomyxoma peritonei","option_only":true},"mesenteriaal ischemie":{"title":"Mesenteriale ischemie","short":"Bij mesenteriale ischemie krijgt de darm te weinig bloed, door embolie, trombose of lage doorbloeding.","definition":"<p><strong>Acute mesenteriale ischemie</strong> geeft hevige buikpijn die niet past bij de geringe afwijkingen bij onderzoek, vaak bij ouderen met boezemfibrilleren of atherosclerose; het lactaat kan verhoogd zijn. Diagnose met CT-angiografie. <strong>Chronische</strong> mesenteriale ischemie geeft pijn na de maaltijd en gewichtsverlies (‘angina abdominalis’).</p>","image_url":"","wiki_title":"Mesenteric ischemia","match":"mesenteriaal ischemie|mesenteriale ischemie|darmischemie","option_only":true},"lymfadenitis mesenterica":{"title":"Lymfadenitis mesenterica","short":"Lymfadenitis mesenterica is een ontsteking van de lymfeklieren in het mesenterium, vaak bij kinderen na een virale infectie, met pijn rechtsonder.","definition":"<p><strong>Mesenteriale lymfadenitis</strong> kan appendicitis nabootsen. Oorzaken zijn virale infecties en <em>Yersinia</em>. Op de echo zijn vergrote klieren met een normale appendix te zien. Het verloopt meestal vanzelf goed.</p>","image_url":"","wiki_title":"Mesenteric lymphadenitis","match":"lymfadenitis mesenterica|mesenteriale lymfadenitis","option_only":true},"cmv colitis":{"title":"CMV-colitis","short":"CMV-colitis is een ontsteking van het colon door het cytomegalovirus, vooral bij afweergestoorde patiënten of bij ernstige colitis ulcerosa.","definition":"<p>Bij <strong>CMV-colitis</strong> zijn er diarree, bloedverlies, buikpijn en koorts. Biopten tonen virale inclusies. Bij een steroïdrefractaire colitis ulcerosa moet hieraan worden gedacht. Behandeling met ganciclovir.</p>","image_url":"","wiki_title":"Cytomegalovirus","match":"cmv colitis|cmv-colitis","option_only":true},"taenia":{"title":"Taenia (lintworm)","short":"Taenia-soorten zijn lintwormen die via onvoldoende verhit rund- of varkensvlees worden opgelopen.","definition":"<p>Een <strong>lintworm</strong> in de darm geeft meestal weinig klachten; soms ziet men proglottiden in de ontlasting. Bij <em>T. solium</em> (varken) kunnen eitjes (fecaal-oraal) cysticercose veroorzaken, met cysten in o.a. het brein (neurocysticercose, epilepsie). Behandeling met praziquantel.</p>","image_url":"","wiki_title":"Taeniasis","match":"taenia|lintworm|taenia solium|taenia saginata","option_only":true},"mediastinitis":{"title":"Mediastinitis","short":"Mediastinitis is een ernstige infectie van het mediastinum, bijvoorbeeld na een slokdarmperforatie of hartoperatie.","definition":"<p>Acute <strong>mediastinitis</strong> ontstaat o.a. na een slokdarmperforatie (bijv. syndroom van Boerhaave na heftig braken), sternotomie of uitbreiding van een diepe halsinfectie. Klachten: koorts, pijn op de borst en sepsis. Behandeling met drainage, chirurgie en breedspectrum-antibiotica.</p>","image_url":"","wiki_title":"Mediastinitis","match":"mediastinitis","option_only":true},"papilla duodeni minor":{"title":"Papilla duodeni minor","short":"De papilla duodeni minor is de kleine uitmonding in het duodenum van de ductus pancreaticus accessorius (Santorini).","definition":"<p>De <strong>papilla minor</strong> ligt iets boven en vóór de papil van Vater. Bij pancreas divisum (onvolledige versmelting van de ventrale en dorsale pancreasaanleg) loopt het meeste pancreassap via deze kleine papil, wat recidiverende pancreatitis kan geven.</p>","image_url":"","wiki_title":"Minor duodenal papilla","match":"papilla duodeni minor","option_only":true},"foveolair epitheel":{"title":"Foveolair epitheel van de maag","short":"Het foveolaire epitheel is het oppervlakte-epitheel van de maag, met cellen die een beschermende slijm- en bicarbonaatlaag maken.","definition":"<p>De maagwand is bekleed met enkellaags cilindrisch epitheel dat in putjes (foveolae) overgaat in de maagklieren. Deze <strong>slijmcellen</strong> beschermen tegen maagzuur en pepsine; prostaglandinen stimuleren hun werking, wat verklaart waarom NSAID's ulcera kunnen geven.</p>","image_url":"","wiki_title":"","match":"foveolair epitheel","option_only":true},"aambeien":{"title":"Aambeien (hemorroïden)","short":"Aambeien zijn verwijde vaatkussentjes in het anaalkanaal die kunnen bloeden, uitzakken of jeuken.","definition":"<p>Bij <strong>inwendige hemorroïden</strong> (boven de linea dentata) is helderrood bloed op de ontlasting de belangrijkste klacht, meestal zonder pijn. Uitwendige aambeien kunnen trombose geven met hevige pijn. Risicofactoren: obstipatie, persen, zwangerschap. Bij rectaal bloedverlies boven ongeveer 50 jaar moet een coloncarcinoom worden uitgesloten.</p>","image_url":"","wiki_title":"Hemorrhoid","match":"aambeien|hemorroïden|haemorrhoïden","option_only":true},"adenomateuze poliepen":{"title":"Adenomateuze poliepen","short":"Adenomateuze poliepen zijn goedaardige gezwellen van het darmslijmvlies die kunnen uitgroeien tot coloncarcinoom.","definition":"<p>De kans op ontaarding van een <strong>adenoom</strong> neemt toe met de grootte, een villeuze bouw en de mate van dysplasie. Bij coloscopie worden ze verwijderd, met daarna surveillance. Familiaire adenomateuze polyposis (FAP) geeft honderden tot duizenden adenomen en vrijwel zeker kanker zonder colectomie.</p>","image_url":"","wiki_title":"Colorectal polyp","match":"adenomateuze poliepen|adenoom van de darm|darmpoliep","option_only":true},"arteria mesenterica superior":{"title":"A. mesenterica superior","short":"De a. mesenterica superior voorziet de dunne darm en het proximale colon van bloed.","definition":"<p>De <strong>a. mesenterica superior</strong> ontspringt ter hoogte van L1 uit de aorta, achter de pancreas, en loopt vóór het duodenum. Takken: aa. jejunales en ileales, a. ileocolica, a. colica dextra en media. Een acute afsluiting (embolie) geeft mesenteriale ischemie met hevige buikpijn bij weinig afwijkingen aan de buik.</p>","image_url":"","wiki_title":"Superior mesenteric artery","match":"arteria mesenterica superior","option_only":true},"hcc, hepatocellulair carcinoom":{"title":"Hepatocellulair carcinoom (HCC)","short":"Het hepatocellulair carcinoom is primaire leverkanker uitgaand van hepatocyten, meestal in een cirrotische lever.","definition":"<p><strong>HCC</strong> ontstaat vooral bij cirrose door alcohol, NASH of chronische hepatitis B en C (bij hepatitis B ook zonder cirrose). Patiënten met cirrose worden halfjaarlijks gescreend met echo, eventueel met AFP. Behandeling hangt af van tumorgrootte en leverfunctie: resectie, ablatie, transplantatie of systemische therapie.</p>","image_url":"","wiki_title":"Hepatocellular carcinoma","match":"hcc, hepatocellulair carcinoom","option_only":true},"elastases":{"title":"Elastase","short":"Elastase is een eiwitsplitsend enzym (o.a. uit neutrofielen en pancreas) dat elastine en andere matrixeiwitten afbreekt.","definition":"<p><strong>Neutrofielenelastase</strong> helpt bij het doden van bacteriën en het opruimen van weefsel, maar kan bij overmaat longweefsel beschadigen. α1-antitrypsine remt het; een tekort daaraan geeft emfyseem. Fecaal elastase wordt gemeten om de exocriene pancreasfunctie te beoordelen.</p>","image_url":"","wiki_title":"Elastase","match":"elastases","option_only":true},"malabsorptie":{"title":"Malabsorptie","short":"Bij malabsorptie worden voedingsstoffen onvoldoende uit de darm opgenomen, met diarree, gewichtsverlies en tekorten.","definition":"<p>Oorzaken van <strong>malabsorptie</strong> zijn o.a. coeliakie, exocriene pancreasinsufficiëntie, galzuurtekort (cholestase, ileumresectie), de ziekte van Crohn, bacteriële overgroei en lactasedeficiëntie. Vetmalabsorptie geeft steatorroe en tekorten aan de vetoplosbare vitamines A, D, E en K.</p>","image_url":"","wiki_title":"Malabsorption","match":"malabsorptie|malabsorptiesyndroom","option_only":true},"hemicolectomie links":{"title":"Hemicolectomie","short":"Bij een hemicolectomie wordt de linker- of rechterhelft van de dikke darm verwijderd, meestal wegens een tumor.","definition":"<p>Bij een <strong>rechter hemicolectomie</strong> worden het terminale ileum, caecum, colon ascendens en een deel van het transversum verwijderd; bij een <strong>linker</strong> het colon descendens en soms het sigmoïd. Met de darm wordt het bijbehorende mesenterium met lymfeklieren weggenomen voor stadiëring.</p>","image_url":"","wiki_title":"Colectomy","match":"hemicolectomie links|hemicolectomie|hemicolectomie rechts","option_only":true},"oesofagusspasmen":{"title":"Slokdarmspasmen","short":"Bij slokdarmspasmen trekt de slokdarm ongecoördineerd en krachtig samen, met slikklachten en retrosternale pijn.","definition":"<p>Bij <strong>distale oesofagusspasmen</strong> zijn de contracties te vroeg of tegelijk in plaats van in een voortschrijdende golf. Klachten: wisselende slikklachten voor vast én vloeibaar voedsel en kramp-achtige pijn achter het borstbeen, die op angina pectoris kan lijken. Diagnose met slokdarmmanometrie; op een slikfoto kan een ‘kurkentrekker’-beeld te zien zijn.</p>","image_url":"","wiki_title":"Diffuse esophageal spasm","match":"oesofagusspasmen","option_only":true},"conventionele x-thorax":{"title":"X-thorax","short":"Een X-thorax is een röntgenfoto van de borstkas; het eerste beeldvormend onderzoek bij verdenking op longafwijkingen, hartfalen of pneumothorax.","definition":"<p>Een <strong>X-thorax</strong> is een röntgenopname van de borstkas, meestal posterieur-anterieur en lateraal. Lucht is zwart, weke delen grijs en bot wit.</p><p>Het is snel, goedkoop en met een lage stralingsdosis, en wordt gebruikt om o.a. pneumonie (infiltraat), pleuravocht, pneumothorax, longtumoren, hartvergroting en tekenen van hartfalen op te sporen. Kleine of subtiele afwijkingen zijn er minder goed op te zien dan op een CT.</p>","image_url":"","wiki_title":"Chest radiograph","match":"conventionele x-thorax","option_only":true},"endocriene pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"endocriene pancreas","option_only":true},"exocriene pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"exocriene pancreas","option_only":true},"levercirrose":{"title":"Levercirrose","short":"Bij levercirrose is het leverweefsel vervangen door bindweefsel en regeneratieknobbels, met verlies van leverfunctie en portale hypertensie.","definition":"<p>Oorzaken van <strong>cirrose</strong> zijn o.a. alcohol, NASH, chronische hepatitis B en C, auto-immuunziekten en hemochromatose. Gevolgen: ascites, varices met bloedingen, hepatische encefalopathie, icterus, stollingsstoornissen en een verhoogd risico op hepatocellulair carcinoom. Ernst wordt ingedeeld met Child-Pugh of MELD.</p>","image_url":"","wiki_title":"Cirrhosis","match":"levercirrose|cirrose|cirrhose","option_only":true},"schistosomiasis":{"title":"Schistosomiasis (bilharzia)","short":"Schistosomiasis is een worminfectie via zoet water in de tropen, waarbij larven door de huid binnendringen.","definition":"<p>Afhankelijk van de soort ontstaan klachten van de blaas (hematurie, later blaaskanker) of darm en lever (portale hypertensie). Een acute vorm (Katayama-koorts) geeft koorts, hoest en eosinofilie. Behandeling met praziquantel.</p>","image_url":"","wiki_title":"Schistosomiasis","match":"schistosomiasis|bilharzia","option_only":true},"barrett-slokdarm":{"title":"Barrett-slokdarm","short":"Bij een Barrett-slokdarm is het plaveiselepitheel onderin de slokdarm door chronische reflux vervangen door darmachtig cilinderepitheel.","definition":"<p>Een <strong>Barrett-slokdarm</strong> is een voorstadium van het adenocarcinoom van de slokdarm. Patiënten worden periodiek gecontroleerd met endoscopie en biopten; bij dysplasie volgt endoscopische behandeling.</p>","image_url":"","wiki_title":"Barrett's esophagus","match":"barrett-slokdarm|barrett oesophagus|een barrett slokdarm","option_only":true},"salmonella infectie":{"title":"Salmonella","short":"Salmonella zijn gramnegatieve staven die voedselinfecties (gastro-enteritis) en buiktyfus kunnen veroorzaken.","definition":"<p>Niet-tyfeuze <strong>salmonellae</strong> komen via onvoldoende verhit voedsel (kip, eieren) binnen en geven koorts, buikkrampen en diarree. <em>S. typhi</em> en <em>S. paratyphi</em> veroorzaken (para)tyfus, een systemische ziekte met hoge koorts, relatieve bradycardie en roseola. Bij sikkelcelziekte kan Salmonella osteomyelitis veroorzaken.</p>","image_url":"","wiki_title":"Salmonella","match":"salmonella infectie","option_only":true},"hepatitis-b":{"title":"Hepatitis B","short":"Hepatitis B is een via bloed en seks overgedragen DNA-virus dat acute en chronische leverontsteking geeft, met risico op cirrose en levercelcarcinoom.","definition":"<p><strong>Hepatitis B</strong> wordt veroorzaakt door het hepatitis B-virus, een omhuld (gedeeltelijk dubbelstrengs) DNA-virus. Overdracht via bloed, seksueel contact en van moeder op kind rond de geboorte.</p><p>Bij volwassenen geneest de meeste acute infectie; bij pasgeborenen wordt de infectie meestal <em>chronisch</em>. Chronische hepatitis B kan leiden tot levercirrose en hepatocellulair carcinoom. Diagnostiek via serologie (HBsAg, anti-HBc, anti-HBs). Er is een effectief vaccin.</p>","image_url":"","wiki_title":"Hepatitis B","match":"hepatitis-b","option_only":true},"hepatitis b virus":{"title":"Hepatitis B","short":"Hepatitis B is een via bloed en seks overgedragen DNA-virus dat acute en chronische leverontsteking geeft, met risico op cirrose en levercelcarcinoom.","definition":"<p><strong>Hepatitis B</strong> wordt veroorzaakt door het hepatitis B-virus, een omhuld (gedeeltelijk dubbelstrengs) DNA-virus. Overdracht via bloed, seksueel contact en van moeder op kind rond de geboorte.</p><p>Bij volwassenen geneest de meeste acute infectie; bij pasgeborenen wordt de infectie meestal <em>chronisch</em>. Chronische hepatitis B kan leiden tot levercirrose en hepatocellulair carcinoom. Diagnostiek via serologie (HBsAg, anti-HBc, anti-HBs). Er is een effectief vaccin.</p>","image_url":"","wiki_title":"Hepatitis B","match":"hepatitis b virus","option_only":true},"astma-aanval":{"title":"Astma","short":"Astma is een chronische ontsteking van de luchtwegen met wisselende, reversibele luchtwegobstructie en hyperreactiviteit; klachten zijn piepen, benauwdheid en hoesten.","definition":"<p>Bij <strong>astma</strong> zijn de luchtwegen chronisch ontstoken (vaak eosinofiel/Th2-gemedieerd) en <em>hyperreactief</em>: op prikkels zoals allergenen, inspanning, koude lucht of rook ontstaan bronchoconstrictie, slijmvliesoedeem en slijmproductie.</p><p>De obstructie is variabel en grotendeels <em>reversibel</em> (verbetering van de FEV1 na een luchtwegverwijder). Klachten: aanvallen van piepen, kortademigheid, een beklemd gevoel op de borst en hoesten, vaak ’s nachts. Behandeling met inhalatiecorticosteroïden en luchtwegverwijders.</p>","image_url":"","wiki_title":"Asthma","match":"astma-aanval","option_only":true},"astma-exacerbatie":{"title":"Astma","short":"Astma is een chronische ontsteking van de luchtwegen met wisselende, reversibele luchtwegobstructie en hyperreactiviteit; klachten zijn piepen, benauwdheid en hoesten.","definition":"<p>Bij <strong>astma</strong> zijn de luchtwegen chronisch ontstoken (vaak eosinofiel/Th2-gemedieerd) en <em>hyperreactief</em>: op prikkels zoals allergenen, inspanning, koude lucht of rook ontstaan bronchoconstrictie, slijmvliesoedeem en slijmproductie.</p><p>De obstructie is variabel en grotendeels <em>reversibel</em> (verbetering van de FEV1 na een luchtwegverwijder). Klachten: aanvallen van piepen, kortademigheid, een beklemd gevoel op de borst en hoesten, vaak ’s nachts. Behandeling met inhalatiecorticosteroïden en luchtwegverwijders.</p>","image_url":"","wiki_title":"Asthma","match":"astma-exacerbatie","option_only":true},"ct-scan van het abdomen":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct-scan van het abdomen","option_only":true},"mesenterica superior":{"title":"A. mesenterica superior","short":"De a. mesenterica superior voorziet de dunne darm en het proximale colon van bloed.","definition":"<p>De <strong>a. mesenterica superior</strong> ontspringt ter hoogte van L1 uit de aorta, achter de pancreas, en loopt vóór het duodenum. Takken: aa. jejunales en ileales, a. ileocolica, a. colica dextra en media. Een acute afsluiting (embolie) geeft mesenteriale ischemie met hevige buikpijn bij weinig afwijkingen aan de buik.</p>","image_url":"","wiki_title":"Superior mesenteric artery","match":"mesenterica superior","option_only":true},"tnf-alfablokker":{"title":"Infliximab","short":"Infliximab is een monoklonaal antilichaam tegen TNF-α, gebruikt bij o.a. de ziekte van Crohn, colitis ulcerosa en reumatoïde artritis.","definition":"<p><strong>TNF-α-remmers</strong> zoals infliximab, adalimumab en etanercept remmen een centraal pro-inflammatoir cytokine. Ze worden gebruikt bij IBD, reumatoïde artritis, spondyloartritis en psoriasis. Doordat ze de cellulaire afweer verzwakken, kan latente tuberculose reactiveren; daarom wordt vooraf gescreend. Ook het risico op andere infecties is verhoogd.</p>","image_url":"","wiki_title":"Infliximab","match":"tnf-alfablokker","option_only":true},"tnf-alfaremmers":{"title":"Infliximab","short":"Infliximab is een monoklonaal antilichaam tegen TNF-α, gebruikt bij o.a. de ziekte van Crohn, colitis ulcerosa en reumatoïde artritis.","definition":"<p><strong>TNF-α-remmers</strong> zoals infliximab, adalimumab en etanercept remmen een centraal pro-inflammatoir cytokine. Ze worden gebruikt bij IBD, reumatoïde artritis, spondyloartritis en psoriasis. Doordat ze de cellulaire afweer verzwakken, kan latente tuberculose reactiveren; daarom wordt vooraf gescreend. Ook het risico op andere infecties is verhoogd.</p>","image_url":"","wiki_title":"Infliximab","match":"tnf-alfaremmers","option_only":true},"tnf-alfaremmer":{"title":"Infliximab","short":"Infliximab is een monoklonaal antilichaam tegen TNF-α, gebruikt bij o.a. de ziekte van Crohn, colitis ulcerosa en reumatoïde artritis.","definition":"<p><strong>TNF-α-remmers</strong> zoals infliximab, adalimumab en etanercept remmen een centraal pro-inflammatoir cytokine. Ze worden gebruikt bij IBD, reumatoïde artritis, spondyloartritis en psoriasis. Doordat ze de cellulaire afweer verzwakken, kan latente tuberculose reactiveren; daarom wordt vooraf gescreend. Ook het risico op andere infecties is verhoogd.</p>","image_url":"","wiki_title":"Infliximab","match":"tnf-alfaremmer","option_only":true},"biologicals: tnf-remmers":{"title":"Infliximab","short":"Infliximab is een monoklonaal antilichaam tegen TNF-α, gebruikt bij o.a. de ziekte van Crohn, colitis ulcerosa en reumatoïde artritis.","definition":"<p><strong>TNF-α-remmers</strong> zoals infliximab, adalimumab en etanercept remmen een centraal pro-inflammatoir cytokine. Ze worden gebruikt bij IBD, reumatoïde artritis, spondyloartritis en psoriasis. Doordat ze de cellulaire afweer verzwakken, kan latente tuberculose reactiveren; daarom wordt vooraf gescreend. Ook het risico op andere infecties is verhoogd.</p>","image_url":"","wiki_title":"Infliximab","match":"biologicals: tnf-remmers","option_only":true},"azathioprine (purine-antagonist)":{"title":"Azathioprine","short":"Azathioprine is een immunosuppressivum dat de purinesynthese remt en zo de deling van lymfocyten onderdrukt.","definition":"<p><strong>Azathioprine</strong> wordt omgezet in 6-mercaptopurine en dan in thioguanine-nucleotiden die in het DNA worden ingebouwd. Het wordt gebruikt bij IBD, auto-immuunhepatitis, vasculitis en na transplantatie. Bijwerkingen zijn beenmergsuppressie, levertoxiciteit en pancreatitis. Bij een TPMT-deficiëntie is het risico op ernstige beenmergsuppressie groot; allopurinol versterkt de werking.</p>","image_url":"","wiki_title":"Azathioprine","match":"azathioprine (purine-antagonist)","option_only":true},"methotrexaat (foliumzuurantagonist)":{"title":"Methotrexaat","short":"Methotrexaat is een foliumzuurantagonist; in lage dosis een basismiddel bij reumatoïde artritis en psoriasis, in hoge dosis een cytostaticum.","definition":"<p><strong>Methotrexaat</strong> remt dihydrofolaatreductase. In lage, wekelijkse dosering werkt het ontstekingsremmend (o.a. via adenosine) en is het een hoeksteen bij reumatoïde artritis, psoriasis en IBD; foliumzuur vermindert bijwerkingen. Bijwerkingen: beenmergsuppressie, levertoxiciteit, mucositis en pneumonitis. Het is teratogeen en wordt via de nier uitgescheiden.</p>","image_url":"","wiki_title":"Methotrexate","match":"methotrexaat (foliumzuurantagonist)","option_only":true},"acute pyelonefritis":{"title":"Pyelonefritis","short":"Pyelonefritis is een bacteriële infectie van het nierbekken en de nier, met koorts, flankpijn en vaak klachten van een blaasontsteking.","definition":"<p><strong>Pyelonefritis</strong> is een opstijgende urineweginfectie die de nier en het nierbekken bereikt, meestal door <em>E. coli</em>.</p><p>Kenmerkend zijn koorts, koude rillingen, flankpijn en slagpijn in de nierloge, eventueel met mictieklachten. Het is een gecompliceerde urineweginfectie die behandeld wordt met antibiotica met goede weefselpenetratie (niet nitrofurantoïne).</p>","image_url":"","wiki_title":"Pyelonephritis","match":"acute pyelonefritis","option_only":true},"post-operatieve wondinfectie":{"title":"Wondinfectie","short":"Een wondinfectie is een infectie van een (operatie)wond, met roodheid, warmte, pijn, zwelling en eventueel pus.","definition":"<p>Postoperatieve <strong>wondinfecties</strong> worden vaak veroorzaakt door <em>S. aureus</em> of, bij darmchirurgie, door darmbacteriën. Risicofactoren zijn diabetes, obesitas, roken, lange operaties en contaminatie. Behandeling: openen en draineren, eventueel antibiotica.</p>","image_url":"","wiki_title":"Surgical site infection","match":"post-operatieve wondinfectie","option_only":true},"lymfadenopathie":{"title":"Lymfadenopathie","short":"Vergroting van lymfeklieren, vaak reactief bij infecties.","definition":"<p><b>Lymfadenopathie</b> is het vergroot of afwijkend zijn van lymfeklieren. Meestal reactief bij infecties (bv. in de hals bij keel-/oorontsteking), soms teken van een systeemziekte of maligniteit.</p>","image_url":"","wiki_title":"Lymphadenopathy","match":"lymfadenopathie","option_only":true},"mri scan":{"title":"MRI","short":"MRI maakt met een sterk magneetveld en radiogolven gedetailleerde beelden van weke delen, zonder ioniserende straling.","definition":"<p>Bij <strong>MRI</strong> worden waterstofkernen in een sterk magneetveld door radiogolven aangeslagen; het signaal bij terugkeer verschilt per weefseltype. MRI is bijzonder geschikt voor hersenen, ruggenmerg, gewrichten, weke delen en het bekken. Nadelen zijn de lange duur, kosten en beperkingen bij pacemakers en sommige metalen implantaten.</p>","image_url":"","wiki_title":"Magnetic resonance imaging","match":"mri scan","option_only":true},"sterk verhoogd c-reactief proteïne (crp)":{"title":"CRP","short":"C-reactief proteïne; ontstekingseiwit in het bloed dat helpt de kans op een gecompliceerde infectie in te schatten.","definition":"<p>Het CRP stijgt bij ontsteking of infectie; in de huisartsenpraktijk stuurt het het antibioticabeleid bij luchtweginfecties.</p>","image_url":"","wiki_title":"C-reactive_protein","match":"sterk verhoogd c-reactief proteïne (crp)","option_only":true},"ct thorax/abdomen":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct thorax/abdomen","option_only":true},"linitis plastica (diffuus type carcinoom)":{"title":"Linitis plastica","short":"Diffuus infiltrerend maagcarcinoom waarbij de maagwand stug en verdikt wordt ('leren fles'); hoort bij het diffuse type met verlies van E-cadherine.","definition":"<p><b>Linitis plastica</b> is een diffuus groeiend maagcarcinoom dat de hele maagwand infiltreert en verstijft ('leren-fles-maag'). Geassocieerd met het diffuse type en <b>E-cadherine</b>-mutatie.</p>","image_url":"","wiki_title":"Linitis plastica","match":"linitis plastica (diffuus type carcinoom)","option_only":true},"gastro intestinale stromacel tumor (gist)":{"title":"GIST","short":"Gastro-intestinale stromacel tumor: een mesenchymale tumor van het maag-darmkanaal, uitgaand van de cellen van Cajal, vaak met een KIT (CD117)-mutatie. Meestal in de maag gelegen.","definition":"<p>Een <b>GIST</b> (gastro-intestinale stromacel tumor) is de meest voorkomende mesenchymale tumor van het maag-darmkanaal, uitgaand van de interstitiele cellen van Cajal. Kenmerkend is een activerende mutatie in <i>KIT</i> (CD117) of <i>PDGFRA</i>; behandeling met tyrosinekinaseremmers (imatinib) is mogelijk.</p>","image_url":"","wiki_title":"Gastrointestinal stromal tumor","match":"gastro intestinale stromacel tumor (gist)","option_only":true},"urine sediment":{"title":"Leukocyturie","short":"Leukocyturie is de aanwezigheid van witte bloedcellen in de urine, meestal bij een urineweginfectie.","definition":"<p><strong>Leukocyturie</strong> wordt aangetoond met een teststrook (leukocytenesterase) of microscopie. Meestal past het bij een bacteriële urineweginfectie, eventueel samen met positief nitriet. ‘Steriele’ leukocyturie zonder groei in de kweek komt voor bij o.a. chlamydia, urogenitale tuberculose, tubulo-interstitiële nefritis en na antibioticagebruik.</p>","image_url":"","wiki_title":"Pyuria","match":"urine sediment","option_only":true},"virale hepatitis":{"title":"Virale hepatitis","short":"Leverontsteking door een hepatitisvirus (A, B, C, D of E), met sterk verhoogde transaminasen.","definition":"<p><b>Virale hepatitis</b> is een ontsteking van de lever door hepatotrope virussen. Kenmerkend zijn fors verhoogde transaminasen (ALAT vaak hoger dan ASAT); hepatitis B en C kunnen chronisch worden en tot cirrose/carcinoom leiden.</p>","image_url":"","wiki_title":"Viral hepatitis","match":"virale hepatitis","option_only":true},"oesophaguscarcinoom":{"title":"Oesophaguscarcinoom","short":"Kwaadaardige tumor van de slokdarm, meestal een plaveiselcelcarcinoom of adenocarcinoom (bij Barrett). Geeft vaak slikklachten (dysfagie).","definition":"<p>Kwaadaardige tumor van de <b>slokdarm</b>. De twee hoofdtypen zijn het plaveiselcelcarcinoom (proximaal, geassocieerd met roken/alcohol) en het adenocarcinoom (distaal, ontstaat uit een Barrett-slokdarm). Presenteert zich vaak met progressieve dysfagie en gewichtsverlies. Stagering met endoscopie, EUS en PET-CT.</p>","image_url":"","wiki_title":"Esophageal cancer","match":"oesophaguscarcinoom","option_only":true},"colorectale levermetastasen":{"title":"Colorectale levermetastasen","short":"Uitzaaiingen van dikkedarmkanker naar de lever, de meest voorkomende leveruitzaaiing.","definition":"<p>Metastasen van een colorectaal carcinoom in de lever, via de v. portae. Frequentste maligne leverafwijking; beeldvorming met echo, CT, MRI en PET-scan.</p>","image_url":"","wiki_title":"Colorectal cancer","match":"colorectale levermetastasen","option_only":true},"ct-thorax/abdomen":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct-thorax/abdomen","option_only":true},"hoofdcellen":{"title":"Hoofdcellen","short":"Cellen in de maagwand die pepsinogeen produceren.","definition":"<p><b>Hoofdcellen</b> (chief cells) van de maagklieren bezitten veel ruw endoplasmatisch reticulum voor de aanmaak en secretie van pepsinogeen, het inactieve voorloperenzym van pepsine.</p>","image_url":"","wiki_title":"Gastric chief cell","match":"hoofdcellen","option_only":true},"ductus cysticus":{"title":"Ductus cysticus","short":"De galbuis die de galblaas verbindt met de ductus hepaticus communis.","definition":"<p>De buis die de <b>galblaas</b> verbindt met de ductus hepaticus communis; samen vormen zij de ductus choledochus.</p>","image_url":"","wiki_title":"Cystic duct","match":"ductus cysticus","option_only":true},"ductus hepaticus communis":{"title":"Ductus hepaticus communis","short":"De gemeenschappelijke leverbuis die de gal uit beide leverkwabben verzamelt.","definition":"<p>Gevormd door samenvloeiing van de rechter en linker ductus hepaticus; sluit zich aan met de ductus cysticus tot de ductus choledochus.</p>","image_url":"","wiki_title":"Common hepatic duct","match":"ductus hepaticus communis","option_only":true},"metoclopramide":{"title":"Metoclopramide","short":"Dopamine-antagonist met anti-emetische en prokinetische werking; bij migraine ingezet tegen misselijkheid en om opname van pijnstillers te bevorderen.","definition":"<p>Metoclopramide blokkeert dopamine-D2-receptoren, remt misselijkheid/braken en versnelt de maaglediging. Bij een migraineaanval verbetert het de resorptie van orale analgetica.</p>","image_url":"","wiki_title":"Metoclopramide","match":"metoclopramide","option_only":true},"bloedonderzoek (calcium)":{"title":"Calcium","short":"Mineraal dat essentieel is voor botmineralisatie, spiercontractie en zenuwgeleiding. Opname in de darm wordt bevorderd door 1,25-OH-vitamine D (calcitriol).","definition":"<p><strong>Calcium</strong> wordt in de dunne darm actief opgenomen onder invloed van 1,25-dihydroxyvitamine D. Het grootste deel van het lichaamscalcium ligt opgeslagen in het skelet als hydroxyapatiet.</p>","image_url":"","wiki_title":"Calcium in biology","match":"bloedonderzoek (calcium)","option_only":true},"bumetanide":{"title":"Lisdiureticum","short":"Lisdiuretica remmen de NKCC2-cotransporter in de lis van Henle en zijn de krachtigste plasmiddelen.","definition":"<p><strong>Lisdiuretica</strong> zoals furosemide remmen de Na⁺/K⁺/2Cl⁻-cotransporter in het dikke opstijgende deel van de lis van Henle. Ze worden gebruikt bij oedeem door hartfalen, nierziekte of levercirrose en bij longoedeem. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, metabole alkalose, uitdroging en ototoxiciteit; anders dan thiaziden verhogen ze de calciumuitscheiding.</p>","image_url":"","wiki_title":"Loop diuretic","match":"bumetanide","option_only":true},"ductus arteriosus":{"title":"Ductus arteriosus (Botalli)","short":"Foetaal bloedvat tussen longslagader en aorta dat de longcirculatie omzeilt; sluit normaal na de geboorte.","definition":"<p>De <b>ductus arteriosus</b> verbindt in de foetus de a. pulmonalis met de aorta (long → aorta), zodat de longen worden omzeild. Blijft hij open (persisterende ductus arteriosus), dan ontstaat een links-rechtsshunt.</p>","image_url":"","wiki_title":"Ductus arteriosus","match":"ductus arteriosus","option_only":true},"auto immuun hepatitis":{"title":"Auto-immuunhepatitis","short":"Auto-immuunhepatitis is een chronische leverontsteking waarbij het afweersysteem de hepatocyten aanvalt.","definition":"<p><strong>Auto-immuunhepatitis</strong> komt vaker voor bij vrouwen. Kenmerken zijn verhoogde transaminasen, een verhoogd IgG, auto-antistoffen (ANA, anti-SMA of anti-LKM1) en in het biopt een interfacehepatitis met plasmacellen. Zonder behandeling kan het tot cirrose leiden; het reageert meestal goed op prednison en azathioprine.</p>","image_url":"","wiki_title":"Autoimmune hepatitis","match":"auto immuun hepatitis","option_only":true},"klatskin tumor":{"title":"Klatskin-tumor","short":"Perihilair cholangiocarcinoom ter hoogte van de leverhilus, ingedeeld volgens de Bismuth-classificatie.","definition":"<p>Cholangiocarcinoom gelokaliseerd bij de <b>samenvloeiing van de galwegen</b> in de leverhilus. De uitbreiding wordt ingedeeld volgens de <b>Bismuth-Corlette</b>-classificatie.</p>","image_url":"","wiki_title":"Klatskin tumor","match":"klatskin tumor","option_only":true},"primair scleroserende cholangitis":{"title":"Primair Scleroserende Cholangitis (PSC)","short":"Chronische ontsteking en fibrose van de galwegen, sterk geassocieerd met colitis ulcerosa (IBD).","definition":"<p>Progressieve inflammatie en verlittekening van de intra- en extrahepatische galwegen, leidend tot stricturen en cholestase. Sterke associatie met <b>colitis ulcerosa</b> en verhoogd risico op cholangiocarcinoom.</p>","image_url":"","wiki_title":"Primary sclerosing cholangitis","match":"primair scleroserende cholangitis","option_only":true},"bolle buik (ascites)":{"title":"Ascites","short":"Abnormale ophoping van vocht in de buikholte.","definition":"<p>Ascites is vrij vocht in de peritoneale holte, o.a. door levercirrose, hartfalen of maligniteit (zoals ovariumcarcinoom met peritoneale uitzaaiing).</p>","image_url":"","wiki_title":"Ascites","match":"bolle buik (ascites)","option_only":true},"hartmann procedure":{"title":"Hartmann procedure","short":"Sigmoïdresectie waarbij het proximale colon als eindstandig stoma wordt uitgeleid en de rectumstomp gesloten; bij gecompliceerde diverticulitis/perforatie.","definition":"<p>De <b>Hartmann-procedure</b> verwijdert het zieke sigmoïd, sluit de rectumstomp en legt een eindstandig colostoma aan. Toegepast bij o.a. geperforeerde diverticulitis.</p>","image_url":"","wiki_title":"Hartmann's operation","match":"hartmann procedure","option_only":true},"carcinoïd (neuroendocriene tumor)":{"title":"Neuro-endocriene tumor","short":"Neuro-endocriene tumoren gaan uit van hormoonproducerende cellen, vooral in het maag-darmkanaal, de pancreas en de long.","definition":"<p><strong>Neuro-endocriene neoplasmata</strong> variëren van goed gedifferentieerde, langzaam groeiende tumoren (vroeger carcinoïden) tot agressieve, slecht gedifferentieerde carcinomen (zoals het kleincellig longcarcinoom). Ze kleuren aan met chromogranine en synaptofysine. Sommige maken hormonen; bij levermetastasen van een dunnedarm-NET kan een carcinoïdsyndroom ontstaan (flushing, diarree).</p>","image_url":"","wiki_title":"Neuroendocrine tumor","match":"carcinoïd (neuroendocriene tumor)","option_only":true},"refluxoesophagitis":{"title":"Gastro-oesofageale reflux","short":"Bij refluxklachten stroomt maaginhoud terug in de slokdarm, met zuurbranden en oprispingen.","definition":"<p><strong>Gastro-oesofageale refluxziekte</strong> ontstaat bij een tekortschietende onderste slokdarmsfincter, een hiatus hernia of verhoogde druk in de buik (overgewicht, zwangerschap). Klachten zijn zuurbranden achter het borstbeen en zure oprispingen, soms hoesten of heesheid. Complicaties: oesofagitis, stenose en Barrett-slokdarm. Behandeling met leefstijladviezen en protonpompremmers.</p>","image_url":"","wiki_title":"Gastroesophageal reflux disease","match":"refluxoesophagitis","option_only":true},"zenker’s divertikel":{"title":"Zenkers divertikel","short":"Uitstulping van de farynxmucosa net boven de bovenste slokdarmsfincter, met slikklachten, regurgitatie, geborrel en foetor ex ore.","definition":"<p>Een <b>Zenkers divertikel</b> is een pulsie-divertikel in de zwakke plek (driehoek van Killian) boven de bovenste oesofagussfincter. Klachten zijn dysfagie, regurgitatie van onverteerd voedsel, geborrel bij slikken en slechte adem.</p>","image_url":"","wiki_title":"Zenker's diverticulum","match":"zenker’s divertikel","option_only":true},"gastric sleeve":{"title":"Gastric sleeve","short":"Bariatrische operatie waarbij een groot deel van de maag verwijderd wordt tot een buisvormige maag: restrictie.","definition":"<p>Sleeve-gastrectomie: het grootste deel van de maag wordt verwijderd, waardoor een smalle buisvormige maag overblijft. Vooral <b>restrictief</b>, met ook hormonale effecten (ghreline-daling).</p>","image_url":"","wiki_title":"Sleeve gastrectomy","match":"gastric sleeve","option_only":true},"bilirubine":{"title":"Bilirubine","short":"Geel afbraakproduct van heem dat via de gal wordt uitgescheiden.","definition":"<p><b>Bilirubine</b> ontstaat bij afbraak van erytrocyten. Een galwegafsluiting geeft verhoogd (geconjugeerd) bilirubine in het bloed, donkere urine en lichte ontlasting.</p>","image_url":"","wiki_title":"Bilirubin","match":"bilirubine","option_only":true},"encefalopathie":{"title":"Encefalopathie","short":"Diffuse stoornis van de hersenfunctie, zich uitend in verminderd bewustzijn of gedragsverandering.","definition":"<p><b>Encefalopathie</b> is een verzamelterm voor een diffuse verstoring van het hersenfunctioneren. Samen met subdurale hematomen en retinabloedingen vormt het de trias van inflicted Traumatic Brain Injury.</p>","image_url":"","wiki_title":"Encephalopathy","match":"encefalopathie","option_only":true},"gamma gt":{"title":"γ-GT","short":"γ-GT is een leverenzym dat stijgt bij cholestase en door alcoholgebruik en sommige geneesmiddelen.","definition":"<p><strong>γ-glutamyltransferase</strong> is gevoelig maar niet specifiek. Samen met een verhoogd alkalisch fosfatase bevestigt het een leveroorsprong (cholestase). Een geïsoleerd verhoogd γ-GT past vaak bij alcoholgebruik of enzyminducerende middelen.</p>","image_url":"","wiki_title":"Gamma-glutamyltransferase","match":"gamma gt","option_only":true},"gender (man)":{"title":"Gender","short":"Het sociaal-culturele proces van rollen, taken en eigenschappen die aan mannen en vrouwen worden toegeschreven.","definition":"<p><b>Gender</b> is een sociaal-cultureel begrip: de waarden, attitudes, taken en rollen die als ‘masculien’ of ‘feminien’ worden beschouwd en (ook) worden geïnternaliseerd. Anders dan <b>sekse</b> is gender niet biologisch bepaald.</p>","image_url":"","wiki_title":"","match":"gender (man)","option_only":true},"ige":{"title":"IgE (immunoglobuline E)","short":"Antilichaamklasse die centraal staat bij allergische reacties en de afweer tegen parasieten.","definition":"<p><b>IgE</b> is de antistofklasse die bindt aan mestcellen en basofielen. Bij hernieuwd contact met een allergeen leidt kruisbinding van IgE tot degranulatie en de symptomen van een allergische reactie.</p>","image_url":"","wiki_title":"Immunoglobulin E","match":"ige","option_only":true},"gastric band":{"title":"Gastric band","short":"Bariatrische ingreep waarbij een verstelbare band rond de bovenmaag wordt gelegd (restrictie); het minste lange-termijn gewichtsverlies van de standaardingrepen.","definition":"<p>De <b>maagband</b> (gastric band) knijpt de bovenmaag af (puur restrictief). Van de bariatrische ingrepen geeft hij het <b>minste</b> lange-termijn gewichtsverlies (sleeve &lt; bypass geven meer).</p>","image_url":"","wiki_title":"Adjustable gastric band","match":"gastric band","option_only":true},"retinol zuur":{"title":"Retinolzuur","short":"Actieve metaboliet van vitamine A; stuurt lymfocyten aan om naar de darm te migreren (gut-homing).","definition":"<p>Actieve vorm van <b>vitamine A</b>. Speelt een sleutelrol in het darmimmuunsysteem door de expressie van homing-receptoren op lymfocyten te induceren, zodat deze naar de <b>darm</b> migreren.</p>","image_url":"","wiki_title":"Retinoic acid","match":"retinol zuur","option_only":true},"stenose":{"title":"Stenose","short":"Vernauwing van een vat of klepopening; ter plaatse neemt de stroomsnelheid toe terwijl de volumestroom gelijk blijft.","definition":"<p>Bij een <b>stenose</b> zonder zijtakken blijft de volumetrische stroom constant, waardoor de stroomsnelheid in de vernauwing stijgt (continuïteitswet).</p>","image_url":"","wiki_title":"Stenosis","match":"stenose","option_only":true},"abces":{"title":"Abces","short":"Afgekapselde holte gevuld met pus (etter), een ernstige vorm van purulente ontsteking.","definition":"<p>Een <b>abces</b> is een lokale ophoping van pus in een door ontsteking gevormde holte, veroorzaakt door pyogene (etterverwekkende) bacteriën. Het is een purulente ontsteking.</p>","image_url":"","wiki_title":"Abscess","match":"abces","option_only":true},"vena portae":{"title":"Vena portae","short":"De poortader die het veneuze, voedingrijke bloed van de darmen, milt en pancreas naar de lever transporteert.","definition":"<p>De <strong>vena portae</strong> (poortader) verzamelt het veneuze bloed van de tractus digestivus, milt en pancreas (o.a. via de v. mesenterica superior en v. lienalis) en voert het naar de lever, waar het door de sinusoïden stroomt vóór het via de venae hepaticae naar de v. cava inferior gaat.</p>","image_url":"","wiki_title":"Portal vein","match":"vena portae","option_only":true},"ascites":{"title":"Ascites","short":"Abnormale ophoping van vocht in de buikholte.","definition":"<p>Ascites is vrij vocht in de peritoneale holte, o.a. door levercirrose, hartfalen of maligniteit (zoals ovariumcarcinoom met peritoneale uitzaaiing).</p>","image_url":"","wiki_title":"Ascites","match":"ascites","option_only":true},"cholangitis":{"title":"cholangitis","short":"Een (meestal bacteriele) ontsteking van de galwegen, klassiek door obstructie (steen, stenose). De trias van Charcot bestaat uit koorts, icterus en pijn in de rechterbovenbuik.","definition":"<p><b>Cholangitis</b> is een ontsteking van het galwegsysteem, vaak door obstructie met opstijgende bacteriele infectie. De <i>trias van Charcot</i> (koorts/rillingen, icterus, RBB-pijn) is klassiek; uitgebreid met verwardheid en shock vormt dit de pentade van Reynolds. Behandeling: antibiotica en galwegdrainage (ERCP).</p>","image_url":"","wiki_title":"Ascending cholangitis","match":"cholangitis","option_only":true},"colon carcinoom":{"title":"Coloncarcinoom (darmkanker)","short":"Coloncarcinoom is een kwaadaardige tumor van de dikke darm, meestal een adenocarcinoom dat ontstaat uit een poliep.","definition":"<p>Het <strong>colorectaal carcinoom</strong> ontstaat meestal via de adenoom-carcinoomsequentie, waarbij mutaties (o.a. in APC, KRAS, p53) zich opstapelen. Risicofactoren zijn leeftijd, familiaire belasting (FAP, Lynch-syndroom), IBD, rood en bewerkt vlees, alcohol en roken. Klachten: veranderd ontlastingspatroon, bloed bij de ontlasting en ijzergebreksanemie. In Nederland is er een bevolkingsonderzoek met de FIT-test.</p>","image_url":"","wiki_title":"Colorectal cancer","match":"colon carcinoom","option_only":true},"achalasie":{"title":"Achalasie","short":"Achalasie is een slokdarmmotiliteitsstoornis waarbij de onderste slokdarmsfincter niet goed ontspant, met passageklachten tot gevolg.","definition":"<p><strong>Achalasie</strong> ontstaat door verlies van remmende neuronen in de slokdarmwand: de onderste sfincter (LES) blijft te strak en peristaltiek ontbreekt. Gevolg: dysfagie en voedselstase.</p>","image_url":"","wiki_title":"Esophageal achalasia","match":"achalasie","option_only":true},"oesofagusvarices":{"title":"Oesofagusvarices","short":"Verwijde submuceuze venen in de distale slokdarm door portale hypertensie; kunnen levensbedreigend bloeden (hematemesis).","definition":"<p><b>Oesofagusvarices</b> zijn portosystemische collateralen in de distale slokdarm bij portale hypertensie. Ruptuur geeft massale hematemesis.</p>","image_url":"","wiki_title":"Esophageal varices","match":"oesofagusvarices","option_only":true},"galwegletsel":{"title":"Galwegletsel","short":"Beschadiging van de galwegen, meestal als complicatie van een cholecystectomie; geclassificeerd volgens de Amsterdam-classificatie (type A–D).","definition":"<p><b>Galwegletsel</b> is een gevreesde complicatie van galblaasverwijdering. De <b>Amsterdam-classificatie</b> (type A–D) beschrijft de ernst; type A = lekkage uit de ductus cysticus of kleine gangetjes.</p>","image_url":"","wiki_title":"Bile duct injury","match":"galwegletsel","option_only":true},"urineweg infectie":{"title":"Urineweginfectie","short":"Infectie van de urinewegen, meestal bacterieel; kan leucocyturie en een positieve nitriettest geven.","definition":"<p>Een <b>urineweginfectie</b> is meestal een bacteriële infectie van blaas of hogere urinewegen, gekenmerkt door leucocyturie, bacteriurie en vaak een positieve nitriettest.</p>","image_url":"","wiki_title":"Urinary tract infection","match":"urineweg infectie","option_only":true},"ct-abdomen, met oraal contrast":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct-abdomen, met oraal contrast","option_only":true},"galzouten":{"title":"Galzouten","short":"Uit cholesterol gevormde stoffen die vetten emulgeren voor de vertering en opname.","definition":"<p><b>Galzouten</b> worden door de lever aangemaakt, in de gal uitgescheiden en grotendeels in het ileum heropgenomen (enterohepatische kringloop).</p>","image_url":"","wiki_title":"Bile acid","match":"galzouten","option_only":true},"papil van vater":{"title":"papil van Vater","short":"De uitmonding van de gemeenschappelijke galgang en de pancreasgang in het duodenum (ampulla hepatopancreatica). Een carcinoom hier geeft een double duct sign.","definition":"<p>De <b>papil van Vater</b> (ampulla van Vater) is de gezamenlijke uitmonding van de ductus choledochus en de ductus pancreaticus in het duodenum. Een <i>papil van Vater-carcinoom</i> obstrueert beide gangen en geeft daardoor het radiologische <b>double duct sign</b> (verwijde galweg en pancreasgang).</p>","image_url":"","wiki_title":"Ampulla of Vater","match":"papil van vater","option_only":true},"eosinofiele oesophagitis":{"title":"Eosinofiele oesophagitis","short":"Chronische, allergisch/immuun-gemedieerde ontsteking van de slokdarm met eosinofiele infiltratie; frequente oorzaak van voedselimpactie bij jongvolwassenen.","definition":"<p><b>Eosinofiele oesophagitis</b> (EoE) is een chronische ontsteking van de slokdarm door eosinofiele infiltratie. Het presenteert zich vaak met dysfagie en <i>voedselimpactie</i> bij jongvolwassenen. Behandeling: <i>protonpompremmers</i>, topicale corticosteroïden en eliminatiedieet.</p>","image_url":"","wiki_title":"Eosinophilic esophagitis","match":"eosinofiele oesophagitis","option_only":true},"giardia":{"title":"Giardiasis","short":"Giardiasis is een darminfectie met de protozo Giardia lamblia, met langdurige diarree, opgeblazen gevoel en vetrijke ontlasting.","definition":"<p><strong><em>Giardia lamblia</em></strong> wordt via cysten in besmet water of voedsel opgelopen. De trofozoïeten hechten aan het dunnedarmepitheel zonder het te binnendringen. Klachten: waterige, vettige, stinkende ontlasting, buikkrampen, winderigheid en gewichtsverlies, soms wekenlang. Diagnose met PCR of microscopie van ontlasting; behandeling met metronidazol of tinidazol.</p>","image_url":"","wiki_title":"Giardiasis","match":"giardia","option_only":true},"sondevoeding":{"title":"Sondevoeding","short":"Toediening van vloeibare voeding via een sonde direct in maag of darm.","definition":"<p>Sondevoeding levert voeding via een neus-maagsonde of PEG-sonde bij patiënten die onvoldoende via de mond kunnen eten. Bij gevorderde dementie geeft het geen levensverlenging of betere kwaliteit van leven en kan het complicaties geven.</p>","image_url":"","wiki_title":"Feeding tube","match":"sondevoeding","option_only":true},"mesalazine":{"title":"Mesalazine (5-ASA)","short":"Ontstekingsremmend middel (5-aminosalicylzuur) voor onderhoudsbehandeling van colitis ulcerosa.","definition":"<p><b>Mesalazine</b> (5-aminosalicylzuur, 5-ASA) is een lokaal ontstekingsremmend middel dat als eerste keus wordt gebruikt voor inductie en onderhoud van remissie bij milde tot matige colitis ulcerosa.</p>","image_url":"","wiki_title":"Mesalazine","match":"mesalazine","option_only":true},"urine weg infectie":{"title":"Urineweginfectie","short":"Infectie van de urinewegen, meestal bacterieel; kan leucocyturie en een positieve nitriettest geven.","definition":"<p>Een <b>urineweginfectie</b> is meestal een bacteriële infectie van blaas of hogere urinewegen, gekenmerkt door leucocyturie, bacteriurie en vaak een positieve nitriettest.</p>","image_url":"","wiki_title":"Urinary tract infection","match":"urine weg infectie","option_only":true},"zenker's divertikel":{"title":"Zenkers divertikel","short":"Uitstulping van de farynxmucosa net boven de bovenste slokdarmsfincter, met slikklachten, regurgitatie, geborrel en foetor ex ore.","definition":"<p>Een <b>Zenkers divertikel</b> is een pulsie-divertikel in de zwakke plek (driehoek van Killian) boven de bovenste oesofagussfincter. Klachten zijn dysfagie, regurgitatie van onverteerd voedsel, geborrel bij slikken en slechte adem.</p>","image_url":"","wiki_title":"Zenker's diverticulum","match":"zenker's divertikel","option_only":true},"autoimmuun hepatitis":{"title":"Auto-immuunhepatitis","short":"Auto-immuunhepatitis is een chronische leverontsteking waarbij het afweersysteem de hepatocyten aanvalt.","definition":"<p><strong>Auto-immuunhepatitis</strong> komt vaker voor bij vrouwen. Kenmerken zijn verhoogde transaminasen, een verhoogd IgG, auto-antistoffen (ANA, anti-SMA of anti-LKM1) en in het biopt een interfacehepatitis met plasmacellen. Zonder behandeling kan het tot cirrose leiden; het reageert meestal goed op prednison en azathioprine.</p>","image_url":"","wiki_title":"Autoimmune hepatitis","match":"autoimmuun hepatitis","option_only":true},"primair scleroserende cholangitis (psc)":{"title":"Primair Scleroserende Cholangitis (PSC)","short":"Chronische ontsteking en fibrose van de galwegen, sterk geassocieerd met colitis ulcerosa (IBD).","definition":"<p>Progressieve inflammatie en verlittekening van de intra- en extrahepatische galwegen, leidend tot stricturen en cholestase. Sterke associatie met <b>colitis ulcerosa</b> en verhoogd risico op cholangiocarcinoom.</p>","image_url":"","wiki_title":"Primary sclerosing cholangitis","match":"primair scleroserende cholangitis (psc)","option_only":true},"ca19,9":{"title":"CA 19-9","short":"Tumormarker geassocieerd met pancreas- en galwegcarcinoom (cholangiocarcinoom).","definition":"<p>Koolhydraatantigeen 19-9, tumormarker die verhoogd is bij pancreas- en galwegcarcinoom (cholangiocarcinoom).</p>","image_url":"","wiki_title":"CA19-9","match":"ca19,9","option_only":true},"primaire scleroserende cholangitis":{"title":"primaire scleroserende cholangitis","short":"Primaire scleroserende cholangitis (PSC) is een chronische ontsteking met fibrose van de galwegen, sterk geassocieerd met colitis ulcerosa; kenmerkend zijn strengvormige galgangvernauwingen ('kralensnoer').","definition":"<p><b>Primaire scleroserende cholangitis</b> (PSC) is een progressieve ontsteking en fibrose van de intra- en extrahepatische galwegen, met multifocale stricturen ('kralensnoer' op MRCP). Sterk geassocieerd met <b>colitis ulcerosa</b>. Verhoogt het risico op cholangiocarcinoom. Presenteert met cholestase (verhoogd bilirubine, γGT, AF).</p>","image_url":"","wiki_title":"Primary sclerosing cholangitis","match":"primaire scleroserende cholangitis","option_only":true},"bèta-blokker":{"title":"Bètablokker","short":"Bètablokkers blokkeren bèta-adrenerge receptoren en verlagen hartfrequentie, contractiekracht en reninesecretie.","definition":"<p><strong>Bètablokkers</strong> worden gebruikt bij hypertensie, angina pectoris, na een hartinfarct, bij hartfalen, ritmestoornissen, tremor en migraineprofylaxe. Cardioselectieve middelen (metoprolol, bisoprolol) werken vooral op β1; niet-selectieve (propranolol) ook op β2, wat bronchospasme kan geven. Bijwerkingen: bradycardie, vermoeidheid, koude extremiteiten en het maskeren van hypoglykemieverschijnselen.</p>","image_url":"","wiki_title":"Beta blocker","match":"bèta-blokker","option_only":true},"pid":{"title":"Salpingitis","short":"Salpingitis is een ontsteking van de eileiders, meestal door een opstijgende seksueel overdraagbare infectie.","definition":"<p><strong>Salpingitis</strong> maakt deel uit van pelvic inflammatory disease (PID) en wordt vaak veroorzaakt door <em>Chlamydia trachomatis</em> of gonokokken. Klachten: onderbuikpijn, koorts, abnormale afscheiding en slingerpijn bij vaginaal toucher. Complicaties zijn tubo-ovarieel abces, verklevingen, buitenbaarmoederlijke zwangerschap en subfertiliteit.</p>","image_url":"","wiki_title":"Salpingitis","match":"pid","option_only":true},"pelvic inflammatory disease":{"title":"Salpingitis","short":"Salpingitis is een ontsteking van de eileiders, meestal door een opstijgende seksueel overdraagbare infectie.","definition":"<p><strong>Salpingitis</strong> maakt deel uit van pelvic inflammatory disease (PID) en wordt vaak veroorzaakt door <em>Chlamydia trachomatis</em> of gonokokken. Klachten: onderbuikpijn, koorts, abnormale afscheiding en slingerpijn bij vaginaal toucher. Complicaties zijn tubo-ovarieel abces, verklevingen, buitenbaarmoederlijke zwangerschap en subfertiliteit.</p>","image_url":"","wiki_title":"Salpingitis","match":"pelvic inflammatory disease","option_only":true},"v. umbilicalis":{"title":"Vena umbilicalis","short":"Foetale navelstrengader; het obliterende restant vormt het ligamentum teres hepatis.","definition":"<p>De <b>vena umbilicalis</b> voert in de foetus zuurstofrijk bloed van de placenta naar de foetus. Na de geboorte obliteert zij tot het <i>ligamentum teres hepatis</i> (rond ligament van de lever).</p>","image_url":"","wiki_title":"Umbilical vein","match":"v. umbilicalis","option_only":true},"meckel’s divertikel":{"title":"Divertikel van Meckel","short":"Het divertikel van Meckel is een restant van de ductus omphaloentericus aan het ileum; het kan bloeden, ontsteken of een obstructie veroorzaken.","definition":"<p>De ‘regel van 2’: komt bij ongeveer 2% van de mensen voor, ligt ongeveer 60 cm (2 voet) van de ileocaecaalklep, is ongeveer 5 cm lang en geeft vaak klachten vóór het 2e jaar. Het kan maagslijmvlies bevatten, met ulceratie en pijnloos rectaal bloedverlies, of als leidpunt voor invaginatie dienen.</p>","image_url":"","wiki_title":"Meckel's diverticulum","match":"meckel’s divertikel","option_only":true},"pylorus":{"title":"Pylorus (maagportier)","short":"De pylorus is de gespierde overgang van de maag naar het duodenum, die de lediging van de maag regelt.","definition":"<p>De <strong>pylorus</strong> laat de maaginhoud in kleine porties door. Bij zuigelingen kan de spier verdikken (hypertrofische pylorusstenose). Bij volwassenen kan een ulcus of tumor bij de pylorus een maaguitgangsstenose geven.</p>","image_url":"","wiki_title":"Pylorus","match":"pylorus|maagportier|pylorussfincter","option_only":true},"cytonucleaire atypie":{"title":"Kenmerken van maligniteit (histologie)","short":"Kenmerken van een kwaadaardige tumor onder de microscoop zijn atypische kernen, veel (afwijkende) delingsfiguren, infiltratieve groei en uitzaaiing.","definition":"<p>Bij <strong>cytonucleaire atypie</strong> zijn de kernen vergroot, onregelmatig, donker en wisselend van vorm. Alleen infiltratie in het omliggende weefsel en metastasering bewijzen kwaadaardigheid; atypie en mitosen kunnen ook bij een goedaardige of reactieve afwijking voorkomen.</p>","image_url":"","wiki_title":"Nuclear atypia","match":"cytonucleaire atypie|talrijke mitosefiguren|atypie|infiltratie|metastasering","option_only":true},"diverticulosis/itis":{"title":"Diverticulose en diverticulitis","short":"Bij diverticulose zijn er uitstulpingen van het slijmvlies door de wand van het colon; als zo'n divertikel ontsteekt, heet het diverticulitis.","definition":"<p><strong>Diverticulose</strong> komt in westerse landen vooral voor in het sigmoïd, bij ouderen en bij een vezelarm dieet. Diverticulitis geeft pijn linksonder en koorts; complicaties zijn een abces, perforatie en fistels. Divertikels kunnen ook pijnloos een forse bloeding geven.</p>","image_url":"","wiki_title":"Diverticular disease","match":"diverticulosis/itis|diverticulose|diverticulitis|divertikelbloeding in het colon","option_only":true},"een granuloom":{"title":"Granuloom","short":"Een granuloom is een ophoping van geactiveerde macrofagen (epitheloïde cellen), vaak met reuscellen, rond een moeilijk afbreekbare prikkel.","definition":"<p><strong>Granulomen</strong> ontstaan bij tuberculose (met centrale verkazing), sarcoïdose, de ziekte van Crohn, schimmelinfecties en reacties op vreemd materiaal. Ze ontstaan via Th1-cellen en IFN-γ. Een abces bestaat juist uit granulocyten en pus.</p>","image_url":"","wiki_title":"Granuloma","match":"een granuloom|granuloom|granulomateuze ontsteking","option_only":true},"thiopurinederivaat":{"title":"Thiopurines","short":"Thiopurines (azathioprine, mercaptopurine, tioguanine) zijn immunosuppressiva die de aanmaak van purines remmen, o.a. gebruikt bij IBD.","definition":"<p>Voor de start van <strong>thiopurines</strong> wordt de TPMT/NUDT15-activiteit bepaald, omdat een laag enzymniveau ernstige beenmergsuppressie geeft. Andere bijwerkingen zijn pancreatitis, leverschade en een verhoogd risico op huidkanker en lymfomen. Allopurinol remt de afbraak en versterkt de werking.</p>","image_url":"","wiki_title":"Thiopurine","match":"thiopurinederivaat|thiopurines|mercaptopurine|tioguanine","option_only":true},"brachytherapie met iridiumnaalden":{"title":"Brachytherapie","short":"Bij brachytherapie wordt een radioactieve bron in of vlak naast de tumor geplaatst, zodat een hoge dosis lokaal wordt gegeven.","definition":"<p><strong>Brachytherapie</strong> wordt o.a. gebruikt bij baarmoederhals-, prostaat- en slokdarmkanker, vaak in combinatie met uitwendige bestraling.</p>","image_url":"","wiki_title":"Brachytherapy","match":"brachytherapie met iridiumnaalden|brachytherapie|inwendige bestraling","option_only":true},"alfa foeto proteïne bepalen":{"title":"Alfa-foetoproteïne (AFP)","short":"AFP is een eiwit dat de foetus maakt; bij volwassenen is een verhoogd AFP een tumormarker voor levercelkanker en sommige kiemceltumoren.","definition":"<p>Een verhoogd <strong>AFP</strong> past bij het hepatocellulair carcinoom en niet-seminomateuze kiemceltumoren (dooierzaktumor). In de zwangerschap wijst een hoog AFP op een open neuraalbuisdefect of buikwanddefect, een laag AFP op het syndroom van Down.</p>","image_url":"","wiki_title":"Alpha-fetoprotein","match":"alfa foeto proteïne bepalen|afp|alfa-foetoproteïne","option_only":true},"sofosbuvir":{"title":"Sofosbuvir (DAA's)","short":"Sofosbuvir is een direct werkend antiviraal middel dat het RNA-polymerase van het hepatitis C-virus remt.","definition":"<p>Combinaties van <strong>DAA's</strong> (bijv. sofosbuvir met velpatasvir) genezen hepatitis C in meer dan 95% van de gevallen in 8–12 weken, met weinig bijwerkingen.</p>","image_url":"","wiki_title":"Sofosbuvir","match":"sofosbuvir|direct werkende antivirale middelen|daa","option_only":true},"tenofovir":{"title":"Tenofovir","short":"Tenofovir is een nucleotide-reverse-transcriptaseremmer, gebruikt bij hiv en chronische hepatitis B.","definition":"<p><strong>Tenofovir</strong> wordt ook gebruikt als PrEP tegen hiv. De oudere vorm (TDF) kan de nierfunctie en botdichtheid aantasten; de nieuwere vorm (TAF) minder.</p>","image_url":"","wiki_title":"Tenofovir","match":"tenofovir","option_only":true},"mrcp":{"title":"MRCP","short":"MRCP is een MRI-onderzoek dat galwegen en pancreasgang in beeld brengt zonder contrast of ingreep.","definition":"<p><strong>MRCP</strong> wordt gebruikt bij verdenking op galwegstenen, PSC en tumoren. Als er een behandeling nodig is (steen verwijderen, stent plaatsen), volgt een ERCP.</p>","image_url":"","wiki_title":"Magnetic resonance cholangiopancreatography","match":"mrcp|mr-cholangiopancreaticografie","option_only":true},"steenextractie middels ercp":{"title":"ERCP","short":"Bij een ERCP wordt via een endoscoop in het duodenum de papil van Vater opgezocht, waarna galwegen en pancreasgang met contrast kunnen worden afgebeeld en behandeld.","definition":"<p>Met een <strong>ERCP</strong> kunnen na een papillotomie galstenen worden verwijderd en stents worden geplaatst. De belangrijkste complicatie is een post-ERCP-pancreatitis; daarnaast bloeding, perforatie en cholangitis.</p>","image_url":"","wiki_title":"Endoscopic retrograde cholangiopancreatography","match":"steenextractie middels ercp|ercp|endoscopische retrograde cholangiopancreaticografie","option_only":true},"fibroscan":{"title":"Fibroscan (transiënte elastografie)","short":"Een Fibroscan meet met een echografische techniek de stijfheid van de lever, als maat voor leverfibrose.","definition":"<p>De <strong>Fibroscan</strong> wordt gebruikt om fibrose en cirrose op te sporen bij chronische leverziekten (NAFLD, hepatitis B en C), zodat vaak geen leverbiopt nodig is.</p>","image_url":"","wiki_title":"Transient elastography","match":"fibroscan|elastografie","option_only":true},"loperamide":{"title":"Loperamide","short":"Loperamide is een opioïd dat via µ-receptoren in de darmwand de peristaltiek remt, zonder centrale werking in normale doseringen.","definition":"<p><strong>Loperamide</strong> wordt gebruikt bij diarree zonder koorts of bloed. Bij invasieve diarree (bloed, hoge koorts) of <em>C. difficile</em> wordt het afgeraden, vanwege het risico op een toxisch megacolon.</p>","image_url":"","wiki_title":"Loperamide","match":"loperamide","option_only":true},"galzure zouten diarree":{"title":"Galzuurdiarree","short":"Bij galzuurdiarree komen te veel galzuren in het colon, waar ze water- en zoutsecretie geven.","definition":"<p><strong>Galzuurdiarree</strong> komt voor na een resectie van het terminale ileum, bij de ziekte van Crohn van het ileum en na een cholecystectomie. Behandeling met galzuurbinders (colestyramine).</p>","image_url":"","wiki_title":"Bile acid malabsorption","match":"galzure zouten diarree|galzuurdiarree|galzuurmalabsorptie","option_only":true},"squameuze metaplasie":{"title":"Squameuze metaplasie","short":"Bij squameuze metaplasie wordt cilinder- of trilhaarepitheel vervangen door plaveiselepitheel, als aanpassing aan chronische prikkeling.","definition":"<p>Voorbeelden zijn <strong>squameuze metaplasie</strong> in de bronchi bij rokers en in de transformatiezone van de baarmoederhals. Metaplasie is omkeerbaar, maar kan overgaan in dysplasie en kanker.</p>","image_url":"","wiki_title":"Squamous metaplasia","match":"squameuze metaplasie|plaveiselcelmetaplasie","option_only":true},"a. cystica":{"title":"A. cystica","short":"De a. cystica voorziet de galblaas van bloed en is meestal een tak van de a. hepatica dextra.","definition":"<p>Bij een cholecystectomie worden de <strong>a. cystica</strong> en de ductus cysticus in de driehoek van Calot geclipt. Variaties in de anatomie van deze vaten en galwegen geven het risico op galwegletsel.</p>","image_url":"","wiki_title":"Cystic artery","match":"a. cystica|arteria cystica","option_only":true},"a. hepatica dextra":{"title":"A. hepatica propria, dextra en sinistra","short":"De a. hepatica propria splitst zich in een rechter- en linkertak die de leverhelften van zuurstofrijk bloed voorzien.","definition":"<p>De lever krijgt ongeveer 25% van het bloed via de <strong>a. hepatica</strong> (zuurstofrijk) en 75% via de v. portae. Galwegen zijn voor hun bloedvoorziening vrijwel alleen van de a. hepatica afhankelijk, waardoor trombose na een levertransplantatie galwegschade geeft.</p>","image_url":"","wiki_title":"Hepatic artery proper","match":"a. hepatica dextra|a. hepatica sinistra|a. hepatica propria","option_only":true},"a. pancreaticoduodenalis":{"title":"Aa. pancreaticoduodenales","short":"De aa. pancreaticoduodenales voorzien de pancreaskop en het duodenum en verbinden het stroomgebied van de truncus coeliacus met dat van de a. mesenterica superior.","definition":"<p>De bovenste takken komen uit de a. gastroduodenalis (truncus coeliacus), de onderste uit de a. mesenterica superior. Een ulcus aan de achterwand van het duodenum kan in de a. gastroduodenalis eroderen, met een ernstige bloeding.</p>","image_url":"","wiki_title":"Pancreaticoduodenal arteries","match":"a. pancreaticoduodenalis|aa. pancreaticoduodenales","option_only":true},"antireflux chirurgie":{"title":"Antirefluxchirurgie (fundoplicatie)","short":"Bij een fundoplicatie wordt de maagfundus om de onderkant van de slokdarm gevouwen, om reflux te voorkomen.","definition":"<p>Een <strong>fundoplicatie volgens Nissen</strong> is een optie bij ernstige refluxziekte die niet goed reageert op protonpompremmers, of bij een grote hiatus hernia. Bijwerkingen zijn slikklachten en niet kunnen boeren of braken (gas bloat).</p>","image_url":"","wiki_title":"Nissen fundoplication","match":"antireflux chirurgie|fundoplicatie|nissen","option_only":true},"partiële tromboplastinetijd":{"title":"Stollingstijden (PT en aPTT)","short":"De protrombinetijd (PT/INR) meet de extrinsieke route en de aPTT de intrinsieke route van de stolling.","definition":"<p>Een verlengde <strong>PT/INR</strong> komt voor bij vitamine K-antagonisten, vitamine K-tekort en leverziekte (factor VII heeft de kortste halfwaardetijd, dus PT is een goede maat voor de leversyntheefunctie). Een verlengde <strong>aPTT</strong> past bij heparine, hemofilie A en B, en het lupusanticoagulans.</p>","image_url":"","wiki_title":"Prothrombin time","match":"partiële tromboplastinetijd|aptt|prothrombinetijd|protrombinetijd|pt|inr","option_only":true},"slokdarmvarices":{"title":"Slokdarmvarices","short":"Slokdarmvarices zijn verwijde venen onderin de slokdarm door portale hypertensie, meestal bij levercirrose.","definition":"<p>Een bloeding uit <strong>varices</strong> is levensbedreigend. Behandeling: vasoactieve middelen (terlipressine of octreotide), antibiotica, en endoscopisch rubberbandligatie. Preventie met niet-selectieve bètablokkers (propranolol, carvedilol) of ligatie. Bij falen een TIPS.</p>","image_url":"","wiki_title":"Esophageal varices","match":"slokdarmvarices|oesofagusvarices|maagvarices","option_only":true},"hyperplastische poliep":{"title":"Poliepen van het colon","short":"Darmpoliepen worden ingedeeld in adenomen (voorstadium van kanker), hyperplastische en serrated poliepen, inflammatoire en juveniele (hamartomateuze) poliepen.","definition":"<p>De meeste darmkankers ontstaan uit een <strong>adenoom</strong> (adenoom-carcinoomsequentie). Kleine hyperplastische poliepen in het rectosigmoïd zijn onschuldig; sessiele serrated laesies kunnen wel ontaarden. Juveniele poliepen zijn hamartomen; bij meerdere poliepen is een erfelijk syndroom mogelijk.</p>","image_url":"","wiki_title":"Colorectal polyp","match":"hyperplastische poliep|inflammatoire poliep|juveniele poliep|adenomateuze poliep|adenoom","option_only":true},"retinal":{"title":"Retinal (vitamine A)","short":"Retinal is de vorm van vitamine A die in het oog aan opsine bindt en zo het lichtgevoelige rodopsine vormt.","definition":"<p>Een tekort aan <strong>vitamine A</strong> geeft nachtblindheid, droge ogen (xeroftalmie) en een verhoogde kans op infecties. Vitamine A en zijn derivaten (isotretinoïne) zijn in hoge doses teratogeen.</p>","image_url":"","wiki_title":"Retinal","match":"retinal|retinol|vitamine a","option_only":true},"metamucil":{"title":"Psylliumvezels (Metamucil)","short":"Psylliumvezels zijn volumevormende laxantia die water binden en zo de ontlasting zachter en volumineuzer maken.","definition":"<p>Volumevormers zoals <strong>psyllium</strong> (ispaghula) zijn een eerste stap bij obstipatie en worden ook gebruikt bij het prikkelbaredarmsyndroom. Voldoende drinken is nodig; ze werken pas na enkele dagen.</p>","image_url":"","wiki_title":"Psyllium","match":"metamucil|psyllium|vezels|volumevormend laxans","option_only":true},"parotitis":{"title":"Parotitis","short":"Parotitis is een ontsteking van de oorspeekselklier, viraal (bof) of bacterieel.","definition":"<p><strong>Bof</strong> (mumps) geeft een pijnlijke zwelling van de parotis aan een of beide kanten; complicaties zijn orchitis, meningitis en pancreatitis. Een bacteriële parotitis (vaak <em>S. aureus</em>) komt vooral voor bij uitgedroogde ouderen, met pus uit de afvoergang.</p>","image_url":"","wiki_title":"Parotitis","match":"parotitis|bof","option_only":true},"asat":{"title":"ASAT en ALAT","short":"ASAT en ALAT zijn enzymen die vrijkomen bij beschadiging van levercellen; ALAT is specifieker voor de lever.","definition":"<p>Zeer hoge <strong>transaminasen</strong> (&gt; 1000) passen bij virale hepatitis, ischemische hepatitis en paracetamolvergiftiging. Een ASAT/ALAT-ratio boven 2 past bij alcoholische leverziekte. ASAT komt ook vrij bij spier- en hartspierschade.</p>","image_url":"","wiki_title":"Aspartate transaminase","match":"asat|alat|transaminasen|levertransaminasen","option_only":true},"propanolol":{"title":"Propranolol","short":"Propranolol is een niet-selectieve bètablokker, o.a. gebruikt bij portale hypertensie, migraineprofylaxe, essentiële tremor en de lichamelijke kant van angst.","definition":"<p>Door blokkade van β1 en β2 verlaagt <strong>propranolol</strong> de hartminuutvolume en vernauwt het de splanchnische vaten, wat de poortaderdruk verlaagt. Het kan bronchospasmen geven bij astma en de symptomen van een hypoglykemie maskeren.</p>","image_url":"","wiki_title":"Propranolol","match":"propanolol|propranolol","option_only":true},"cholesterolstenen":{"title":"Galstenen","short":"De meeste galstenen zijn cholesterolstenen; pigmentstenen ontstaan bij hemolyse (zwart) of infecties van de galwegen (bruin).","definition":"<p>Risicofactoren voor <strong>cholesterolstenen</strong> zijn vrouw zijn, leeftijd boven 40, overgewicht, zwangerschap, snel afvallen en bepaalde etnische achtergronden. De meeste galstenen geven geen klachten; complicaties zijn koliek, cholecystitis, choledocholithiasis, cholangitis en pancreatitis.</p>","image_url":"","wiki_title":"Gallstone","match":"cholesterolstenen|pigmentstenen|galstenen|cholelithiasis","option_only":true},"medium-chain triglyceriden":{"title":"Middellangeketen-triglyceriden (MCT)","short":"MCT-vetten worden zonder gal en lipase grotendeels direct via de poortader opgenomen, zonder chylomicronen.","definition":"<p><strong>MCT</strong> wordt gebruikt als energiebron bij vetmalabsorptie, chylothorax, korte darm en bepaalde stofwisselingsziekten (bijv. LCHAD-deficiëntie).</p>","image_url":"","wiki_title":"Medium-chain triglyceride","match":"medium-chain triglyceriden|mct|mct-vetten","option_only":true},"adhesies":{"title":"Adhesies (verklevingen)","short":"Adhesies zijn bindweefselstrengen tussen organen of tussen organen en de buikwand, meestal na een buikoperatie of ontsteking.","definition":"<p><strong>Adhesies</strong> zijn de meest voorkomende oorzaak van een dunnedarmobstructie. Ze kunnen ook chronische buikpijn en verminderde vruchtbaarheid veroorzaken.</p>","image_url":"","wiki_title":"Adhesion (medicine)","match":"adhesies|verklevingen|adhesieileus","option_only":true},"galsteenileus":{"title":"Galsteenileus","short":"Bij een galsteenileus is een grote galsteen via een fistel van galblaas naar duodenum in de darm terechtgekomen, waar hij de dunne darm afsluit, meestal bij de ileocaecale klep.","definition":"<p>Een <strong>galsteenileus</strong> komt vooral voor bij oudere vrouwen. Op de foto of CT zijn lucht in de galwegen (pneumobilie), een dunnedarmobstructie en soms een verkalkte steen te zien (trias van Rigler).</p>","image_url":"","wiki_title":"Gallstone ileus","match":"galsteenileus","option_only":true},"low anterior resectie":{"title":"Low anterior resectie (LAR)","short":"Bij een low anterior resectie wordt het rectum met een deel van het sigmoïd verwijderd en wordt de darm opnieuw aan de anus verbonden.","definition":"<p>Een <strong>LAR</strong> wordt gedaan bij rectumtumoren boven de sluitspier, vaak met een tijdelijk beschermend stoma. Na de operatie kan het ‘LARS’ (low anterior resection syndrome) optreden: aandrang, frequentie en incontinentie.</p>","image_url":"","wiki_title":"Low anterior resection","match":"low anterior resectie|lar|lage anterior resectie","option_only":true},"calprotectine":{"title":"Fecaal calprotectine","short":"Calprotectine is een eiwit uit neutrofielen; een verhoogde waarde in de ontlasting wijst op een ontsteking van de darm.","definition":"<p>Met <strong>fecaal calprotectine</strong> kan onderscheid worden gemaakt tussen een prikkelbaredarmsyndroom (normaal) en IBD (verhoogd). Het wordt ook gebruikt om de activiteit van IBD te volgen. Het is niet specifiek: ook infecties en NSAID's verhogen het.</p>","image_url":"","wiki_title":"Calprotectin","match":"calprotectine|fecaal calprotectine","option_only":true},"octreotide":{"title":"Octreotide","short":"Octreotide is een somatostatineanaloog dat de afgifte van veel hormonen remt en de splanchnische doorbloeding vermindert.","definition":"<p><strong>Octreotide</strong> wordt gebruikt bij varicesbloedingen, neuro-endocriene tumoren (carcinoïdsyndroom), acromegalie en bepaalde vormen van diarree. Het kan galstenen veroorzaken.</p>","image_url":"","wiki_title":"Octreotide","match":"octreotide|somatostatine-analoog","option_only":true},"totale colectomie met pouch":{"title":"Proctocolectomie met ileo-anale pouch (IPAA)","short":"Bij een proctocolectomie met pouch worden colon en rectum verwijderd en wordt van het laatste stuk dunne darm een reservoir gemaakt dat aan de anus wordt verbonden.","definition":"<p>Een <strong>IPAA</strong> wordt gedaan bij colitis ulcerosa die niet op medicatie reageert of met dysplasie, en bij familiaire adenomateuze polyposis. Een bekende complicatie is pouchitis. Bij een acute ernstige colitis wordt eerst een subtotale colectomie met tijdelijk stoma gedaan.</p>","image_url":"","wiki_title":"Ileo-anal pouch","match":"totale colectomie met pouch|ileo-anale pouch|ipaa|subtotale colectomie","option_only":true},"x colon inloop":{"title":"Colon-inloopfoto","short":"Bij een colon-inloopfoto wordt het colon met contrast via de anus gevuld en op röntgenfoto's afgebeeld.","definition":"<p>Een <strong>colon-inloop</strong> is grotendeels vervangen door coloscopie en CT-colografie, maar wordt nog gebruikt om fistels, stricturen of naadlekkage in beeld te brengen (met wateroplosbaar contrast).</p>","image_url":"","wiki_title":"Lower gastrointestinal series","match":"x colon inloop|colon inloop|x-colon","option_only":true},"een toxisch megacolon":{"title":"Toxisch megacolon","short":"Een toxisch megacolon is een acute, sterke verwijding van het colon bij een ernstige colitis, met systemische ziekte; risico op perforatie.","definition":"<p>Een <strong>toxisch megacolon</strong> komt voor bij colitis ulcerosa, de ziekte van Crohn en <em>C. difficile</em>-infectie. Het colon transversum is meer dan 6 cm breed op de foto. Opiaten en anticholinergica kunnen het uitlokken. Behandeling: intensieve medische therapie, zo nodig een spoedcolectomie.</p>","image_url":"","wiki_title":"Toxic megacolon","match":"een toxisch megacolon|toxisch megacolon","option_only":true},"primaire biliaire cholangitis":{"title":"Primaire biliaire cholangitis (PBC)","short":"PBC is een auto-immuunziekte waarbij de kleine galgangen in de lever worden vernietigd, vooral bij vrouwen van middelbare leeftijd.","definition":"<p>Kenmerken van <strong>PBC</strong> zijn vermoeidheid, jeuk, een verhoogd alkalisch fosfatase en antimitochondriale antistoffen (AMA). Behandeling met ursodeoxycholzuur, dat het beloop vertraagt.</p>","image_url":"","wiki_title":"Primary biliary cholangitis","match":"primaire biliaire cholangitis|pbc|primaire biliaire cirrose","option_only":true},"child-pugh score":{"title":"Child-Pugh-score","short":"De Child-Pugh-score beoordeelt de ernst van levercirrose aan de hand van bilirubine, albumine, INR, ascites en encefalopathie.","definition":"<p>De <strong>Child-Pugh</strong>-klasse (A, B of C) voorspelt de overleving en het operatierisico. Voor de wachtlijst voor levertransplantatie wordt de MELD-score gebruikt (bilirubine, INR, creatinine en natrium).</p>","image_url":"","wiki_title":"Child–Pugh score","match":"child-pugh score|child-pugh|meld-score","option_only":true},"levercyste":{"title":"Levercyste","short":"Een levercyste is een met vocht gevulde holte in de lever, meestal goedaardig en zonder klachten.","definition":"<p>Eenvoudige <strong>levercysten</strong> zijn een toevalsbevinding bij echo of CT. Grote cysten of polycysteuze leverziekte (vaak samen met cystenieren) kunnen klachten geven door hun omvang. Een echinococcuscyste (lintworm) heeft vaak tussenschotten en verkalkingen.</p>","image_url":"","wiki_title":"Hepatic cyst","match":"levercyste|levercysten|polycysteuze leverziekte","option_only":true},"lactulose":{"title":"Lactulose","short":"Lactulose is een niet-opneembare suiker die als osmotisch laxans werkt en bij hepatische encefalopathie de ammoniakspiegel verlaagt.","definition":"<p>In het colon wordt <strong>lactulose</strong> door bacteriën afgebroken tot zuren. Daardoor wordt ammoniak (NH₃) omgezet in ammonium (NH₄⁺), dat niet wordt opgenomen. Bijwerkingen zijn winderigheid en krampen.</p>","image_url":"","wiki_title":"Lactulose","match":"lactulose","option_only":true},"mri enteroclyse":{"title":"MR-enterografie","short":"Bij MR-enterografie wordt de dunne darm met MRI afgebeeld na het drinken (of via een sonde inlopen) van contrastvloeistof.","definition":"<p><strong>MR-enterografie</strong> is het standaardonderzoek om de uitgebreidheid en activiteit van de ziekte van Crohn in de dunne darm vast te stellen, zonder stralingsbelasting.</p>","image_url":"","wiki_title":"Magnetic resonance enterography","match":"mri enteroclyse|mr-enterografie|mr-enteroclyse","option_only":true},"episiotomie":{"title":"Episiotomie en perineumruptuur","short":"Een episiotomie is een knip in het perineum tijdens de bevalling; een perineumruptuur is een spontane scheur, ingedeeld in vier graden.","definition":"<p>Bij een <strong>derde- of vierdegraads ruptuur</strong> (totaalruptuur) is de anale sluitspier, en bij de vierde graad ook het anaalslijmvlies, betrokken; dit moet zorgvuldig worden gehecht om incontinentie te voorkomen. Een mediolaterale episiotomie wordt gedaan bij foetale nood of een kunstverlossing.</p>","image_url":"","wiki_title":"Episiotomy","match":"episiotomie|perineumruptuur|totaalruptuur","option_only":true},"α-amylase":{"title":"Amylase","short":"Amylase is een enzym uit speekselklieren en pancreas dat zetmeel afbreekt; een verhoogde bloedwaarde past o.a. bij pancreatitis.","definition":"<p><strong>Amylase</strong> splitst α-1,4-bindingen in zetmeel. Bij acute pancreatitis stijgt het, maar het is minder specifiek dan lipase (ook verhoogd bij o.a. parotitis, darmperforatie en nierfalen) en normaliseert sneller.</p>","image_url":"","wiki_title":"Amylase","match":"α-amylase","option_only":true},"anti-tnf-medicatie":{"title":"Infliximab","short":"Infliximab is een monoklonaal antilichaam tegen TNF-α, gebruikt bij o.a. de ziekte van Crohn, colitis ulcerosa en reumatoïde artritis.","definition":"<p><strong>TNF-α-remmers</strong> zoals infliximab, adalimumab en etanercept remmen een centraal pro-inflammatoir cytokine. Ze worden gebruikt bij IBD, reumatoïde artritis, spondyloartritis en psoriasis. Doordat ze de cellulaire afweer verzwakken, kan latente tuberculose reactiveren; daarom wordt vooraf gescreend. Ook het risico op andere infecties is verhoogd.</p>","image_url":"","wiki_title":"Infliximab","match":"anti-tnf-medicatie","option_only":true},"een abces":{"title":"Granuloom","short":"Een granuloom is een ophoping van geactiveerde macrofagen (epitheloïde cellen), vaak met reuscellen, rond een moeilijk afbreekbare prikkel.","definition":"<p><strong>Granulomen</strong> ontstaan bij tuberculose (met centrale verkazing), sarcoïdose, de ziekte van Crohn, schimmelinfecties en reacties op vreemd materiaal. Ze ontstaan via Th1-cellen en IFN-γ. Een abces bestaat juist uit granulocyten en pus.</p>","image_url":"","wiki_title":"Granuloma","match":"een abces","option_only":true},"een ulcus":{"title":"Granuloom","short":"Een granuloom is een ophoping van geactiveerde macrofagen (epitheloïde cellen), vaak met reuscellen, rond een moeilijk afbreekbare prikkel.","definition":"<p><strong>Granulomen</strong> ontstaan bij tuberculose (met centrale verkazing), sarcoïdose, de ziekte van Crohn, schimmelinfecties en reacties op vreemd materiaal. Ze ontstaan via Th1-cellen en IFN-γ. Een abces bestaat juist uit granulocyten en pus.</p>","image_url":"","wiki_title":"Granuloma","match":"een ulcus","option_only":true},"een necrosehaard":{"title":"Granuloom","short":"Een granuloom is een ophoping van geactiveerde macrofagen (epitheloïde cellen), vaak met reuscellen, rond een moeilijk afbreekbare prikkel.","definition":"<p><strong>Granulomen</strong> ontstaan bij tuberculose (met centrale verkazing), sarcoïdose, de ziekte van Crohn, schimmelinfecties en reacties op vreemd materiaal. Ze ontstaan via Th1-cellen en IFN-γ. Een abces bestaat juist uit granulocyten en pus.</p>","image_url":"","wiki_title":"Granuloma","match":"een necrosehaard","option_only":true},"tuberculeuze granulomen":{"title":"Granuloom","short":"Een granuloom is een ophoping van geactiveerde macrofagen (epitheloïde cellen), vaak met reuscellen, rond een moeilijk afbreekbare prikkel.","definition":"<p><strong>Granulomen</strong> ontstaan bij tuberculose (met centrale verkazing), sarcoïdose, de ziekte van Crohn, schimmelinfecties en reacties op vreemd materiaal. Ze ontstaan via Th1-cellen en IFN-γ. Een abces bestaat juist uit granulocyten en pus.</p>","image_url":"","wiki_title":"Granuloma","match":"tuberculeuze granulomen","option_only":true},"inflammatoire poliep":{"title":"Poliepen van het colon","short":"Darmpoliepen worden ingedeeld in adenomen (voorstadium van kanker), hyperplastische en serrated poliepen, inflammatoire en juveniele (hamartomateuze) poliepen.","definition":"<p>De meeste darmkankers ontstaan uit een <strong>adenoom</strong> (adenoom-carcinoomsequentie). Kleine hyperplastische poliepen in het rectosigmoïd zijn onschuldig; sessiele serrated laesies kunnen wel ontaarden. Juveniele poliepen zijn hamartomen; bij meerdere poliepen is een erfelijk syndroom mogelijk.</p>","image_url":"","wiki_title":"Colorectal polyp","match":"inflammatoire poliep","option_only":true},"juveniele poliep":{"title":"Poliepen van het colon","short":"Darmpoliepen worden ingedeeld in adenomen (voorstadium van kanker), hyperplastische en serrated poliepen, inflammatoire en juveniele (hamartomateuze) poliepen.","definition":"<p>De meeste darmkankers ontstaan uit een <strong>adenoom</strong> (adenoom-carcinoomsequentie). Kleine hyperplastische poliepen in het rectosigmoïd zijn onschuldig; sessiele serrated laesies kunnen wel ontaarden. Juveniele poliepen zijn hamartomen; bij meerdere poliepen is een erfelijk syndroom mogelijk.</p>","image_url":"","wiki_title":"Colorectal polyp","match":"juveniele poliep","option_only":true},"prothrombinetijd":{"title":"Stollingstijden (PT en aPTT)","short":"De protrombinetijd (PT/INR) meet de extrinsieke route en de aPTT de intrinsieke route van de stolling.","definition":"<p>Een verlengde <strong>PT/INR</strong> komt voor bij vitamine K-antagonisten, vitamine K-tekort en leverziekte (factor VII heeft de kortste halfwaardetijd, dus PT is een goede maat voor de leversyntheefunctie). Een verlengde <strong>aPTT</strong> past bij heparine, hemofilie A en B, en het lupusanticoagulans.</p>","image_url":"","wiki_title":"Prothrombin time","match":"prothrombinetijd","option_only":true},"a. hepatica sinistra":{"title":"A. hepatica propria, dextra en sinistra","short":"De a. hepatica propria splitst zich in een rechter- en linkertak die de leverhelften van zuurstofrijk bloed voorzien.","definition":"<p>De lever krijgt ongeveer 25% van het bloed via de <strong>a. hepatica</strong> (zuurstofrijk) en 75% via de v. portae. Galwegen zijn voor hun bloedvoorziening vrijwel alleen van de a. hepatica afhankelijk, waardoor trombose na een levertransplantatie galwegschade geeft.</p>","image_url":"","wiki_title":"Hepatic artery proper","match":"a. hepatica sinistra","option_only":true},"alcoholische levercirrose":{"title":"Levercirrose","short":"Bij levercirrose is het leverweefsel vervangen door bindweefsel en regeneratieknobbels, met verlies van leverfunctie en portale hypertensie.","definition":"<p>Oorzaken van <strong>cirrose</strong> zijn o.a. alcohol, NASH, chronische hepatitis B en C, auto-immuunziekten en hemochromatose. Gevolgen: ascites, varices met bloedingen, hepatische encefalopathie, icterus, stollingsstoornissen en een verhoogd risico op hepatocellulair carcinoom. Ernst wordt ingedeeld met Child-Pugh of MELD.</p>","image_url":"","wiki_title":"Cirrhosis","match":"alcoholische levercirrose","option_only":true},"ercp met papillotomie":{"title":"ERCP","short":"Bij een ERCP wordt via een endoscoop in het duodenum de papil van Vater opgezocht, waarna galwegen en pancreasgang met contrast kunnen worden afgebeeld en behandeld.","definition":"<p>Met een <strong>ERCP</strong> kunnen na een papillotomie galstenen worden verwijderd en stents worden geplaatst. De belangrijkste complicatie is een post-ERCP-pancreatitis; daarnaast bloeding, perforatie en cholangitis.</p>","image_url":"","wiki_title":"Endoscopic retrograde cholangiopancreatography","match":"ercp met papillotomie","option_only":true},"verwijzing radioloog voor mrcp":{"title":"MRCP","short":"MRCP is een MRI-onderzoek dat galwegen en pancreasgang in beeld brengt zonder contrast of ingreep.","definition":"<p><strong>MRCP</strong> wordt gebruikt bij verdenking op galwegstenen, PSC en tumoren. Als er een behandeling nodig is (steen verwijderen, stent plaatsen), volgt een ERCP.</p>","image_url":"","wiki_title":"Magnetic resonance cholangiopancreatography","match":"verwijzing radioloog voor mrcp","option_only":true},"colon inloop foto (x-colon)":{"title":"Colon-inloopfoto","short":"Bij een colon-inloopfoto wordt het colon met contrast via de anus gevuld en op röntgenfoto's afgebeeld.","definition":"<p>Een <strong>colon-inloop</strong> is grotendeels vervangen door coloscopie en CT-colografie, maar wordt nog gebruikt om fistels, stricturen of naadlekkage in beeld te brengen (met wateroplosbaar contrast).</p>","image_url":"","wiki_title":"Lower gastrointestinal series","match":"colon inloop foto (x-colon)","option_only":true},"pantoprazol bolusinjectie":{"title":"Protonpompremmer (PPI)","short":"Protonpompremmers remmen de H⁺/K⁺-ATPase van de pariëtale cellen en zijn de krachtigste remmers van de maagzuurproductie.","definition":"<p><strong>PPI's</strong> worden gebruikt bij refluxziekte, ulcera, H. pylori-eradicatie, maagbescherming bij NSAID's en een bloedend ulcus (intraveneus). Langdurig gebruik hangt samen met hypomagnesiëmie, vitamine B12-tekort, fracturen en infecties (<em>C. difficile</em>).</p>","image_url":"","wiki_title":"Proton-pump inhibitor","match":"pantoprazol bolusinjectie","option_only":true},"octreotide bolusinjectie":{"title":"Octreotide","short":"Octreotide is een somatostatineanaloog dat de afgifte van veel hormonen remt en de splanchnische doorbloeding vermindert.","definition":"<p><strong>Octreotide</strong> wordt gebruikt bij varicesbloedingen, neuro-endocriene tumoren (carcinoïdsyndroom), acromegalie en bepaalde vormen van diarree. Het kan galstenen veroorzaken.</p>","image_url":"","wiki_title":"Octreotide","match":"octreotide bolusinjectie","option_only":true},"non-alcoholische steato-hepatitis":{"title":"NAFLD en NASH (MASLD/MASH)","short":"Bij NAFLD (nu MASLD) is er vet in de lever zonder overmatig alcoholgebruik; bij NASH (MASH) gaat dat samen met ontsteking en levercelschade.","definition":"<p><strong>NAFLD</strong> hangt sterk samen met overgewicht, diabetes type 2 en het metabool syndroom. NASH kan overgaan in fibrose, cirrose en levercelkanker. De belangrijkste behandeling is gewichtsverlies.</p>","image_url":"","wiki_title":"Non-alcoholic fatty liver disease","match":"non-alcoholische steato-hepatitis","option_only":true},"primaire biliaire cirrhose (pbc)":{"title":"Primaire biliaire cholangitis (PBC)","short":"PBC is een auto-immuunziekte waarbij de kleine galgangen in de lever worden vernietigd, vooral bij vrouwen van middelbare leeftijd.","definition":"<p>Kenmerken van <strong>PBC</strong> zijn vermoeidheid, jeuk, een verhoogd alkalisch fosfatase en antimitochondriale antistoffen (AMA). Behandeling met ursodeoxycholzuur, dat het beloop vertraagt.</p>","image_url":"","wiki_title":"Primary biliary cholangitis","match":"primaire biliaire cirrhose (pbc)","option_only":true},"psc":{"title":"primaire scleroserende cholangitis","short":"Primaire scleroserende cholangitis (PSC) is een chronische ontsteking met fibrose van de galwegen, sterk geassocieerd met colitis ulcerosa; kenmerkend zijn strengvormige galgangvernauwingen ('kralensnoer').","definition":"<p><b>Primaire scleroserende cholangitis</b> (PSC) is een progressieve ontsteking en fibrose van de intra- en extrahepatische galwegen, met multifocale stricturen ('kralensnoer' op MRCP). Sterk geassocieerd met <b>colitis ulcerosa</b>. Verhoogt het risico op cholangiocarcinoom. Presenteert met cholestase (verhoogd bilirubine, γGT, AF).</p>","image_url":"","wiki_title":"Primary sclerosing cholangitis","match":"psc","option_only":true},"appendicits":{"title":"Appendicitis","short":"Appendicitis is een ontsteking van de appendix, met buikpijn die vaak rond de navel begint en naar rechtsonder trekt.","definition":"<p>Bij <strong>appendicitis</strong> raakt het lumen van de appendix afgesloten (bijv. door een fecoliet of lymfoïde hyperplasie), waarna ontsteking en infectie volgen. Klachten: pijn eerst rond de navel, later rechtsonder (McBurney), misselijkheid, koorts en lokale peritoneale prikkeling. Zonder behandeling kan perforatie optreden. Diagnose met echo en/of CT; behandeling meestal appendectomie.</p>","image_url":"","wiki_title":"Appendicitis","match":"appendicits","option_only":true},"hemorrhoiden":{"title":"Aambeien (hemorroïden)","short":"Aambeien zijn verwijde vaatkussentjes in het anaalkanaal die kunnen bloeden, uitzakken of jeuken.","definition":"<p>Bij <strong>inwendige hemorroïden</strong> (boven de linea dentata) is helderrood bloed op de ontlasting de belangrijkste klacht, meestal zonder pijn. Uitwendige aambeien kunnen trombose geven met hevige pijn. Risicofactoren: obstipatie, persen, zwangerschap. Bij rectaal bloedverlies boven ongeveer 50 jaar moet een coloncarcinoom worden uitgesloten.</p>","image_url":"","wiki_title":"Hemorrhoid","match":"hemorrhoiden","option_only":true},"refluxoesophagus":{"title":"Gastro-oesofageale reflux","short":"Bij refluxklachten stroomt maaginhoud terug in de slokdarm, met zuurbranden en oprispingen.","definition":"<p><strong>Gastro-oesofageale refluxziekte</strong> ontstaat bij een tekortschietende onderste slokdarmsfincter, een hiatus hernia of verhoogde druk in de buik (overgewicht, zwangerschap). Klachten zijn zuurbranden achter het borstbeen en zure oprispingen, soms hoesten of heesheid. Complicaties: oesofagitis, stenose en Barrett-slokdarm. Behandeling met leefstijladviezen en protonpompremmers.</p>","image_url":"","wiki_title":"Gastroesophageal reflux disease","match":"refluxoesophagus","option_only":true},"acute hepatitis c":{"title":"Hepatitis C","short":"Hepatitis C is een via bloed overgedragen RNA-virus dat vaak chronisch wordt en tot cirrose en levercelkanker kan leiden.","definition":"<p>Het <strong>hepatitis C-virus</strong> (flavivirus) wordt vooral via bloed overgedragen (drugsgebruik met naalden, vroeger transfusies). Een acute infectie verloopt meestal zonder klachten, maar wordt in de meerderheid chronisch. Na jaren kunnen fibrose, cirrose en hepatocellulair carcinoom ontstaan. Er is geen vaccin, maar direct werkende antivirale middelen genezen de infectie in vrijwel alle gevallen.</p>","image_url":"","wiki_title":"Hepatitis C","match":"acute hepatitis c","option_only":true},"hepatitis a infectie":{"title":"Hepatitis A","short":"Hepatitis A is een fecaal-oraal overgedragen virale leverontsteking die acuut verloopt en nooit chronisch wordt.","definition":"<p><strong>Hepatitis A</strong> wordt veroorzaakt door het hepatitis A-virus, een niet-omhuld RNA-virus dat fecaal-oraal wordt overgedragen (besmet water en voedsel, reizen).</p><p>Het geeft een acute hepatitis met moeheid, misselijkheid, geelzucht en verhoogde transaminasen; bij jonge kinderen vaak zonder klachten. Hepatitis A wordt <em>niet chronisch</em> en geeft levenslange immuniteit. Er is een vaccin.</p>","image_url":"","wiki_title":"Hepatitis A","match":"hepatitis a infectie","option_only":true},"gastro-enteritis, mogelijk het norovirus":{"title":"Norovirus","short":"Norovirus is een zeer besmettelijk RNA-virus dat acute gastro-enteritis veroorzaakt met plotseling braken en diarree, vaak in uitbraken.","definition":"<p>Het <strong>norovirus</strong> is een niet-omhuld RNA-virus (calicivirus). Er zijn maar weinig deeltjes nodig voor infectie en het overleeft lang in de omgeving.</p><p>Het veroorzaakt acute gastro-enteritis met plotseling braken, waterige diarree en buikkrampen, die 1 à 3 dagen duurt. Uitbraken komen vooral voor in verpleeghuizen, ziekenhuizen en op cruiseschepen; handhygiëne is de belangrijkste maatregel.</p>","image_url":"","wiki_title":"Norovirus","match":"gastro-enteritis, mogelijk het norovirus","option_only":true},"endo-echografie":{"title":"Endo-echografie (EUS)","short":"Bij een endo-echografie zit een echokop op een endoscoop, waardoor organen vlak naast slokdarm, maag en duodenum van dichtbij kunnen worden afgebeeld en zo nodig gepuncteerd.","definition":"<p>Met <strong>EUS</strong> wordt o.a. de doorgroei van slokdarm-, maag- en pancreastumoren beoordeeld, worden kleine galstenen opgespoord en kunnen biopten en drainages van cysten worden uitgevoerd.</p>","image_url":"","wiki_title":"Endoscopic ultrasound","match":"endo-echografie|eus|eus, endoechografie|endoscopische echografie","option_only":true},"irritable bowel syndrome":{"title":"Prikkelbare darm syndroom","short":"Functionele darmstoornis met buikpijn en wisselend ontlastingspatroon zonder aantoonbare afwijkingen.","definition":"<p>Het <b>prikkelbare darm syndroom</b> (PDS/IBS) is een diagnose per uitsluiting: buikpijn en veranderd defecatiepatroon zonder alarmsymptomen of afwijkend onderzoek.</p>","image_url":"","wiki_title":"Irritable bowel syndrome","match":"irritable bowel syndrome","option_only":true},"eus, endoechografie":{"title":"Endo-echografie (EUS)","short":"Bij een endo-echografie zit een echokop op een endoscoop, waardoor organen vlak naast slokdarm, maag en duodenum van dichtbij kunnen worden afgebeeld en zo nodig gepuncteerd.","definition":"<p>Met <strong>EUS</strong> wordt o.a. de doorgroei van slokdarm-, maag- en pancreastumoren beoordeeld, worden kleine galstenen opgespoord en kunnen biopten en drainages van cysten worden uitgevoerd.</p>","image_url":"","wiki_title":"Endoscopic ultrasound","match":"eus, endoechografie","option_only":true},"galblaascarcinoom":{"title":"Galblaascarcinoom","short":"Het galblaascarcinoom is een zeldzame, agressieve tumor van de galblaas, vaak pas laat ontdekt.","definition":"<p>Risicofactoren zijn langdurige galstenen, een porseleingalblaas en grote galblaaspoliepen (&gt; 1 cm). Soms wordt het toevallig gevonden na een cholecystectomie.</p>","image_url":"","wiki_title":"Gallbladder cancer","match":"galblaascarcinoom","option_only":true},"colorectaal carcinoom":{"title":"Colorectaal carcinoom","short":"Het colorectaal carcinoom is een adenocarcinoom van de dikke darm, meestal ontstaan uit een adenoom.","definition":"<p>Een tumor <strong>links</strong> geeft vaak een veranderd ontlastingspatroon en bloed bij de ontlasting; een tumor <strong>rechts</strong> vaker een ijzergebreksanemie. Risicofactoren: leeftijd, familie, IBD, Lynch-syndroom en FAP. In Nederland is er een bevolkingsonderzoek met een FIT-test.</p>","image_url":"","wiki_title":"Colorectal cancer","match":"colorectaal carcinoom|darmkanker|coloncarcinoom|rectumcarcinoom","option_only":true},"tuberculeuze colitis":{"title":"Darmtuberculose","short":"Darmtuberculose treft vooral het ileocaecale gebied en kan sterk lijken op de ziekte van Crohn.","definition":"<p>Bij <strong>abdominale tuberculose</strong> zijn er buikpijn, koorts, gewichtsverlies en soms ascites. Het onderscheid met Crohn is belangrijk, omdat behandeling met immunosuppressie bij tbc gevaarlijk is.</p>","image_url":"","wiki_title":"Abdominal tuberculosis","match":"tuberculeuze colitis|darmtuberculose|abdominale tuberculose","option_only":true},"zinksulfaat":{"title":"Zink","short":"Zink is een spoorelement dat nodig is voor veel enzymen, wondgenezing en de afweer.","definition":"<p>Een <strong>zinktekort</strong> geeft huidafwijkingen rond mond en anus (acrodermatitis enteropathica), haaruitval, diarree, smaakstoornissen en slechte wondgenezing. Het komt voor bij malabsorptie, alcoholisme en langdurige parenterale voeding.</p>","image_url":"","wiki_title":"Zinc deficiency","match":"zinksulfaat|zink|zinktekort","option_only":true},"sigmoidcarcinoom":{"title":"Colorectaal carcinoom","short":"Het colorectaal carcinoom is een adenocarcinoom van de dikke darm, meestal ontstaan uit een adenoom.","definition":"<p>Een tumor <strong>links</strong> geeft vaak een veranderd ontlastingspatroon en bloed bij de ontlasting; een tumor <strong>rechts</strong> vaker een ijzergebreksanemie. Risicofactoren: leeftijd, familie, IBD, Lynch-syndroom en FAP. In Nederland is er een bevolkingsonderzoek met een FIT-test.</p>","image_url":"","wiki_title":"Colorectal cancer","match":"sigmoidcarcinoom","option_only":true},"helicobacter pylori positieve gastritis":{"title":"Helicobacter pylori-gastritis","short":"Helicobacter pylori is een bacterie die het maagslijmvlies koloniseert en gastritis, ulcera, maagkanker en MALT-lymfoom kan veroorzaken.","definition":"<p>Diagnose met een ademtest, een feceantigeentest of biopten. Eradicatie met een protonpompremmer en twee antibiotica. <em>H. pylori</em> geeft vooral een gastritis in het antrum.</p>","image_url":"","wiki_title":"Helicobacter pylori","match":"helicobacter pylori positieve gastritis|helicobacter pylori|h. pylori","option_only":true},"vlokatrofie bij coeliakie":{"title":"Coeliakie","short":"Coeliakie is een auto-immuunreactie op gluten, met vlokatrofie in de dunne darm en malabsorptie.","definition":"<p>Klachten van <strong>coeliakie</strong> zijn diarree, buikpijn, gewichtsverlies, ijzergebrek en bij kinderen groeiachterstand. Diagnose met anti-tTG-IgA (met totaal IgA) en een dunnedarmbiopt. Behandeling: een levenslang glutenvrij dieet.</p>","image_url":"","wiki_title":"Coeliac disease","match":"vlokatrofie bij coeliakie|coeliakie|glutenintolerantie","option_only":true},"translocaties":{"title":"Chromosoomafwijkingen","short":"Chromosoomafwijkingen zijn numeriek (te veel of te weinig chromosomen, aneuploïdie) of structureel (zoals translocaties, deleties en duplicaties).","definition":"<p>Bij een <strong>translocatie</strong> wordt een stuk chromosoom verplaatst. Gebalanceerde dragers zijn gezond, maar hebben een verhoogd risico op miskramen. In tumoren geven translocaties fusiegenen, zoals BCR-ABL bij CML.</p>","image_url":"","wiki_title":"Chromosomal translocation","match":"translocaties|translocatie|extra chromosomen|verlies van chromosomen|aneuploïdie","option_only":true},"ouderdom":{"title":"Risicofactoren (leeftijd, erfelijkheid, medicatie)","short":"Leeftijd, erfelijke aanleg en medicatie zijn algemene risicofactoren voor veel aandoeningen.","definition":"<p>Bij het beoordelen van risicofactoren wordt onderscheid gemaakt tussen <strong>niet-beïnvloedbare</strong> (leeftijd, geslacht, erfelijkheid) en <strong>beïnvloedbare</strong> factoren (roken, voeding, beweging, medicatie).</p>","image_url":"","wiki_title":"","match":"ouderdom|erfelijke aanleg|medicatie","option_only":true}};
